INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', 'アルファベットの「Q」の小文字として正しいものはどれか。', '["q","p","g","d"]', 0, 1, 'Qの小文字はqです。pと混同しやすいので、形をしっかり覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスをします」を英語にする際、適切なものはどれか。', '["I play tennis.","I am play tennis.","I plays tennis.","I am tennis."]', 0, 1, '一般動詞の文では、主語がIのとき、動詞は原形を使います。amはbe動詞なので使いません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたは学生です」を英語にしたとき、空欄に入るべき語は？ You ( ) a student.', '["are","am","is","be"]', 0, 1, '主語がyouのとき、be動詞はareを使います。amはIのとき、isは三人称単数のときに使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はケンです」を英語にしたとき、正しいものはどれか。', '["I am Ken.","I are Ken.","I is Ken.","I Ken."]', 0, 1, '主語がIのとき、be動詞はamを使います。I am Ken.が正しい文です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「これはペンです」を英語にしたとき、正しいものはどれか。', '["This is a pen.","This am a pen.","This are a pen.","This pen is."]', 0, 1, 'Thisは三人称単数なので、be動詞はisを使います。また、数えられる名詞の前にはaを忘れないようにしましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はサッカーが好きではありません」を英語にする際、適切なものはどれか。', '["I do not like soccer.","I am not like soccer.","I no like soccer.","I not like soccer."]', 0, 2, '一般動詞の否定文は、動詞の前にdo not (don''t)を置きます。am notはbe動詞の否定文で使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたはテニスをしますか？」という疑問文として正しいものはどれか。', '["Do you play tennis?","Are you play tennis?","You play tennis?","Do you playing tennis?"]', 0, 2, '一般動詞の疑問文は文頭にDoを置きます。Do you play tennis?が正しい形です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「りんご」の複数形として正しいものはどれか。', '["apples","applees","appls","apple"]', 0, 1, '多くの名詞は語尾にsをつけることで複数形になります。appleの複数形はapplesです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「箱」の複数形として正しいものはどれか。', '["boxes","boxs","boxies","box"]', 0, 2, 'xで終わる名詞の複数形は、esをつけてboxesとします。ルールをしっかり覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「おはよう」を意味する英語として正しいものはどれか。', '["Good morning.","Good afternoon.","Good evening.","Good night."]', 0, 1, 'Good morning.は朝の挨拶です。時間帯による挨拶の違いは基本中の基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私は学生ではありません」を英語にしたとき、正しいものはどれか。', '["I am not a student.","I not am a student.","I am no a student.","I don''t a student."]', 0, 2, 'be動詞の否定文は、be動詞の直後にnotを置きます。I am not a student.が正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたはテニスをしますか？」への否定の答え方として正しいものはどれか。', '["No, I do not.","No, I am not.","No, I don''t play.","No, I not."]', 0, 2, 'Doで聞かれた疑問文にはDoで答えます。No, I do not. (No, I don''t.)が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', 'アルファベットの「f」の次に来る文字はどれか。', '["g","e","h","i"]', 0, 1, 'アルファベット順はa, b, c, d, e, f, g...です。順番を正確に覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私は本を持っています」を英語にしたとき、正しいものはどれか。', '["I have a book.","I has a book.","I am have a book.","I do have a book."]', 0, 2, '主語がIのとき、haveを使います。hasは三人称単数のときに使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたはテニスをしますか？」に対する肯定の答えとして正しいものはどれか。', '["Yes, I do.","Yes, I am.","Yes, I play.","Yes, I do play."]', 0, 2, 'Doで聞かれた疑問文にはDoで答えます。Yes, I do.が最も自然で正しい答え方です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「これは何ですか？」を英語にしたとき、正しいものはどれか。', '["What is this?","What this is?","Is this what?","What are this?"]', 0, 2, '疑問詞を使った疑問文は、疑問詞を文頭に置き、その後にbe動詞を続けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「バス」の複数形として正しいものはどれか。', '["buses","buss","busies","bus"]', 0, 2, 'sで終わる名詞の複数形はesをつけます。busesとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私は英語を勉強します」を英語にしたとき、正しいものはどれか。', '["I study English.","I study english.","I study the English.","I am study English."]', 0, 2, '教科名（English）の頭文字は必ず大文字で書きます。また、studyは一般動詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私は空腹です」を英語にしたとき、適切なものはどれか。', '["I am hungry.","I hungry.","I have hungry.","I do hungry."]', 0, 2, '形容詞（hungry）を述語にするにはbe動詞が必要です。I am hungry.が正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスが好きです」を英語にしたとき、正しいものはどれか。', '["I like tennis.","I like a tennis.","I like the tennis.","I am like tennis."]', 0, 2, 'スポーツ名には基本的に冠詞（aやthe）はつきません。I like tennis.が正しいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたは誰ですか？」を英語にしたとき、正しいものはどれか。', '["Who are you?","Who you are?","Who is you?","Who am you?"]', 0, 2, 'Whoで始まる疑問文は、be動詞を主語の前に置きます。Who are you?が正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はピアノを弾きます」を英語にしたとき、正しいものはどれか。', '["I play the piano.","I play piano.","I play a piano.","I play pianos."]', 0, 3, '楽器を弾くという表現では、playの後にtheをつけます。play the pianoが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスをしません」を短縮形を使って表すとどれか。', '["I don''t play tennis.","I do not play tennis.","I not play tennis.","I don''t playing tennis."]', 0, 2, 'do notの短縮形はdon''tです。否定文の基本形を覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたはテニスをしますか？」という質問に対し、「はい、します」と答える正しい表現はどれか。', '["Yes, I do.","Yes, I am.","Yes, I play.","Yes, I do play."]', 0, 2, 'Doで始まる疑問文にはDoで答えるのがルールです。Yes, I do.が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私は学生です」の否定文として正しいものはどれか。', '["I am not a student.","I am no a student.","I not am a student.","I don''t a student."]', 0, 2, 'be動詞の否定文は、be動詞の後にnotを置きます。I am not...が正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「これはペンですか？」という疑問文として正しいものはどれか。', '["Is this a pen?","This is a pen?","Is this pen?","Are this a pen?"]', 0, 2, 'be動詞の疑問文は、be動詞を文頭に置きます。Is this a pen?が正しい語順です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「あなたはテニスをしますか？」という質問に対し、「いいえ、しません」と答える正しい表現はどれか。', '["No, I don''t.","No, I am not.","No, I not.","No, I don''t play."]', 0, 2, 'Doで聞かれた疑問文にはDoで答えます。否定の場合はNo, I do not. (No, I don''t.)です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスをします」の疑問文として正しいものはどれか。', '["Do you play tennis?","Are you play tennis?","You play tennis?","Do you playing tennis?"]', 0, 2, '一般動詞の疑問文は文頭にDoを置きます。Do you play tennis?が正しい形です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスをしません」を英語にしたとき、正しいものはどれか。', '["I do not play tennis.","I am not play tennis.","I not play tennis.","I no play tennis."]', 0, 2, '一般動詞の否定文はdo notを使います。am notはbe動詞の否定文で使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'english', '「私はテニスをします」を英語にしたとき、正しいものはどれか。', '["I play tennis.","I am play tennis.","I plays tennis.","I am tennis."]', 0, 1, '一般動詞の文では、主語がIのとき動詞は原形です。amはbe動詞なので使いません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「これは何ですか。」を英語にする際、空所に当てはまる語は？ What ( ) this?', '["is","are","do","does"]', 0, 1, 'What is this? で「これは何ですか」という定型表現です。主語が this（単数）なので is を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はだれですか。」を英語にする際、空所に当てはまる語は？ ( ) is he?', '["What","Who","Where","How"]', 1, 1, '人物を尋ねる疑問詞は Who です。What は「何」、Where は「どこ」、How は「どのような」を意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「あなたはどこに住んでいますか。」を英語にする際、空所に当てはまる語は？ ( ) do you live?', '["What","Who","Where","How"]', 2, 1, '場所を尋ねる疑問詞は Where です。live（住む）という場所に関連する動詞があるため、Where が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「お元気ですか。」を英語にする際、空所に当てはまる語は？ ( ) are you?', '["What","Who","Where","How"]', 3, 1, '相手の状態を尋ねる「お元気ですか」は How are you? です。How は状態や手段を尋ねる際によく使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ドアを開けなさい。」という命令文として正しいものはどれか。', '["Open the door.","You open the door.","Opens the door.","To open the door."]', 0, 1, '命令文は動詞の原形から始めます。主語の You は省略するのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ここで走ってはいけません。」という禁止の命令文として正しいものはどれか。', '["No run here.","Don''t run here.","Not run here.","Doesn''t run here."]', 1, 1, '禁止の命令文は「Don''t ＋動詞の原形」で作ります。Don''t run here. で「ここで走るな」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はテニスをします。」を英語にする際、空所に当てはまる語は？ He ( ) tennis.', '["play","plays","playing","played"]', 1, 2, '主語が三人称単数（He）で、現在形なので、動詞に s をつける必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女は英語を話します。」を英語にする際、空所に当てはまる語は？ She ( ) English.', '["speak","speaks","speaking","to speak"]', 1, 2, 'She（三人称単数）が主語の肯定文なので、動詞 speak に s をつけて speaks とします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はサッカーが好きではありません。」を英語にする際、空所に当てはまる語は？ He ( ) like soccer.', '["don''t","doesn''t","isn''t","not"]', 1, 2, '三人称単数の否定文は doesn''t ＋動詞の原形を使います。don''t は I や you などに使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はピアノを弾きますか。」を英語にする際、空所に当てはまる語は？ ( ) she play the piano?', '["Do","Does","Is","Are"]', 1, 2, '三人称単数の疑問文は Does で始めます。Does を使うと、動詞は必ず原形（play）になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「あれは彼の本です。」の「彼の」にあたる語は？ That is ( ) book.', '["he","him","his","he''s"]', 2, 1, '「彼の」という所有格は his です。he は主格、him は目的格です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「これは彼女のペンです。」の「彼女の」にあたる語は？ This is ( ) pen.', '["she","her","hers","she''s"]', 1, 1, '「彼女の」という所有格は her です。hers は「彼女のもの」という所有代名詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「それは私の猫です。」の「それ」にあたる語は？ ( ) is my cat.', '["He","She","It","They"]', 2, 1, '人以外の動物や物を指す主語は It を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「静かにしなさい。」という命令文として正しいものはどれか。', '["Be quiet.","Is quiet.","You are quiet.","Do quiet."]', 0, 2, '形容詞（quiet）を伴う命令文は Be ＋形容詞を使います。Be quiet. で「静かにしなさい」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ケンはテニスをしますか。」に対する答えとして正しいものは？ Does Ken play tennis?', '["Yes, he does.","Yes, he is.","Yes, Ken play.","Yes, he plays."]', 0, 2, 'Does で聞かれたら Does で答えます。また、Ken は he に置き換えて答えるのが一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「あなたはだれですか。」を英語にする際、正しいものは？', '["Who are you?","Who is you?","Who do you?","Who does you?"]', 0, 1, 'you に対応する be 動詞は are です。Who are you? で「あなたはだれですか」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は何を食べますか。」を英語にする際、空所に当てはまる語は？ What ( ) he eat?', '["do","does","is","are"]', 1, 2, '主語が he（三人称単数）なので、疑問文を作る助動詞には does を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ここに来なさい。」を英語にする際、空所に当てはまる語は？ ( ) here.', '["Come","Comes","Coming","To come"]', 0, 1, '命令文は動詞の原形で始めます。Come が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「その本を読まないでください。」（丁寧な禁止）を英語にする際、空所に当てはまる語は？ ( ) read the book.', '["Don''t","Doesn''t","No","Not"]', 0, 2, '否定の命令文は Don''t で始めます。Don''t read the book. で「その本を読まないで」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は毎日勉強します。」を英語にする際、空所に当てはまる語は？ He ( ) every day.', '["study","studys","studies","studying"]', 2, 3, 'study は子音字＋y で終わる語なので、三人称単数現在形では y を i に変えて es をつけます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女は放課後何をするのですか。」を英語にする際、空所に当てはまる語は？ What ( ) she do after school?', '["do","does","is","are"]', 1, 2, '主語が she なので、疑問文を作る助動詞は does です。その後ろの do は原形になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「これは誰のペンですか。」を英語にする際、空所に当てはまる語は？ ( ) pen is this?', '["Who","What","Whose","Where"]', 2, 2, '「誰の～」と所有を尋ねる疑問詞は Whose です。Whose pen is this? で正しい文になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は親切です。」を英語にする際、空所に当てはまる語は？ He ( ) kind.', '["am","is","are","be"]', 1, 1, '主語が He なので、be 動詞は is を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「私は彼を知っています。」の「彼を」にあたる語は？ I know ( ).', '["he","his","him","he''s"]', 2, 2, '動詞の後ろに置くので、目的格の him を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はテニス部です。」の「彼女」にあたる語は？ ( ) is in the tennis club.', '["Her","She","Hers","She''s"]', 1, 1, '文の主語になるので、主格の She を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「そのドアを閉めなさい。」を英語にする際、正しいものは？', '["Close the door.","Closes the door.","Closing the door.","To close the door."]', 0, 1, '命令文は動詞の原形で始めます。Close が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は野球が好きですか。」という疑問文として正しいものは？', '["Does he like baseball?","Do he like baseball?","Is he like baseball?","Does he likes baseball?"]', 0, 2, 'Does で始め、動詞は原形（like）にします。Does he likes... は間違いです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「私の父は医者です。」の「私の」にあたる語は？ ( ) father is a doctor.', '["I","Me","My","Mine"]', 2, 1, '名詞の前に置くので、所有格の My を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ここで騒いではいけません。」を英語にする際、空所に当てはまる語は？ ( ) noisy here.', '["Don''t be","Doesn''t be","Not be","No be"]', 0, 3, '形容詞（noisy）を伴う禁止命令文は Don''t be ＋形容詞となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はどこで勉強しますか。」を英語にする際、空所に当てはまる語は？ Where ( ) he study?', '["do","does","is","are"]', 1, 2, '主語が he なので、疑問文を作る助動詞には does を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「これは誰のバッグですか。」を英語にする際、正しいものは？', '["Whose bag is this?","Who bag is this?","Who''s bag is this?","Whose is bag this?"]', 0, 2, 'Whose は「誰の」という意味で、その後に名詞（bag）を続けて使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は朝食を食べます。」を英語にする際、空所に当てはまる語は？ He ( ) breakfast.', '["eat","eats","eating","to eat"]', 1, 2, '主語が He（三人称単数）なので、動詞 eat に s をつけます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女は忙しくありません。」を英語にする際、空所に当てはまる語は？ She ( ) busy.', '["don''t","doesn''t","isn''t","not"]', 2, 2, 'be 動詞の否定文は be 動詞の後ろに not を置きます。She is not busy. が正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はテニスをしません。」を英語にする際、空所に当てはまる語は？ He ( ) play tennis.', '["don''t","doesn''t","isn''t","not"]', 1, 2, '一般動詞の否定文は doesn''t ＋動詞の原形を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「それは何色ですか。」を英語にする際、空所に当てはまる語は？ ( ) color is it?', '["What","Who","Where","How"]', 0, 2, '「何色の」は What color と言います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「親切にしなさい。」を英語にする際、空所に当てはまる語は？ ( ) kind.', '["Be","Is","Are","Do"]', 0, 2, '形容詞（kind）を伴う命令文は Be で始めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は何時に起きますか。」を英語にする際、空所に当てはまる語は？ What time ( ) he get up?', '["do","does","is","are"]', 1, 2, '主語が he なので、疑問文を作る助動詞は does です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女は英語を教えます。」を英語にする際、空所に当てはまる語は？ She ( ) English.', '["teach","teachs","teaches","teaching"]', 2, 3, 'ch で終わる動詞は、三人称単数現在形では es をつけます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼らに会ってください。」の「彼らに」にあたる語は？ Please meet ( ).', '["they","their","them","theirs"]', 2, 2, '動詞の後ろなので目的格の them を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「それは彼女のものです。」の「彼女のもの」にあたる語は？ It is ( ).', '["she","her","hers","she''s"]', 2, 2, '「彼女のもの」という意味の所有代名詞は hers です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ケンはどこに住んでいますか。」という疑問文として正しいものは？', '["Where does Ken live?","Where do Ken live?","Where is Ken live?","Where Ken lives?"]', 0, 2, '三人称単数の疑問文は Does を使い、動詞は原形（live）にします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はテニスをしますか。」に対する否定の答えとして正しいものは？', '["No, he doesn''t.","No, he don''t.","No, he isn''t.","No, he not."]', 0, 2, 'Does で聞かれたら doesn''t を使って否定します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「あれは誰の車ですか。」を英語にする際、正しいものは？', '["Whose car is that?","Who car is that?","Who''s car is that?","Whose is car that?"]', 0, 2, 'Whose ＋名詞（car）で「誰の車」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は忙しいですか。」を英語にする際、空所に当てはまる語は？ ( ) he busy?', '["Do","Does","Is","Are"]', 2, 1, 'be 動詞の疑問文は be 動詞を文頭に出します。主語が he なので Is を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はテニスをしません。」を英語にする際、空所に当てはまる語は？ She ( ) play tennis.', '["don''t","doesn''t","isn''t","not"]', 1, 2, '一般動詞の否定文は doesn''t ＋動詞の原形を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ドアを閉めないでください。」を英語にする際、空所に当てはまる語は？ ( ) close the door.', '["Don''t","Doesn''t","No","Not"]', 0, 2, '否定の命令文は Don''t で始めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は何が好きですか。」を英語にする際、空所に当てはまる語は？ What ( ) he like?', '["do","does","is","are"]', 1, 2, '主語が he なので、疑問文を作る助動詞は does です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「それは私のペンです。」の「私の」にあたる語は？ It is ( ) pen.', '["I","me","my","mine"]', 2, 1, '名詞の前に置くので所有格の my を使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は歌を歌います。」を英語にする際、正しいものは？', '["He sings a song.","He sing a song.","He sings song.","He sing songs."]', 0, 2, '主語が he なので動詞 sing に s をつけます。また、a song（歌）という数えられる名詞には a が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はテニス部ですか。」を英語にする際、空所に当てはまる語は？ ( ) she in the tennis club?', '["Do","Does","Is","Are"]', 2, 2, 'be 動詞の文なので、疑問文は Is を文頭に出します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はだれですか。」という問いに対する答えとして正しいものは？ Who is he?', '["He is Ken.","He is a student.","He is my friend.","All of them are correct."]', 3, 1, 'Who は人物を尋ねる疑問詞です。名前、職業、関係性など、人物を表す答えならすべて正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「ここで勉強しなさい。」を英語にする際、正しいものは？', '["Study here.","Studies here.","Studying here.","To study here."]', 0, 1, '命令文は動詞の原形で始めます。Study が適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はテニスをしますか。」に対する答えとして正しいものは？ Does he play tennis?', '["Yes, he does.","Yes, he plays.","Yes, he is.","Yes, he do."]', 0, 2, 'Does で聞かれたら Does で答えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「それは何ですか。」を英語にする際、正しいものは？', '["What is it?","What it is?","What does it?","What do it?"]', 0, 1, '疑問詞＋be動詞＋主語の語順になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は忙しいですか。」に対する否定の答えとして正しいものは？ Is he busy?', '["No, he isn''t.","No, he doesn''t.","No, he not.","No, he don''t."]', 0, 2, 'be 動詞で聞かれたら be 動詞で答えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はどこに住んでいますか。」を英語にする際、空所に当てはまる語は？ Where ( ) she live?', '["do","does","is","are"]', 1, 2, '主語が she なので、疑問文を作る助動詞は does です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼は親切な少年です。」の「彼の」にあたる語は？ He is ( ) kind boy.', '["a","his","he","him"]', 1, 2, '「彼の」という所有格は his です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「静かにしてはいけません。」を英語にする際、空所に当てはまる語は？ ( ) be noisy.', '["Don''t","Doesn''t","No","Not"]', 0, 3, '形容詞を伴う否定命令文は Don''t be ＋形容詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼はテニスをします。」の否定文として正しいものは？', '["He doesn''t play tennis.","He don''t play tennis.","He isn''t play tennis.","He not play tennis."]', 0, 2, '三人称単数の否定文は doesn''t ＋原形です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'english', '「彼女はだれですか。」を英語にする際、正しいものは？', '["Who is she?","Who she is?","Who does she?","Who do she?"]', 0, 1, '疑問詞＋be動詞＋主語の語順です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「私はテニスをすることができます」を英語にする際、正しいものはどれか。', '["I can play tennis.","I can playing tennis.","I can plays tennis.","I can to play tennis."]', 0, 1, '助動詞canの後ろは、必ず動詞の原形を置きます。playは原形なのでこれが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼はピアノを弾くことができません」を英語にする際、正しいものはどれか。', '["He can not plays the piano.","He can not play the piano.","He can not playing the piano.","He can not to play the piano."]', 1, 1, 'can not（cannot）の後ろも動詞の原形です。playが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「あなたは泳ぐことができますか？」という疑問文として正しいものはどれか。', '["Can you swim?","Do you can swim?","Are you can swim?","Can you to swim?"]', 0, 1, '助動詞canの疑問文は、Canを文の先頭に出します。動詞は原形のswimを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼は今、本を読んでいます」を英語にする際、正しいものはどれか。', '["He is read a book now.","He is reading a book now.","He reads a book now.","He is reads a book now."]', 1, 1, '現在進行形は「be動詞＋動詞のing形」で表します。主語がHeなのでisを使い、readingとします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼らはサッカーをしています」を英語にする際、正しいものはどれか。', '["They are play soccer.","They are playing soccer.","They are plays soccer.","They playing soccer."]', 1, 1, '現在進行形は「be動詞＋動詞のing形」です。Theyにはareを使い、playingとします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「私は昨日、テニスをしました」を英語にする際、正しいものはどれか。', '["I play tennis yesterday.","I played tennis yesterday.","I playing tennis yesterday.","I am played tennis yesterday."]', 1, 1, '過去の出来事は動詞を過去形にします。規則動詞playの過去形はplayedです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', 'studyの過去形として正しいものはどれか。', '["studyd","studyed","studied","studying"]', 2, 1, '子音字＋yで終わる動詞は、yをiに変えてedをつけます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼は昨日、勉強しました」を英語にする際、正しいものはどれか。', '["He studyed yesterday.","He studied yesterday.","He studys yesterday.","He is studied yesterday."]', 1, 1, '過去形では主語がHeでも動詞の形は変わりません。studyの過去形はstudiedです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「私は昨日、図書館に行きませんでした」を英語にする際、正しいものはどれか。', '["I not went to the library.","I didn''t go to the library.","I didn''t went to the library.","I don''t go to the library."]', 1, 2, '過去の否定文は「did not (didn''t) ＋ 動詞の原形」です。goが原形です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「あなたは昨日、何を食べましたか？」を英語にする際、正しいものはどれか。', '["What did you ate yesterday?","What did you eat yesterday?","What do you eat yesterday?","What you ate yesterday?"]', 1, 2, '過去の疑問文は「Did ＋ 主語 ＋ 動詞の原形」です。eatが原形です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「月曜日に」を英語で表すとき、正しい前置詞はどれか。', '["in Monday","on Monday","at Monday","to Monday"]', 1, 1, '曜日や特定の日の前には前置詞onを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「朝に」を英語で表すとき、正しい前置詞はどれか。', '["in the morning","on the morning","at the morning","to the morning"]', 0, 1, 'in the morning, in the afternoon, in the eveningはセットで覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「7時に」を英語で表すとき、正しい前置詞はどれか。', '["in 7 o''clock","on 7 o''clock","at 7 o''clock","to 7 o''clock"]', 2, 1, '時刻の前には前置詞atを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「10月に」を英語で表すとき、正しい前置詞はどれか。', '["in October","on October","at October","to October"]', 0, 1, '月や年、季節の前には前置詞inを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「2023年に」を英語で表すとき、正しい前置詞はどれか。', '["in 2023","on 2023","at 2023","to 2023"]', 0, 1, '年はinを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「5月5日に」を英語で表すとき、正しい前置詞はどれか。', '["in May 5","on May 5","at May 5","to May 5"]', 1, 2, '月だけでなく「日」が含まれる場合は、onを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「私はピアノを弾くことができます」の否定文として正しいものはどれか。', '["I can''t play the piano.","I don''t can play the piano.","I can not playing the piano.","I can''t to play the piano."]', 0, 1, '助動詞canの否定文はcanの直後にnotを置きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼は今、走っています」を英語にする際、正しいものはどれか。', '["He is runing now.","He is running now.","He is runing now.","He runs now."]', 1, 2, 'runのように「短母音＋子音字」で終わる語は、子音字を重ねてingをつけます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「あなたは今、何をしているのですか？」を英語にする際、正しいものはどれか。', '["What are you doing now?","What do you doing now?","What are you do now?","What you are doing now?"]', 0, 2, '現在進行形の疑問文は「be動詞 ＋ 主語 ＋ 動詞のing形」の語順です。', NULL);
