INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'english', '「彼は昨日、宿題をしませんでした」を英語にする際、正しいものはどれか。', '["He didn''t did his homework.","He didn''t do his homework.","He doesn''t do his homework.","He didn''t homework."]', 1, 2, 'did notの後は動詞の原形doを使います。', NULL);
