INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'english', '次の動詞の過去形として正しいものを選びなさい：meet', '["met","meeted","meet","meeting"]', 0, 2, 'meetの過去形は不規則変化のmetです。meetedという形はありません。', NULL);
