INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '作図において、コンパスの針を置く場所と鉛筆の先の間隔は何を表すか。', '["距離","角度","面積","体積"]', 0, 1, 'コンパスの針と鉛筆の距離は、描く円の半径（または2点間の距離）を表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '線対称な図形を折り返したとき、重なる点は何と呼ばれるか。', '["対応する点","対称の点","重なる点","頂点"]', 0, 1, '移動や対称によって重なる位置にある点を、対応する点といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '次のうち、空間図形ではないものはどれか。', '["長方形","円柱","球","正四面体"]', 0, 1, '長方形は平面図形であり、空間図形（立体）ではありません。', NULL);
