INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '度数分布表において、階級の端の値を何というか。', '["階級の境界","階級値","度数","範囲"]', 0, 2, '階級の区切りの値を階級の境界といいます。', NULL);
