INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', 'ヒストグラムにおいて、長方形の横の長さは何を表すか。', '["階級の幅","度数","階級値","累積度数"]', 0, 2, 'ヒストグラムでは、横軸が階級、縦軸が度数を表します。長方形の幅は階級の幅です。', NULL);
