INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '平行移動した図形と元の図形はどのような関係にあるか。', '["合同である","相似である","面積が異なる","形が異なる"]', 0, 1, '平行移動、回転移動、対称移動のいずれを行っても、図形の形や大きさは変わらないため、元の図形と合同です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '垂直二等分線上の任意の点は、線分の両端からどのような距離にあるか。', '["等しい距離","異なる距離","2倍の距離","半分"]', 0, 2, '垂直二等分線上のすべての点は、線分の両端から等距離にあるという性質があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '角の二等分線上の任意の点は、角の2つの辺からどのような距離にあるか。', '["等しい距離","異なる距離","2倍の距離","半分"]', 0, 2, '角の二等分線上のすべての点は、角をはさむ2つの辺から等距離にあるという性質があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', 'データの代表値のうち、平均値の求め方はどれか。', '["合計÷個数","最大値-最小値","中央の値","最も多い値"]', 0, 1, '平均値は、データの合計をデータの個数で割って求めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '度数分布表において、階級値が20、度数が3のとき、この階級の合計値はいくつか。', '["60","23","17","40"]', 0, 2, '階級値×度数＝20×3＝60です。平均値を求める際に使用します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '空間図形において、2つの平面が交わってできるものは何か。', '["直線","点","面","円"]', 0, 1, '空間において、2つの平面が交わると、その交わりは直線になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '円柱の体積の公式はどれか（底面半径r、高さh）。', '["πr²h","2πrh","πrh","1/3πr²h"]', 0, 1, '円柱の体積は、底面積(πr²)×高さ(h)＝πr²h です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'math', '円錐の体積の公式はどれか（底面半径r、高さh）。', '["1/3πr²h","πr²h","2πrh","1/3πrh"]', 0, 1, '円錐の体積は、円柱の体積の1/3であり、1/3×底面積×高さ＝1/3πr²h です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', 'ルーペで観察するとき、正しい使い方はどれか。', '["ルーペを目に近づけ、動かさずに観察物を近づける","観察物を机に置き、ルーペを大きく動かしてピントを合わせる","ルーペを固定し、顔を大きく前後に動かす","ルーペを観察物から離し、遠くから見る"]', 0, 1, 'ルーペは目に近づけて持ち、観察対象となる物体をルーペに近づけてピントを合わせるのが正しい手順です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察する際、最初に調整するねじはどれか。', '["調節ねじ","微動調節ねじ","レボルバー","しぼり"]', 0, 1, 'まずは調節ねじを使ってステージを上げ、プレパラートと対物レンズを近づけてから、ピントを合わせます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の倍率を高くしたとき、視野はどうなるか。', '["明るくなり、見える範囲は広くなる","暗くなり、見える範囲は狭くなる","明るくなり、見える範囲は狭くなる","暗くなり、見える範囲は広くなる"]', 1, 2, '倍率を上げると、光の取り込める量が減るため視野は暗くなり、拡大される分、見える範囲は狭くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '花のつくりのうち、花粉がつくられる場所はどこか。', '["やく","めしべの柱頭","花びら","がく"]', 0, 1, 'おしべの先端にある「やく」の中で花粉がつくられます。花粉がめしべの柱頭につくことを受粉といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物において、胚珠が包まれている場所はどこか。', '["子房","花粉","花托","花柱"]', 0, 1, '被子植物は胚珠が子房に包まれています。受粉後、子房は果実になり、胚珠は種子になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '裸子植物の胚珠の特徴として正しいものはどれか。', '["子房がなく、胚珠がむき出しになっている","花びらが発達している","子房の中に胚珠がある","めしべがない"]', 0, 2, '裸子植物は子房を持たないため、胚珠がむき出しの状態です。マツやイチョウなどが代表例です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成で植物が吸収する気体はどれか。', '["二酸化炭素","酸素","窒素","水素"]', 0, 1, '植物は日光のエネルギーを利用して、二酸化炭素と水から養分（デンプンなど）をつくり、酸素を放出します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '葉の裏側に多く見られる、気体の出入り口となる穴を何というか。', '["気孔","道管","師管","葉緑体"]', 0, 1, '気孔は葉の裏側に多く存在し、光合成や呼吸、蒸散に必要な気体の通り道となっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物が根から吸い上げた水が、水蒸気として体外へ放出される現象を何というか。', '["蒸散","光合成","呼吸","受粉"]', 0, 1, '蒸散は、根から吸い上げた水を葉の気孔から水蒸気として出す現象で、体温調節や水の吸い上げを助けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成が行われる細胞内の小さな粒を何というか。', '["葉緑体","核","細胞壁","液胞"]', 0, 1, '葉緑体は緑色の粒で、光合成を行う場所です。光エネルギーを吸収して養分を合成します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '道管を通って運ばれるものは何か。', '["根から吸い上げた水や養分","葉でつくられた養分","二酸化炭素","酸素"]', 0, 2, '道管は根から吸収した水や肥料分を運ぶ管です。葉でつくられた養分は師管を通って運ばれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '師管を通って運ばれるものは何か。', '["葉でつくられた養分","根から吸い上げた水","二酸化炭素","酸素"]', 0, 2, '師管は、光合成によって葉でつくられた養分を植物の各部へ運ぶための管です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '双子葉類の特徴として正しいものはどれか。', '["葉脈が網目状である","葉脈が平行である","ひげ根である","子葉が1枚である"]', 0, 2, '双子葉類は子葉が2枚で、葉脈は網目状、根は主根と側根という特徴があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '単子葉類の特徴として正しいものはどれか。', '["葉脈が平行である","葉脈が網目状である","主根と側根がある","子葉が2枚である"]', 0, 2, '単子葉類は子葉が1枚で、葉脈は平行、根はひげ根という特徴があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の対物レンズを交換する際、回転させる部分はどれか。', '["レボルバー","しぼり","微動調節ねじ","ステージ"]', 0, 2, 'レボルバーを回すことで、倍率の異なる対物レンズに切り替えることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物が呼吸を行うのはいつか。', '["昼も夜も常に行っている","昼間だけ行っている","夜間だけ行っている","光合成をしている間だけ"]', 0, 2, '呼吸は生きている限り常に行われています。光合成は光があるときだけ行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察する材料を薄く切る理由は何か。', '["光を通すため","小さくするため","染色しやすくするため","顕微鏡を傷つけないため"]', 0, 2, '顕微鏡は光を透過させて観察するため、材料が厚いと光が通らず、内部まで見ることができません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', 'ツユクサの葉の裏側を観察したとき、気孔の周りにある細胞を何というか。', '["孔辺細胞","表皮細胞","道管","師管"]', 0, 2, '孔辺細胞は気孔の開閉を行う細胞で、葉緑体を含んでいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物のうち、子葉が2枚の植物はどれか。', '["アサガオ","トウモロコシ","イネ","ユリ"]', 0, 2, 'アサガオは双子葉類なので子葉は2枚です。残りはすべて単子葉類です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '裸子植物の例として正しいものはどれか。', '["マツ","アブラナ","タンポポ","サクラ"]', 0, 2, 'マツ、イチョウ、ソテツなどは裸子植物です。それ以外は被子植物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察中、視野の左上に像がある。中央に移動させるにはプレパラートをどう動かすか。', '["左上に動かす","右下に動かす","上に動かす","左に動かす"]', 0, 3, '顕微鏡の像は上下左右が逆に見えるため、見たい方向へ動かすと視野から消えてしまいます。逆方向に動かします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成でつくられた養分は、何という物質として蓄えられることが多いか。', '["デンプン","タンパク質","脂肪","無機物"]', 0, 2, '光合成によってつくられた養分は、まずデンプンとして葉に蓄えられ、その後ショ糖などに変えられて運ばれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '蒸散が最も活発になる条件はどれか。', '["気温が高く、乾燥しているとき","気温が低く、湿気が多いとき","暗いとき","風が全くないとき"]', 0, 2, '蒸散は、気温が高く、湿度が低く、風があるときに活発になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡のしぼりの役割は何か。', '["光の量を調節する","ピントを合わせる","倍率を変える","プレパラートを固定する"]', 0, 1, 'しぼりは、視野の明るさを調節するための装置です。明るすぎる場合はしぼりを小さくします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の根の先端近くにある、細い毛のようなものを何というか。', '["根毛","ひげ根","側根","主根"]', 0, 1, '根毛は表面積を大きくし、水や肥料分を効率よく吸収する役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '維管束（いかんそく）とは何か。', '["道管と師管が集まったもの","葉の気孔の集まり","根の先端の組織","花びらの血管"]', 0, 2, '維管束は、道管と師管が束になったもので、植物の体内で水や養分を運ぶ通路です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の花のつくりの外側から内側への順番として正しいものはどれか。', '["がく→花びら→おしべ→めしべ","花びら→がく→おしべ→めしべ","めしべ→おしべ→花びら→がく","がく→おしべ→めしべ→花びら"]', 0, 2, '花は外側から「がく」「花びら」「おしべ」「めしべ」の順に並んでいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成において、酸素が放出されるのはいつか。', '["光が当たっているとき","暗いとき","呼吸をしているとき","蒸散をしているとき"]', 0, 2, '光合成は光エネルギーを利用するため、光が当たっているときに酸素が放出されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡のステージを下げてから対物レンズを交換する理由は何か。', '["レンズとプレパラートの接触を防ぐため","光を取り込みやすくするため","倍率を安定させるため","ピントを合わせやすくするため"]', 0, 2, '対物レンズを交換する際、レンズがプレパラートにぶつかって破損するのを防ぐため、必ずステージを下げます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '次のうち、単子葉類はどれか。', '["トウモロコシ","アブラナ","エンドウ","サクラ"]', 0, 2, 'トウモロコシは単子葉類です。他はすべて双子葉類です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成でつくられた養分は、何に変えられて植物の各部に運ばれるか。', '["ショ糖","デンプン","タンパク質","脂肪"]', 0, 3, 'デンプンは水に溶けにくいため、水に溶けやすいショ糖に変えられて師管を通って運ばれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の倍率の計算方法はどれか。', '["接眼レンズの倍率 × 対物レンズの倍率","接眼レンズの倍率 ＋ 対物レンズの倍率","接眼レンズの倍率 ÷ 対物レンズの倍率","対物レンズの倍率 － 接眼レンズの倍率"]', 0, 1, '顕微鏡の総合倍率は、接眼レンズと対物レンズの倍率を掛け合わせたものです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の胚珠が子房に包まれている利点は何か。', '["乾燥などから胚珠を守るため","光合成を促進するため","受粉を確実にするため","成長を早めるため"]', 0, 3, '胚珠が子房に包まれていることで、乾燥や外敵から守られ、より確実に種子を形成できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の微動調節ねじの役割は何か。', '["わずかにピントを合わせる","ステージを大きく上下させる","倍率を大きく変える","光の量を大きく変える"]', 0, 2, '微動調節ねじは、ピントを精密に合わせるときに使用します。調節ねじで大まかに合わせた後に使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の茎において、道管はどこに位置しているか。', '["維管束の内側","維管束の外側","茎の表面","茎の中心部"]', 0, 3, '茎の維管束では、道管は内側、師管は外側に位置しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の茎において、師管はどこに位置しているか。', '["維管束の外側","維管束の内側","茎の表面","茎の中心部"]', 0, 3, '茎の維管束では、師管は外側、道管は内側に位置しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成の実験で、葉をエタノールに入れて加熱する理由は何か。', '["葉緑素を脱色するため","デンプンを溶かすため","葉を柔らかくするため","光合成を止めるため"]', 0, 3, '葉緑素（クロロフィル）をエタノールに溶かし出すことで、ヨウ素液による色の変化（青紫色）を見やすくします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', 'ヨウ素液が反応して何色になるか。', '["青紫色","赤色","黄色","緑色"]', 0, 1, 'ヨウ素液はデンプンと反応して、青紫色に変化します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物のうち、網目状の葉脈を持つのはどれか。', '["双子葉類","単子葉類","裸子植物","シダ植物"]', 0, 2, '双子葉類は網目状の葉脈を持ち、単子葉類は平行な葉脈を持ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物が呼吸で放出する気体は何か。', '["二酸化炭素","酸素","窒素","水素"]', 0, 2, '呼吸は酸素を取り入れ、二酸化炭素を放出する働きです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の視野を明るくするために行う操作はどれか。', '["しぼりを大きくする","しぼりを小さくする","対物レンズを外す","接眼レンズを外す"]', 0, 2, '視野が暗いときは、しぼりを大きくして取り込む光の量を増やします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の種子になる部分はどこか。', '["胚珠","子房","花粉","花托"]', 0, 2, '受粉後、胚珠は種子になり、子房は果実になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の根の主な役割として適切でないものはどれか。', '["光合成を行う","体を支える","水や養分を吸収する","養分を蓄える"]', 0, 1, '光合成は主に葉で行われます。根は体を支えたり、水や養分を吸収・貯蔵したりします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の接眼レンズを先に取り付ける理由は何か。', '["鏡筒内にゴミが入るのを防ぐため","倍率を合わせるため","ピントを合わせやすくするため","光を反射させるため"]', 0, 3, '接眼レンズを先に取り付けることで、鏡筒内へのゴミの混入を防ぐことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '次の植物のうち、ひげ根を持つものはどれか。', '["イネ","アブラナ","エンドウ","タンポポ"]', 0, 2, 'イネは単子葉類なので、ひげ根を持ちます。残りはすべて双子葉類で主根と側根を持ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成に必要な条件として正しいものはどれか。', '["光、二酸化炭素、水","光、酸素、水","光、窒素、水","二酸化炭素、酸素、水"]', 0, 2, '光合成は、光、二酸化炭素、水を用いて行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡のステージに乗せるガラス板を何というか。', '["プレパラート","スライドガラス","カバーガラス","レンズ"]', 0, 1, '観察物をのせるスライドガラスと、その上にかぶせるカバーガラスを合わせたものをプレパラートといいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の花で、受粉後に果実になる部分はどこか。', '["子房","胚珠","花柱","花托"]', 0, 2, '子房が果実になり、その中の胚珠が種子になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察する際、ピントを合わせるために最初に行うことはどれか。', '["調節ねじでステージを上げる","微動調節ねじを回す","しぼりを調整する","レボルバーを回す"]', 0, 2, 'まずはステージを上げて対物レンズをプレパラートに近づけ、そこから遠ざけながらピントを合わせます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物が呼吸を行う際、取り入れる気体は何か。', '["酸素","二酸化炭素","窒素","水素"]', 0, 2, '呼吸は酸素を取り入れ、二酸化炭素を出す働きです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察中、視野の右下に像がある。中央に移動させるにはプレパラートをどう動かすか。', '["右下に動かす","左上に動かす","右に動かす","下に動かす"]', 0, 3, '顕微鏡の像は上下左右が逆に見えるため、見たい方向へ動かすと視野から消えてしまいます。逆方向に動かします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の葉で、光合成が最も活発に行われる場所はどこか。', '["葉肉の細胞","道管","師管","気孔"]', 0, 3, '葉肉の細胞には葉緑体が多く含まれており、そこで光合成が活発に行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の種子植物は、どのように分類されるか。', '["双子葉類と単子葉類","裸子植物と被子植物","シダ植物とコケ植物","種子植物と胞子植物"]', 0, 2, '被子植物は、子葉の枚数によって双子葉類と単子葉類に分類されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡で観察するとき、直射日光を反射鏡に当ててはいけない理由は何か。', '["目を傷める恐れがあるから","レンズが割れるから","像がぼやけるから","顕微鏡が熱くなるから"]', 0, 2, '直射日光を反射鏡に当てると、強い光が目に直接入り、視力を損なう危険があるため絶対に行ってはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '植物の蒸散の主な役割として適切でないものはどれか。', '["光合成を促進する","体温の上昇を防ぐ","根から水を吸い上げる力を生む","養分を運ぶ"]', 0, 3, '蒸散は体温調節や水の吸い上げには役立ちますが、光合成を直接促進する働きではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の反射鏡の役割は何か。', '["光を反射させて視野を明るくする","ピントを合わせる","倍率を変える","プレパラートを固定する"]', 0, 1, '反射鏡は光を反射させ、ステージ上のプレパラートに光を送り込む役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '被子植物の胚珠が子房に包まれているグループを何というか。', '["被子植物","裸子植物","シダ植物","コケ植物"]', 0, 1, '胚珠が子房に包まれている植物を被子植物といいます。包まれていないものは裸子植物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '顕微鏡の対物レンズを交換する際、最初に行うことはどれか。', '["ステージを下げる","レボルバーを回す","微動調節ねじを回す","反射鏡を調整する"]', 0, 2, 'レンズ交換時にプレパラートとの接触を防ぐため、まずはステージを下げて距離をとります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'science', '光合成によって放出される酸素は、主にどこから出ていくか。', '["気孔","根","茎の表面","花びら"]', 0, 2, '光合成で生じた酸素は、気孔を通って空気中に放出されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質の密度を求める公式として正しいものはどれか。', '["密度＝質量÷体積","密度＝体積÷質量","密度＝質量×体積","密度＝質量＋体積"]', 0, 1, '密度は単位体積あたりの質量を表すため、質量を体積で割ることで求められます。単位はg/cm³です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属の性質として誤っているものはどれか。', '["電気をよく通す","たたくと広がる（展性）","磁石に必ずつく","金属光沢がある"]', 2, 1, 'すべての金属が磁石につくわけではありません。鉄やニッケルなどはつきますが、銅やアルミニウムは磁石につきません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '酸素を発生させるために、二酸化マンガンに加える液体は何か。', '["水","石灰水","オキシドール（過酸化水素水）","塩酸"]', 2, 1, '二酸化マンガンを触媒として、オキシドール（過酸化水素水）を加えると、激しく酸素が発生します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '二酸化炭素の性質として正しいものはどれか。', '["水に溶けにくい","石灰水を白くにごらせる","火のついた線香を入れると激しく燃える","空気より軽い"]', 1, 1, '二酸化炭素は石灰水と反応して炭酸カルシウムを生じ、白くにごらせる性質があります。これは重要な確認方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'アンモニアの性質として正しいものはどれか。', '["水に溶けにくい","刺激臭がある","空気より軽い","酸性を示す"]', 1, 2, 'アンモニアは非常に水に溶けやすく、特有の強い刺激臭があります。また、水溶液はアルカリ性を示します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '質量パーセント濃度の計算式として正しいものはどれか。', '["（溶質の質量÷溶液の質量）×100","（溶質の質量÷溶媒の質量）×100","（溶液の質量÷溶質の質量）×100","（溶質の質量÷溶液の体積）×100"]', 0, 2, '質量パーセント濃度は、溶液全体に対する溶質の割合をパーセントで表したものです。溶液＝溶質＋溶媒である点に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質が固体から液体に変わるときの温度を何というか。', '["沸点","融点","凝固点","昇華点"]', 1, 1, '固体が溶けて液体になるときの温度を融点、液体が沸騰して気体になるときの温度を沸点といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水に溶けない気体を集める方法として最も適切なものはどれか。', '["上方置換法","下方置換法","水上置換法","ろ過"]', 2, 1, '水に溶けにくい気体は、水上置換法で集めるのが最も純度が高く適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '密度が1.0g/cm³の液体に浮く物質の密度はどれか。', '["0.8g/cm³","1.2g/cm³","2.0g/cm³","5.0g/cm³"]', 0, 2, '液体より密度が小さい物質は、その液体に浮きます。0.8は1.0より小さいため浮きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質を加熱したとき、温度が一定になるのはなぜか。', '["熱が逃げているから","物質が変化しているから","状態変化に使われているから","温度計が壊れているから"]', 2, 2, '融点や沸点では、加えた熱エネルギーが物質の状態変化（固体→液体、液体→気体）に使われるため、温度は上昇しません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属を磨くと光る性質を何というか。', '["展性","延性","金属光沢","導電性"]', 2, 1, '金属特有の輝きを金属光沢といいます。磨くことで表面が滑らかになり、光をよく反射するようになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水素の性質として正しいものはどれか。', '["空気より重い","火を近づけると音を立てて燃える","水に溶けやすい","石灰水を白くにごらせる"]', 1, 2, '水素は非常に燃えやすい気体で、火を近づけるとポンと音を立てて燃焼し、水が生成されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '10gの食塩を90gの水に溶かしたときの濃度は何％か。', '["10％","11.1％","9％","1.1％"]', 0, 2, '溶液の質量は10g＋90g＝100g。濃度は10g÷100g×100＝10％となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の集め方で、空気より重く水に溶けやすい気体に適しているのはどれか。', '["水上置換法","上方置換法","下方置換法","ろ過"]', 2, 2, '空気より重く水に溶ける気体は、下方置換法で集めます。アンモニアは軽いので上方置換法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '非金属の性質として正しいものはどれか。', '["電気を通しやすい","たたくと広がる","金属光沢がない","熱をよく伝える"]', 2, 1, '非金属は電気や熱をほとんど通さず、たたいても伸びたり広がったりせず、金属光沢もありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質の質量を測定する器具として最も適切なものはどれか。', '["メスシリンダー","上皿天びん","ビーカー","試験管"]', 1, 1, '質量をはかるには上皿天びんや電子天びんを使います。メスシリンダーは体積をはかる器具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水溶液の濃度を高くするにはどうすればよいか。', '["水を加える","溶質を加える","温度を下げる","かき混ぜる"]', 1, 1, '濃度は溶質の割合なので、溶質（食塩など）を増やすことで濃度が高くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'エタノールの沸点は約何度か。', '["100℃","78℃","50℃","0℃"]', 1, 2, 'エタノールの沸点は約78℃です。水（100℃）よりも低い温度で沸騰します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体を水上置換法で集めるとき、最初に出てくる気体はなぜ捨てるのか。', '["純度が低いから","火がつくから","試験管に入っている空気と混ざっているから","毒性があるから"]', 2, 2, '装置内に残っていた空気が最初に出てくるため、純粋な気体を得るために最初の部分は捨てます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属の性質である「展性」とはどのようなものか。', '["電気を通すこと","磁石につくこと","たたいて薄く広がる性質","熱を伝えること"]', 2, 2, '展性とは、たたいたり圧力をかけたりしたときに、薄く広がる性質のことです。延性は細く伸びる性質です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '酸素の性質として正しいものはどれか。', '["水に非常によく溶ける","他の物質が燃えるのを助ける","石灰水を白くにごらせる","空気より軽い"]', 1, 1, '酸素には助燃性があり、他の物質が燃えるのを助ける働きがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'メスシリンダーで体積を読み取るとき、目線の位置として正しいのはどれか。', '["液面の中心と同じ高さ","液面より上から見下ろす","液面より下から見上げる","どこから見てもよい"]', 0, 1, 'メスシリンダーの目盛りは、液面の中心と同じ高さで水平に読む必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '飽和水溶液とはどのような状態か。', '["これ以上溶質が溶けきれない状態","溶質がすべて溶けている状態","温度が非常に高い状態","溶媒が足りない状態"]', 0, 2, 'ある温度で、それ以上溶質が溶けきれなくなった状態を飽和水溶液といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質を加熱したときの温度変化のグラフで、平らな部分が2か所ある物質は何か。', '["純粋な物質","混合物","金属","水"]', 1, 3, '純粋な物質は融点や沸点が一定ですが、混合物は温度が変化し続けるため、平らな部分がはっきりしません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'アンモニアを水に溶かした水溶液の性質はどれか。', '["酸性","中性","アルカリ性","不明"]', 2, 2, 'アンモニア水はアルカリ性を示します。フェノールフタレイン溶液を加えると赤色になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '密度が最も大きい物質はどれか。', '["アルミニウム","鉄","銅","金"]', 3, 2, '金（約19.3g/cm³）は、鉄（約7.9g/cm³）や銅（約8.9g/cm³）よりも密度が非常に大きいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の集め方で、上方置換法が適している気体はどれか。', '["酸素","二酸化炭素","アンモニア","水素"]', 2, 2, 'アンモニアは水に溶けやすく、空気より軽いため、上方置換法で集めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質の体積を求める際、不規則な形の固体はどうやってはかるか。', '["定規で長さをはかる","メスシリンダーで水面の上昇分をはかる","重さをはかる","顕微鏡で見る"]', 1, 1, '水に沈めて、増えた水の体積を読み取ることで、固体の体積を求めることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '溶質が一定量溶けている溶液に、さらに溶媒（水）を加えるとどうなるか。', '["濃度が高くなる","濃度が低くなる","濃度は変わらない","溶質が析出する"]', 1, 1, '溶質の量は変わらず全体の量（溶媒）が増えるため、濃度は低くなります（薄まります）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '沸騰石を入れる目的は何か。', '["温度を上げるため","突沸を防ぐため","気体を発生させるため","溶けやすくするため"]', 1, 2, '沸騰石は、液体が急激に沸騰する「突沸」を防ぎ、穏やかに沸騰させるために加えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属の分類として正しい組み合わせはどれか。', '["鉄・銅・アルミニウム","鉄・炭素・硫黄","酸素・窒素・水素","銅・金・酸素"]', 0, 1, '鉄、銅、アルミニウムはすべて金属です。炭素や硫黄、酸素などは非金属に分類されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '質量パーセント濃度が20％の食塩水100gに含まれる食塩は何gか。', '["10g","20g","80g","100g"]', 1, 2, '100gの20％なので、100×0.2＝20gとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '酸素と二酸化炭素の共通点はどれか。', '["水に溶けやすい","空気より軽い","無色透明である","火を消す"]', 2, 1, '酸素も二酸化炭素も、どちらも無色透明な気体です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質の密度をはかる際、必要なデータは何か。', '["質量と体積","質量と温度","体積と圧力","温度と圧力"]', 0, 1, '密度＝質量÷体積なので、質量と体積の両方を測定する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '状態変化で、体積が最も大きく変化するのはどれか。', '["固体から液体","液体から気体","気体から液体","液体から固体"]', 1, 2, '液体から気体になると、分子間の距離が非常に大きくなるため、体積は何百倍にも膨れ上がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'アンモニアを発生させる方法として適切なのはどれか。', '["塩化アンモニウムと水酸化カルシウムを混ぜて加熱する","鉄と塩酸を混ぜる","二酸化マンガンにオキシドールを加える","石灰石に塩酸を加える"]', 0, 3, 'アンモニアは塩化アンモニウムと水酸化カルシウムなどのアルカリを混ぜて加熱することで発生します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水溶液の濃度を求める際に必要なものはどれか。', '["溶質の質量と溶液の質量","溶質の質量と溶媒の体積","溶液の体積と溶媒の質量","温度と圧力"]', 0, 2, '質量パーセント濃度は、溶質の質量を溶液（溶質＋溶媒）の質量で割って求めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属光沢をもつ非金属はどれか。', '["鉄","銅","ヨウ素","アルミニウム"]', 2, 3, 'ヨウ素は非金属ですが、黒紫色で金属光沢のような輝きをもつ特殊な物質です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体を下方置換法で集める際、試験管の口はどうするべきか。', '["上に向ける","下に向ける","横に向ける","密閉する"]', 0, 2, '下方置換法は、空気より重い気体を底に沈めるように集めるため、試験管の口を上に向けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質が液体から固体に変わる現象を何というか。', '["融解","凝固","沸騰","蒸発"]', 1, 1, '液体から固体になることを凝固といいます。逆に固体から液体になることを融解といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '密度が0.92g/cm³の氷が水（1.0g/cm³）に浮く理由は何か。', '["氷の方が密度が小さいから","氷の方が密度が大きいから","氷の方が重いから","氷の方が体積が大きいから"]', 0, 2, '物体は、その液体よりも密度が小さい場合に浮きます。氷は水より密度が小さいため浮きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '二酸化炭素を発生させるために用いる薬品はどれか。', '["石灰石と塩酸","鉄と塩酸","亜鉛と塩酸","二酸化マンガンとオキシドール"]', 0, 2, '石灰石（炭酸カルシウム）に塩酸を加えると、二酸化炭素が発生します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属の性質として「延性」とは何か。', '["たたいて広がる","細く伸びる","電気を通す","磁石につく"]', 1, 2, '延性とは、引っ張ったときに細く伸びる性質のことです。展性は薄く広がる性質です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '純粋な物質の融点について正しい説明はどれか。', '["一定である","加熱すると変化する","量によって変わる","混合物と同じである"]', 0, 2, '純粋な物質は、その物質固有の融点を持っており、一定です。混合物は融点が一定になりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水100gに食塩25gを溶かしたときの濃度は何％か。', '["20％","25％","33％","10％"]', 0, 3, '溶液の質量は100＋25＝125g。濃度は25÷125×100＝20％となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の性質を調べる際、火のついた線香が消える気体はどれか。', '["酸素","二酸化炭素","水素","アンモニア"]', 1, 2, '二酸化炭素には燃焼を助ける働きがないため、火のついた線香を入れるとすぐに消えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質の密度を求める実験で、誤差が大きくなる原因はどれか。', '["天びんを水平にする","メスシリンダーの目盛りを正しく読む","気泡が付着したまま体積をはかる","室温を一定にする"]', 2, 3, '固体の表面に気泡がついていると、その分体積が大きく測定されてしまい、密度が小さく計算されてしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属を加熱して冷やしても、金属の性質は変わらない。これを何というか。', '["状態変化","化学変化","物理変化","融解"]', 2, 3, '物質そのものが別の物質に変わるのではなく、状態が変わるだけの変化を物理変化といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水溶液の濃度を計算するとき、分母に来るものは何か。', '["溶質の質量","溶媒の質量","溶液の質量","溶質の体積"]', 2, 2, '濃度は「溶質÷溶液」で求めます。溶液の質量は溶質＋溶媒であることを忘れないようにしましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', 'アンモニアの噴水実験で、水が吸い込まれる理由は何か。', '["アンモニアが水に非常によく溶けるから","アンモニアが重いから","空気圧が低いから","温度が上がったから"]', 0, 3, 'アンモニアが水に溶けてフラスコ内の気圧が急激に下がるため、外側の水が吸い上げられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '鉄の性質として正しいものはどれか。', '["磁石につく","電気を通さない","展性がない","水に浮く"]', 0, 1, '鉄は磁石につく性質があります。また、電気をよく通し、展性や延性もあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '物質を加熱したとき、温度が上昇し続けるのはどのような物質か。', '["純粋な物質","混合物","金属","水"]', 1, 3, '混合物は融点や沸点が一定ではないため、加熱中も温度が上昇し続けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の集め方で、水上置換法が使えないのはどれか。', '["酸素","水素","アンモニア","二酸化炭素"]', 2, 2, 'アンモニアは水に非常に溶けやすいため、水上置換法で集めることはできません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '密度をはかる際、体積をはかる器具として最も正確なものはどれか。', '["ビーカー","メスシリンダー","試験管","三角フラスコ"]', 1, 1, 'メスシリンダーは体積をはかるために目盛りが細かく刻まれており、最も正確にはかれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '質量パーセント濃度が同じであれば、溶液の量は関係あるか。', '["ある","ない","濃度による","物質による"]', 1, 2, '濃度は割合なので、全体の量が100gでも1kgでも、同じ濃度であれば含まれる溶質の割合は同じです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の性質を調べる際、石灰水が白くにごる気体はどれか。', '["酸素","水素","二酸化炭素","アンモニア"]', 2, 1, '二酸化炭素は石灰水（水酸化カルシウム水溶液）と反応して、白くにごる性質があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '金属の光沢を失わせるにはどうすればよいか。', '["磨く","加熱する","水につける","冷やす"]', 1, 2, '金属を加熱すると、空気中の酸素と反応して表面が酸化し、光沢が失われることがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '水溶液の濃度を求める際、溶質が食塩の場合、溶媒は何になるか。', '["食塩","水","食塩水","空気"]', 1, 1, '水溶液において、溶かしている液体（この場合は水）を溶媒といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '状態変化について、正しい説明はどれか。', '["物質の種類は変わる","物質の質量は変わる","物質の体積は変わる","物質の温度は変わる"]', 2, 2, '状態変化では、物質の種類や質量は変わりませんが、体積は大きく変わります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'science', '気体の集め方で、上方置換法が適している理由はどれか。', '["空気より重く水に溶けやすいから","空気より軽く水に溶けやすいから","空気より重く水に溶けにくいから","空気より軽く水に溶けにくいから"]', 1, 3, '空気より軽く、水に溶けやすい気体は、水上置換法が使えないため上方置換法で集めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が鏡などの表面で跳ね返る現象を何というか。', '["反射","屈折","直進","全反射"]', 0, 1, '光が物体に当たって跳ね返る現象を反射といいます。入射角と反射角は常に等しくなるという法則があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が異なる物質に進むとき、境界で折れ曲がる現象を何というか。', '["反射","屈折","直進","全反射"]', 1, 1, '光が空気から水やガラスなど、別の物質に進むときに境界面で折れ曲がる現象を屈折といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が水中から空気中へ進むとき、境界面ですべて反射される現象を何というか。', '["乱反射","屈折","全反射","直進"]', 2, 2, '光が屈折率の大きい物質から小さい物質へ進むとき、入射角がある大きさを超えるとすべて反射される全反射が起こります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズによってできる、スクリーンに映すことができる像を何というか。', '["実像","虚像","正立像","倒立像"]', 0, 2, '光が実際に集まってできる像を実像といい、スクリーンに映すことができます。上下左右が逆向きになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズを通して見たとき、大きく見えるがスクリーンに映せない像を何というか。', '["実像","虚像","倒立像","等大像"]', 1, 2, '物体を焦点の内側に置いたとき、レンズを通して見える拡大された像を虚像といいます。光は実際に集まっていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の大きさを決める要素は何か。', '["振動数","振幅","音色","速さ"]', 1, 1, '音の大きさは、物体が振動する幅である「振幅」が大きいほど大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の高さを決める要素は何か。', '["振幅","振動数","音色","速さ"]', 1, 1, '音の高さは、1秒間に振動する回数である「振動数（Hz）」が多いほど高くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねののびが、つるしたおもりの重さに比例する法則を何というか。', '["フックの法則","パスカルの原理","作用反作用の法則","慣性の法則"]', 0, 1, 'ばねののびは、ばねを引く力（おもりの重さ）に比例します。これをフックの法則といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '面を垂直に押す力の大きさを何というか。', '["重力","圧力","摩擦力","弾性力"]', 1, 1, '面を垂直に押す力の大きさを圧力といい、単位面積あたりの力の大きさ（N/m²やPa）で表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光の反射の法則において、入射角と反射角の関係はどれか。', '["入射角の方が大きい","反射角の方が大きい","常に等しい","和が90度になる"]', 2, 1, '反射の法則により、鏡面への入射角と反射角は常に等しくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '水中のコインが浮き上がって見えるのは、光の何という現象によるものか。', '["反射","屈折","直進","全反射"]', 1, 2, '水中のコインから出た光が水面で屈折して空気中へ進むため、実際の位置よりも浅い場所にあるように見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズの焦点距離をfとしたとき、物体を2fより遠くに置いたときにできる像の説明として正しいものは。', '["実像で、物体より小さい","実像で、物体より大きい","虚像で、物体より小さい","虚像で、物体より大きい"]', 0, 3, '物体が2fより遠い場合、像は焦点と2fの間にでき、実像で物体より小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '物体を凸レンズの焦点距離fの位置に置いたとき、像はどうなるか。', '["実像ができる","虚像ができる","像はできない","正立像ができる"]', 2, 3, '物体を焦点の位置に置くと、レンズを通った光は平行に進むため、像はできません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の単位「Hz（ヘルツ）」は何を表すものか。', '["音の大きさ","音の高さ","音の伝わる速さ","音色"]', 1, 2, 'Hzは振動数の単位で、1秒間に何回振動するかを表します。振動数が多いほど音は高くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力を求める公式として正しいものはどれか。', '["力 ÷ 面積","面積 ÷ 力","力 × 面積","質量 × 面積"]', 0, 2, '圧力（Pa）＝ 面を垂直に押す力（N）÷ 力が働く面積（m²）で求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '100gの物体にはたらく重力の大きさを約何Nとするか。', '["0.1N","1N","10N","100N"]', 1, 1, '地球上で約100gの物体にはたらく重力の大きさは約1Nと定義されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズで実像ができるとき、物体と像の上下左右の関係は。', '["上下左右とも同じ","上下左右とも逆","上下だけ逆","左右だけ逆"]', 1, 2, '凸レンズでできる実像は、物体に対して上下左右が逆向き（倒立）になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ギターの弦を強くはじくと、音はどう変化するか。', '["高くなる","低くなる","大きくなる","小さくなる"]', 2, 1, '強くはじくと振幅が大きくなるため、音の大きさが大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねに1Nのおもりをつるすと2cmのびた。2Nつるすと何cmのびるか。', '["2cm","3cm","4cm","1cm"]', 2, 2, 'フックの法則により、のびは力に比例します。力が2倍になれば、のびも2倍の4cmになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力を大きくするためには、どうすればよいか。', '["面積を大きくする","力を小さくする","面積を小さくする","重さを減らす"]', 2, 2, '圧力は「力÷面積」なので、面積を小さくするほど、同じ力でも圧力は大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光がガラスから空気へ進むとき、入射角と屈折角の関係は。', '["入射角＝屈折角","入射角＞屈折角","入射角＜屈折角","常に90度"]', 2, 3, '光が屈折率の大きい物質から小さい物質へ進むとき、屈折角は入射角よりも大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の速さは、空気中で約秒速何mか。', '["150m","340m","1000m","300000km"]', 1, 1, '空気中の音の速さは、気温15℃で約340m/sです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズの焦点距離が10cmのとき、物体を5cmの場所に置くとどうなるか。', '["実像ができる","虚像ができる","像はできない","光が平行になる"]', 1, 3, '物体を焦点距離の内側に置くと、拡大された虚像が見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力の単位 Pa（パスカル）と同じ意味の単位は。', '["N/m²","N/cm²","g/cm²","kg/m²"]', 0, 2, '1Paは1平方メートルあたりに1ニュートンの力がかかる圧力のことで、N/m²と表せます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が鏡で反射するとき、入射角が30度のとき反射角は何度か。', '["30度","60度","90度","0度"]', 0, 1, '反射の法則により、入射角と反射角は等しいため、30度になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '虫眼鏡で太陽の光を集めるとき、最も明るく小さくなる点はどこか。', '["レンズの中心","焦点","焦点の2倍の距離","レンズの表面"]', 1, 2, '平行光線が凸レンズを通ると、焦点に集まります。ここが最も明るく熱くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の振動数が高いほど、音はどう聞こえるか。', '["大きく","小さく","高く","低く"]', 2, 1, '振動数は音の高さを決め、振動数が多いほど高い音になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねに何もつるしていないときの長さを何というか。', '["自然の長さ","のび","全長のび","弾性限界"]', 0, 1, '力を加えていないときのばねの長さを自然の長さといいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'スポンジの上に物体を置くとき、最も圧力が大きくなる置き方は。', '["面積の広い面を下にする","面積の狭い面を下にする","横に倒す","立てかける"]', 1, 2, '圧力は面積が小さいほど大きくなるため、接地面積が狭いほどスポンジは深く沈みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が空気からガラスへ進むとき、屈折角は入射角と比べてどうなるか。', '["大きくなる","小さくなる","変わらない","反射する"]', 1, 3, '光が空気からガラスなど屈折率の大きい物質へ進むとき、光は法線側に曲がり、屈折角は入射角より小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '物体を凸レンズの焦点距離の2倍の位置に置いたとき、できる像は。', '["実像で、物体と同じ大きさ","実像で、物体より大きい","虚像で、物体より小さい","虚像で、物体より大きい"]', 0, 3, '物体を2fの位置に置くと、像も反対側の2fの位置にでき、大きさと向きは等大倒立像となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の大きさを表す単位はどれか。', '["Hz","dB","m/s","N"]', 1, 2, '音の大きさ（音圧レベル）はデシベル（dB）という単位で表されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'フックの法則が成り立たなくなる限界の力を何というか。', '["弾性限界","比例限界","破壊限界","最大荷重"]', 0, 3, 'ばねを強く引きすぎると、元の長さに戻らなくなります。その限界を弾性限界といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '面積が2m²の面に10Nの力が垂直にはたらくとき、圧力は何Paか。', '["5Pa","20Pa","0.2Pa","50Pa"]', 0, 2, '圧力＝力÷面積なので、10N ÷ 2m² ＝ 5Paとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が反射するとき、入射角が0度（面に垂直）の場合、反射角は何度か。', '["0度","45度","90度","180度"]', 0, 2, '入射角は面に対する法線との角度です。垂直に入射すれば入射角は0度となり、反射角も0度になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズを通して見た虚像の特徴として正しいものは。', '["倒立像である","正立像である","スクリーンに映る","物体より小さい"]', 1, 2, '凸レンズでできる虚像は、物体と同じ向きの正立像であり、拡大されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の性質について、正しい説明はどれか。', '["音は真空中でも伝わる","音は物体が振動して発生する","音の高さは振幅で決まる","音の速さは光より速い"]', 1, 1, '音は物体が振動し、それが空気を伝わって耳に届く現象です。真空中では伝わりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねののびを測定する際、注意すべきことは。', '["ばねを強く引きすぎる","おもりの重さを無視する","自然の長さを基準にする","摩擦力を利用する"]', 2, 1, 'ばねののびは、つるした後の長さから自然の長さを引いて求めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力を表す単位Pa（パスカル）の定義は。', '["1m²あたり1N","1cm²あたり1N","1m²あたり1kg","1Nあたり1m²"]', 0, 2, '1Paは、1平方メートルの面積に1ニュートンの力が均等にかかる圧力のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光の直進性を示す現象はどれか。', '["鏡に映る像","影ができること","水中のコインの浮き上がり","虹ができる"]', 1, 1, '光が直進する性質があるため、光が物体に遮られると影ができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズで実像ができるとき、物体をレンズに近づけると像はどうなるか。', '["レンズから遠ざかり、大きくなる","レンズに近づき、小さくなる","レンズから遠ざかり、小さくなる","レンズに近づき、大きくなる"]', 0, 3, '物体をレンズに近づけると、像はレンズから遠ざかり、サイズは大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の高さが低いとき、振動数はどうなっているか。', '["多い","少ない","変わらない","0である"]', 1, 1, '振動数が少ないほど音は低く、多いほど音は高くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねののびが2cmのとき、おもりをもう一つ追加すると、のびは合計何cmになるか。', '["2cm","4cm","6cm","8cm"]', 1, 2, 'フックの法則により、おもりが2倍になればのびも2倍の4cmになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力の計算で、面積の単位をm²に直すとき、100cm²は何m²か。', '["0.1m²","0.01m²","1m²","10m²"]', 1, 3, '1m＝100cmなので、1m²＝10000cm²です。したがって100cm²＝0.01m²となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が反射するとき、入射角と反射角の和が120度の場合、入射角は何度か。', '["30度","60度","90度","120度"]', 1, 2, '入射角と反射角は等しいので、120÷2＝60度となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズの焦点距離が15cmのとき、物体をどこに置くと実像ができるか。', '["10cm","5cm","20cm","12cm"]', 2, 3, '凸レンズで実像ができるのは、物体を焦点距離（15cm）より外側に置いたときです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の振幅を大きくすると、どう聞こえるか。', '["高く聞こえる","低く聞こえる","大きく聞こえる","小さく聞こえる"]', 2, 1, '振幅は音の大きさを決定します。振幅を大きくすると音は大きく聞こえます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'フックの法則に関するグラフで、横軸に「力」、縦軸に「のび」をとったとき、グラフはどうなるか。', '["右上がりの曲線","原点を通る直線","水平な直線","右下がりの直線"]', 1, 2, 'のびは力に比例するため、グラフは原点を通る直線になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '同じ重さの物体を、スポンジの上に置くとき、圧力が最も小さいのは。', '["面積が最小の面","面積が最大の面","立てて置く","斜めに置く"]', 1, 2, '圧力は面積に反比例するため、面積が大きいほど圧力は小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光の屈折において、光が空気から水へ入る際、光はどちら側に曲がるか。', '["法線側","法線と反対側","直進する","反射する"]', 0, 3, '光が屈折率の小さい物質から大きい物質へ進むとき、光は法線の方へ折れ曲がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズの焦点距離をfとする。物体を2fより遠くに置いたとき、像はどこにできるか。', '["レンズの焦点の内側","焦点と2fの間","2fの外側","レンズの反対側の焦点"]', 1, 3, '物体が2fより遠い場合、実像はレンズの反対側の、焦点と2fの間にできます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の高さが変化する要因はどれか。', '["振幅","振動数","音の伝わる速さ","音の大きさ"]', 1, 1, '音の高さは振動数（Hz）によって決まります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねののびが0のとき、つるされているおもりの重さはいくらか。', '["0N","1N","2N","不明"]', 0, 1, 'フックの法則により、力が0であればのびも0になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '圧力の単位 Pa は、何という科学者の名前に由来するか。', '["ニュートン","パスカル","フック","アインシュタイン"]', 1, 1, '圧力の単位 Pa は、フランスの科学者ブレーズ・パスカルにちなんで名付けられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が全反射を起こす条件はどれか。', '["屈折率の大きい物質から小さい物質へ進むとき","屈折率の小さい物質から大きい物質へ進むとき","鏡に当たるとき","光が直進するとき"]', 0, 3, '全反射は、光が屈折率の大きい物質から小さい物質へ進むときに起こります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '凸レンズでできる実像について、正しい説明はどれか。', '["上下左右が逆","上下だけ逆","左右だけ逆","向きは同じ"]', 0, 2, '凸レンズによる実像は、上下左右が逆（倒立）になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '音の振動数が100Hzから200Hzに変わると、音はどうなるか。', '["高くなる","低くなる","大きくなる","小さくなる"]', 0, 2, '振動数が多いほど音は高くなるため、100Hzから200Hzになると音は高くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', 'ばねののびが4cmのとき、おもりを半分に減らすと、のびは何cmになるか。', '["1cm","2cm","4cm","8cm"]', 1, 2, '力が半分になれば、比例関係によりのびも半分の2cmになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '20Nの力を0.5m²の面に加えたときの圧力は。', '["10Pa","40Pa","100Pa","20Pa"]', 1, 2, '圧力＝力÷面積＝20N÷0.5m²＝40Paとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'science', '光が鏡で反射するとき、反射角が40度なら、入射角は何度か。', '["20度","40度","50度","80度"]', 1, 1, '反射の法則により、入射角と反射角は等しいため、40度になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが地表や地表近くで急激に冷えて固まった岩石を何というか。', '["火山岩","深成岩","堆積岩","変成岩"]', 0, 1, 'マグマが地表付近で急冷されてできる岩石は火山岩です。一方、地下深くでゆっくり冷えてできるのは深成岩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが地下深くでゆっくりと冷えて固まった岩石の組織を何というか。', '["斑状組織","等粒状組織","層理","葉理"]', 1, 1, '深成岩はゆっくり冷えるため、結晶が大きく成長し、全体が同じくらいの大きさの結晶で構成される等粒状組織になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火山岩に見られる、大きな結晶（斑晶）と細かい結晶（石基）からなる組織を何というか。', '["斑状組織","等粒状組織","柱状節理","流理構造"]', 0, 1, '急冷された部分が石基となり、先に成長した大きな結晶が斑晶として残る組織を斑状組織といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火成岩のうち、白っぽい色をした岩石に含まれることが多い鉱物はどれか。', '["石英","かんらん石","輝石","磁鉄鉱"]', 0, 2, '石英や長石は白っぽく、かんらん石や輝石は黒っぽい色をしています。そのため石英が多い岩石は白っぽくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、火山岩のグループに当てはまるものはどれか。', '["流紋岩","花崗岩","閃緑岩","斑れい岩"]', 0, 2, '流紋岩は火山岩です。花崗岩、閃緑岩、斑れい岩はすべて深成岩のグループです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマの粘り気が強く、爆発的な噴火をしやすい火山の形はどれか。', '["成層火山","盾状火山","溶岩ドーム","カルデラ"]', 0, 2, '粘り気が強いマグマはガスが抜けにくく爆発しやすいため、富士山のような円錐形の成層火山になりやすいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れにおいて、先に到達する小さな揺れを何というか。', '["初期微動","主要動","震度","マグニチュード"]', 0, 1, 'P波によって起こる小さな揺れを初期微動、その後に来る大きな揺れを主要動といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '初期微動が始まってから主要動が始まるまでの時間を何というか。', '["初期微動継続時間","震源時間","到達時間","揺れ幅"]', 0, 1, 'P波とS波の到達時刻の差が初期微動継続時間です。この時間が長いほど、震源からの距離が遠いことを示します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の規模（エネルギーの大きさ）を表す単位を何というか。', '["マグニチュード","震度","ガル","気圧"]', 0, 1, '地震そのもののエネルギーの大きさはマグニチュードで表します。震度はある地点での揺れの強さを表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'ある地点での揺れの強さを表す階級を何というか。', '["震度","マグニチュード","震源","震央"]', 0, 1, '気象庁震度階級は0から7までの10段階で、その場所の揺れの強さを表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '震源から真上の地表の地点を何というか。', '["震央","震源","震度","震央距離"]', 0, 1, '地震が発生した地下の場所が震源、その真上の地表の地点が震央です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '堆積岩のうち、泥が固まってできた岩石を何というか。', '["泥岩","砂岩","れき岩","石灰岩"]', 0, 1, '粒の大きさによって、泥岩（一番小さい）、砂岩、れき岩（一番大きい）に分類されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '堆積岩が層状に重なっている様子を何というか。', '["地層","節理","断層","しゅう曲"]', 0, 1, '土砂などが積み重なってできた層を地層といいます。堆積岩は地層を構成する主要な岩石です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '化石のうち、その地層が堆積した当時の環境を知る手がかりになるものを何というか。', '["示相化石","示準化石","標準化石","示地化石"]', 0, 2, '示相化石は、サンゴやシジミのように特定の環境でしか生きられない生物の化石で、当時の環境を教えてくれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層ができた年代を決定する手がかりとなる化石を何というか。', '["示準化石","示相化石","古生物","化石燃料"]', 0, 2, '示準化石は、特定の短い期間に広く生息していた生物の化石で、地層の年代を特定するのに使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'うすい塩酸をかけると二酸化炭素が発生する堆積岩はどれか。', '["石灰岩","砂岩","泥岩","凝灰岩"]', 0, 2, '石灰岩は炭酸カルシウムを主成分とするため、塩酸と反応して二酸化炭素を発生させます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火山の噴火で放出された火山灰などが固まってできた岩石を何というか。', '["凝灰岩","泥岩","砂岩","チャート"]', 0, 2, '火山灰が堆積してできた岩石を凝灰岩といいます。地層の年代を特定する鍵層として重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'P波とS波のうち、伝わる速さが速いのはどちらか。', '["P波","S波","どちらも同じ","震度によって変わる"]', 0, 2, 'P波は速く伝わり、S波は遅く伝わります。この速さの差によって初期微動継続時間が生じます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマの粘り気が非常に小さく、サラサラしているマグマが作る火山の形はどれか。', '["盾状火山","成層火山","溶岩ドーム","カルデラ"]', 0, 2, '粘り気が小さいマグマは遠くまで流れるため、傾斜の緩やかな盾状火山になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れが、震源から遠ざかるにつれて小さくなる理由として適切なものはどれか。', '["エネルギーが広がるため","P波が消えるため","S波が消えるため","地層が吸収するため"]', 0, 2, '地震のエネルギーは震源から球面状に伝わるため、距離が離れるほど単位面積あたりのエネルギーは小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、深成岩のグループはどれか。', '["花崗岩","安山岩","玄武岩","流紋岩"]', 0, 2, '花崗岩は地下深くでゆっくり冷えて固まった深成岩です。他はすべて火山岩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層の重なりにおいて、下の層ほど古いという原則を何というか。', '["地層累重の法則","プレートテクトニクス","大陸移動説","進化論"]', 0, 1, '地層は下から順に積み重なるため、下の層が古く、上の層が新しいという原則を地層累重の法則といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'アンモナイトの化石は、何時代の示準化石として有名か。', '["中生代","古生代","新生代","先カンブリア時代"]', 0, 2, 'アンモナイトは中生代に栄えた生物で、中生代の地層を特定する代表的な示準化石です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震計で記録された波のグラフにおいて、P波が到着した時刻を何というか。', '["P波到着時刻","S波到着時刻","初期微動開始時刻","主要動開始時刻"]', 0, 2, '地震計の記録で、最初の小さな揺れが始まった時刻がP波到着時刻です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、火山岩の組織として正しいものはどれか。', '["斑状組織","等粒状組織","層理","葉理"]', 0, 1, '火山岩は急冷されるため、斑晶と石基からなる斑状組織が見られます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '堆積岩の中で、粒の大きさが2mm以上の角ばった岩石を何というか。', '["れき岩","砂岩","泥岩","凝灰岩"]', 0, 2, 'れき岩は2mm以上の大きな粒が集まってできた岩石です。角ばっているものは特に角れき岩と呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の震源が深い場合、震央付近の震度はどうなるか。', '["小さくなる","大きくなる","変わらない","マグニチュードに比例する"]', 0, 3, '震源が深いと、地表に到達するまでの距離が長くなるため、震央付近の震度は小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、黒っぽい色をした火成岩に含まれることが多い鉱物はどれか。', '["かんらん石","石英","長石","白雲母"]', 0, 2, 'かんらん石や輝石は黒っぽく、これらを多く含む岩石（玄武岩や斑れい岩）は黒っぽい色をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層が波打つように曲がっている構造を何というか。', '["しゅう曲","断層","節理","貫入"]', 0, 2, '地層に横からの大きな力が加わって曲がった構造を、しゅう曲といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '三葉虫の化石は、主に何時代の示準化石か。', '["古生代","中生代","新生代","先カンブリア時代"]', 0, 2, '三葉虫は古生代に繁栄した生物で、古生代の地層を特定する重要な示準化石です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが冷えて固まる際にできる、規則的な割れ目を何というか。', '["節理","断層","しゅう曲","層理"]', 0, 2, 'マグマが冷えて収縮する際にできる規則的な割れ目を節理といいます。柱状節理などが有名です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火山岩の「石基」を構成する細かい結晶は何によるものか。', '["急激な冷却","ゆっくりとした冷却","高い圧力","化学反応"]', 0, 2, '急激に冷えると結晶が大きく成長する時間がなく、小さな結晶の集まりである石基になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'ビカリアの化石は、何時代の示準化石か。', '["新生代","古生代","中生代","先カンブリア時代"]', 0, 2, 'ビカリアは新生代の地層から見つかる示準化石です。貝の化石として有名です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れを記録する装置を何というか。', '["地震計","震度計","マグニチュード計","気圧計"]', 0, 1, '地震計は地面の揺れを記録する装置で、P波とS波の到着時刻の差を読み取るために使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層がずれている構造を何というか。', '["断層","しゅう曲","節理","層理"]', 0, 1, '地層に力が加わって破壊され、ずれたものを断層といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、深成岩の組織として正しいものはどれか。', '["等粒状組織","斑状組織","柱状節理","流理構造"]', 0, 1, '深成岩はゆっくり冷えるため、結晶が大きく成長し、全体が等粒状組織になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが地層の間に割れ目を通って入り込み、固まったものを何というか。', '["貫入","堆積","侵食","風化"]', 0, 2, 'マグマが既存の岩石層に割り込んで固まる現象を貫入といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、白っぽい火成岩の組み合わせはどれか。', '["花崗岩と流紋岩","玄武岩と斑れい岩","安山岩と閃緑岩","玄武岩と流紋岩"]', 0, 3, '花崗岩と流紋岩は、どちらも石英や長石を多く含み、白っぽい色をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の発生場所を何というか。', '["震源","震央","震度","マグニチュード"]', 0, 1, '地震が実際に発生した地下の地点を震源といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '堆積岩のうち、プランクトンの死骸などが固まってできたものはどれか。', '["チャート","れき岩","砂岩","泥岩"]', 0, 2, 'チャートは放散虫などのプランクトンの殻が堆積してできた非常に硬い岩石です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れが伝わる際、P波が伝わる速さはS波と比べてどうであるか。', '["速い","遅い","同じ","震源による"]', 0, 1, 'P波はS波よりも速く伝わるため、地震計では先にP波が記録されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火山岩の「斑晶」は何を意味するか。', '["先に成長した大きな結晶","急冷された細かい結晶","マグマの気泡","岩石の割れ目"]', 0, 2, '斑晶は、マグマが地下でゆっくり冷えていた時に成長した結晶が、その後の急冷でそのまま残ったものです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、火山岩のグループはどれか。', '["安山岩","花崗岩","閃緑岩","斑れい岩"]', 0, 2, '安山岩は火山岩です。花崗岩、閃緑岩、斑れい岩はすべて深成岩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '震源からの距離を求めるために必要なものはどれか。', '["初期微動継続時間","震度","マグニチュード","震央の深さ"]', 0, 2, '初期微動継続時間は震源からの距離に比例するため、これを利用して距離を計算します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層が堆積する際、粒の大きいものから順に沈む現象を何というか。', '["級化層理","断層","しゅう曲","貫入"]', 0, 3, '土砂が水中で堆積する際、粒の大きいものが先に沈むことでできる構造を級化層理といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、黒っぽい火成岩の組み合わせはどれか。', '["玄武岩と斑れい岩","流紋岩と花崗岩","安山岩と閃緑岩","流紋岩と閃緑岩"]', 0, 3, '玄武岩と斑れい岩は、かんらん石や輝石を多く含み、黒っぽい色をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の規模を表す「マグニチュード」が1増えると、エネルギーは何倍になるか。', '["約32倍","約10倍","約2倍","約100倍"]', 0, 3, 'マグニチュードが1増えると、地震のエネルギーは約32倍になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '次のうち、堆積岩ではないものはどれか。', '["花崗岩","砂岩","泥岩","石灰岩"]', 0, 1, '花崗岩は火成岩（深成岩）であり、堆積岩ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れにおいて、S波が引き起こすのはどちらの揺れか。', '["主要動","初期微動","震度","マグニチュード"]', 0, 2, 'S波はP波よりも遅れて到達し、大きな揺れである主要動を引き起こします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層の年代を特定するのに適した化石の条件として、誤っているものはどれか。', '["生息期間が長い","広く分布している","個体数が多い","特徴がはっきりしている"]', 0, 2, '示準化石は、特定の短い期間に広く生息していた生物である必要があります。生息期間が長いと年代を特定できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが冷えて固まった岩石を総称して何というか。', '["火成岩","堆積岩","変成岩","火成岩以外の岩石"]', 0, 1, 'マグマが冷えて固まった岩石を火成岩といい、火山岩と深成岩に分けられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層ができた当時の環境を示す化石として、適さないものはどれか。', '["示準化石","サンゴ","シジミ","貝の化石"]', 0, 2, '示準化石は年代を特定するためのもので、環境を示すのは示相化石です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の波において、地表を伝わる波を何というか。', '["表面波","P波","S波","初期微動"]', 0, 3, 'P波やS波は地球内部を伝わりますが、地表付近を伝わる波を表面波といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '火山岩の分類で、中間の色を持つものはどれか。', '["安山岩","玄武岩","流紋岩","花崗岩"]', 0, 2, '安山岩は白っぽい流紋岩と黒っぽい玄武岩の中間の色をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層が堆積する際、水の流れが弱まるとどうなるか。', '["細かい粒が沈む","粗い粒が沈む","何も沈まない","岩石が溶ける"]', 0, 2, '水の流れが速いと粗い粒が運ばれ、流れが弱まると細かい粒が沈殿します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の震源が浅い場合、震央付近の震度はどうなるか。', '["大きくなる","小さくなる","変わらない","マグニチュードに反比例する"]', 0, 2, '震源が浅いと、地表までの距離が短いため、震央付近の揺れは大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地震の揺れを大きく感じるのは、どのような地盤か。', '["軟らかい地盤","硬い岩盤","山地","火山地帯"]', 0, 2, '軟らかい地盤は地震の揺れを増幅させるため、硬い岩盤よりも揺れが大きくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', '地層の重なりにおいて、火山灰の層はなぜ重要か。', '["同時期に堆積した証拠だから","化石が含まれるから","硬いから","色が白いから"]', 0, 2, '火山灰は短期間に広範囲に降り積もるため、離れた場所の地層を比較する鍵層として役立ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'science', 'マグマが冷えてできる火成岩の分類で、結晶の大きさで決まるのはどれか。', '["冷却速度","マグマの粘り気","噴火の規模","地層の厚さ"]', 0, 2, '結晶の大きさは、マグマが冷える速度によって決まります。ゆっくり冷えると大きく、急冷されると小さくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球の表面で、陸地と海洋の面積の割合はおよそどれくらいですか。', '["陸地約3：海洋約7","陸地約4：海洋約6","陸地約2：海洋約8","陸地約5：海洋約5"]', 0, 1, '地球の表面は、約3割が陸地、約7割が海洋で構成されています。この比率は地理の基本知識として必ず覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界で最も面積が大きい大陸はどれですか。', '["アフリカ大陸","北アメリカ大陸","ユーラシア大陸","南アメリカ大陸"]', 2, 1, 'ユーラシア大陸は世界最大の大陸です。2番目はアフリカ大陸、3番目は北アメリカ大陸の順になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界で最も面積が広い海洋はどれですか。', '["太平洋","大西洋","インド洋","北極海"]', 0, 1, '太平洋は世界最大の海洋です。面積は地球の表面積の約3分の1を占めています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '緯度0度の線を何といいますか。', '["本初子午線","赤道","北回帰線","南回帰線"]', 1, 1, '緯度0度の線を赤道と呼び、ここを境に北半球と南半球に分けられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '経度0度の線が通っているイギリスの都市はどこですか。', '["ロンドン","グリニッジ","リバプール","マンチェスター"]', 1, 2, '経度0度の本初子午線は、イギリスの旧グリニッジ天文台を通っています。ここが経度の基準です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '時差の計算において、日本（東経135度）とロンドン（経度0度）の時差は何時間ですか。', '["7時間","8時間","9時間","10時間"]', 2, 2, '経度15度で1時間の時差が生じます。135÷15＝9なので、日本はロンドンより9時間進んでいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '一年中高温多雨で、熱帯雨林が広がる気候帯を何といいますか。', '["熱帯","乾燥帯","温帯","冷帯"]', 0, 1, '熱帯は赤道付近に広がり、気温が高く雨が多いのが特徴です。ジャングルなどの熱帯雨林が見られます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '乾燥帯で見られる、昼夜の気温差が激しい場所はどこですか。', '["サバンナ","砂漠","ステップ","ツンドラ"]', 1, 2, '砂漠は降水量が極めて少なく、日差しが強いため昼は非常に暑く、夜は放射冷却で冷え込みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯に分類される気候のうち、夏に雨が多く冬に乾燥する気候はどれですか。', '["温暖湿潤気候","地中海性気候","西岸海洋性気候","熱帯雨林気候"]', 1, 3, '地中海性気候は、夏は乾燥し、冬に雨が降るのが特徴です。オリーブやブドウの栽培が盛んです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '北半球の高緯度地域に広がり、冬の寒さが非常に厳しい気候帯はどれですか。', '["温帯","冷帯","熱帯","乾燥帯"]', 1, 2, '冷帯はユーラシア大陸や北アメリカ大陸の北部に分布し、夏と冬の気温差が非常に大きいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '一年中氷雪に覆われ、樹木が育たない気候帯を何といいますか。', '["冷帯","寒帯","乾燥帯","温帯"]', 1, 1, '寒帯は極地に近い地域で、一年中気温が低く、氷雪気候やツンドラ気候が見られます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '日本が属している気候帯はどれですか。', '["熱帯","乾燥帯","温帯","冷帯"]', 2, 1, '日本は四季の変化がはっきりした温帯に属しています。ただし、北海道などは冷帯に近い特徴もあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '緯度が高い場所ほど、太陽の光はどのように当たりますか。', '["直射する","斜めに当たる","全く当たらない","真上から当たる"]', 1, 2, '緯度が高い（極に近い）ほど太陽光は斜めに届くため、単位面積あたりの熱量が少なくなり、気温が低くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', 'サバンナ気候で見られる、雨季と乾季がある植生はどれですか。', '["密林","草原","氷河","針葉樹林"]', 1, 2, 'サバンナは熱帯の一部で、雨季には背の高い草が生え、乾季には乾燥する草原地帯です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', 'ステップ気候で見られる短い草の草原を何といいますか。', '["サバンナ","ステップ","プレーリー","パンパ"]', 1, 2, 'ステップ気候は砂漠の周辺に分布し、短い草が生える草原地帯です。遊牧が行われることが多いです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '西岸海洋性気候の特徴として正しいものはどれですか。', '["夏に非常に暑い","一年中気温の変化が小さい","冬に雨が降らない","一年中乾燥している"]', 1, 3, '西岸海洋性気候は、暖流と偏西風の影響で、高緯度の割に冬の寒さが厳しくなく、気温の年較差が小さいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '北極圏で見られる、夏の間だけ地表の氷が溶けてコケなどが生える気候を何といいますか。', '["氷雪気候","ツンドラ気候","冷帯気候","高山気候"]', 1, 3, 'ツンドラ気候は寒帯の一部で、短い夏にわずかな植物が生育します。永久凍土層が見られるのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界の六大陸のうち、面積が小さい順に並べたとき、オーストラリア大陸は何番目ですか。', '["4番目","5番目","6番目","3番目"]', 2, 3, 'ユーラシア、アフリカ、北アメリカ、南アメリカ、南極、オーストラリアの順で、オーストラリアが最も小さいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '時差の計算で、東経135度の日本が午前9時のとき、東経45度の場所は何時ですか。', '["午前3時","午前6時","午後3時","午前9時"]', 0, 3, '経度差は135-45＝90度。90÷15＝6時間。東にある日本の方が進んでいるので、45度は6時間遅い3時になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球儀で、同じ経度を結ぶ線を何といいますか。', '["緯線","経線","赤道","本初子午線"]', 1, 1, '経線は北極と南極を結ぶ線です。すべての経線は長さが同じです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球儀で、赤道に平行な線を何といいますか。', '["緯線","経線","本初子午線","日付変更線"]', 0, 1, '緯線は赤道と平行に引かれた線です。赤道から離れるほど円の長さは短くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '三大洋に含まれないものはどれですか。', '["太平洋","大西洋","インド洋","北極海"]', 3, 2, '三大洋は太平洋、大西洋、インド洋です。北極海はこれに含まれません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '熱帯の気候区分に含まれるのはどれですか。', '["熱帯雨林気候","地中海性気候","西岸海洋性気候","ツンドラ気候"]', 0, 2, '熱帯には熱帯雨林気候やサバンナ気候が含まれます。他は温帯や寒帯の気候です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の温暖湿潤気候の特徴として正しいものはどれですか。', '["一年中雨が少ない","夏と冬の気温差が大きい","一年中気温が高い","冬に雪が降らない"]', 1, 3, '温暖湿潤気候は、季節による気温の変化が大きく、年間を通じて降水があるのが特徴です。日本もこれに該当します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '標高が高い場所で見られる、平地とは異なる気候を何といいますか。', '["高山気候","寒帯気候","冷帯気候","乾燥気候"]', 0, 2, '標高が高い場所は、低緯度にあっても気温が低くなる高山気候になります。アンデス山脈などが有名です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '北回帰線は北緯何度ですか。', '["北緯23.4度","北緯30度","北緯66.6度","北緯45度"]', 0, 3, '北回帰線は北緯23.4度、南回帰線は南緯23.4度です。地球の地軸の傾きに関係しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '日付変更線は、主にどの大洋を通っていますか。', '["太平洋","大西洋","インド洋","北極海"]', 0, 2, '日付変更線は、経度180度付近の太平洋上を通っています。ここを越えるときは日付を修正します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界で最も面積が小さい大陸はどれですか。', '["南極大陸","オーストラリア大陸","ヨーロッパ大陸","南アメリカ大陸"]', 1, 2, 'オーストラリア大陸は六大陸の中で最も小さい大陸です。大陸としては最小ですが、国としては広大です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '乾燥帯の砂漠で、地下水を利用して作られるオアシス周辺の農業を何といいますか。', '["オアシス農業","焼畑農業","企業的農業","放牧"]', 0, 2, '砂漠地帯では、地下水が湧き出るオアシス周辺でナツメヤシなどを栽培するオアシス農業が行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '冷帯の北部に広がる、針葉樹の森林を何といいますか。', '["ジャングル","サバンナ","タイガ","ステップ"]', 2, 3, 'タイガは冷帯に広がる広大な針葉樹林帯です。シベリアやカナダなどに広く分布しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球の形を説明する言葉として最も適切なものはどれですか。', '["完全な球体","赤道方向に少しふくらんだ回転楕円体","南北方向に長い楕円体","平らな円盤状"]', 1, 3, '地球は自転による遠心力で、赤道付近がわずかにふくらんだ形をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の地中海性気候で、夏に乾燥する理由は何ですか。', '["亜熱帯高圧帯の影響を受けるから","偏西風が吹かないから","海流が冷たいから","標高が高いから"]', 0, 1, '夏には亜熱帯高圧帯という乾燥した空気の塊が移動してくるため、雨がほとんど降りません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '南半球にある大陸はどれですか。', '["北アメリカ大陸","ヨーロッパ大陸","オーストラリア大陸","アジア大陸"]', 2, 2, 'オーストラリア大陸は完全に南半球に位置しています。南極大陸も南半球です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '経度15度につき、時差は何時間ですか。', '["1時間","2時間","30分","15分"]', 0, 1, '地球は1日で360度回転します。360÷24時間＝15度。つまり15度で1時間の時差が生じます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '熱帯雨林気候で見られる、スコールとはどのような雨ですか。', '["一日中降り続く雨","激しいにわか雨","冬に降る雪","霧のような雨"]', 1, 2, 'スコールは熱帯で午後に発生しやすい、激しいにわか雨のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '寒帯の氷雪気候で、一年中氷に覆われている場所はどこですか。', '["グリーンランドや南極大陸","シベリア地方","北欧","カナダ北部"]', 0, 3, '南極大陸やグリーンランドは氷雪気候で、一年中気温が氷点下で氷に覆われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界の六大陸のうち、赤道が通っていない大陸はどれですか。', '["アフリカ大陸","南アメリカ大陸","アジア大陸","ヨーロッパ大陸"]', 3, 1, 'ヨーロッパ大陸はすべて北半球の高緯度側に位置しているため、赤道は通りません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の西岸海洋性気候の代表的な都市はどこですか。', '["ロンドン","ローマ","東京","ニューヨーク"]', 0, 3, 'ロンドンは西岸海洋性気候の代表例です。一年を通じて降水があり、気温差が小さいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '乾燥帯のステップ気候で、伝統的に行われている生活様式はどれですか。', '["稲作","遊牧","林業","漁業"]', 1, 2, 'ステップ気候では、草を求めて家畜とともに移動する遊牧が行われてきました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '緯度を測る基準となるのは赤道ですが、経度を測る基準となるのは何ですか。', '["北極点","南極点","本初子午線","日付変更線"]', 2, 1, '経度はロンドンの旧グリニッジ天文台を通る本初子午線を0度として測ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '冷帯の気候の特徴として正しいものはどれですか。', '["夏と冬の気温差が大きい","一年中気温が高い","冬に雨が多い","一年中乾燥している"]', 0, 3, '冷帯は夏は気温が上がりますが、冬は非常に寒くなるため、気温の年較差が非常に大きいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球の表面積のうち、海洋が占める割合はおよそ何％ですか。', '["約50％","約60％","約70％","約80％"]', 2, 1, '地球の表面は約7割が海洋、約3割が陸地です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の気候区分に含まれないものはどれですか。', '["温暖湿潤気候","地中海性気候","西岸海洋性気候","サバンナ気候"]', 3, 2, 'サバンナ気候は熱帯の気候区分です。温帯には温暖湿潤、地中海性、西岸海洋性などが含まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '北極海に面している大陸はどれですか。', '["アジア大陸","オーストラリア大陸","アフリカ大陸","南アメリカ大陸"]', 0, 3, 'アジア大陸の北部は北極海に面しています。北アメリカ大陸やヨーロッパ大陸も同様です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '時差の計算で、ロンドンが正午のとき、東経135度の日本は何時ですか。', '["午後9時","午前3時","午後6時","午前9時"]', 0, 2, '日本はロンドンより9時間進んでいるため、ロンドンが正午（12時）なら、日本は午後9時になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '熱帯雨林気候で、農業に適さない理由として挙げられるものはどれですか。', '["雨が多すぎて土壌の養分が流出するから","気温が低すぎるから","乾燥しすぎているから","冬が寒すぎるから"]', 0, 1, '熱帯雨林は雨が多いため、土壌の養分が流れてしまい、農業にはあまり適していません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '高山気候の特徴として正しいものはどれですか。', '["標高が高いほど気温が低い","標高が高いほど気温が高い","一年中暑い","一年中雪が降る"]', 0, 2, '高山気候は標高が上がるにつれて気温が下がります。そのため低緯度でも山頂付近は寒くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '六大陸のうち、赤道が通っている大陸はどれですか。', '["アフリカ大陸","ヨーロッパ大陸","オーストラリア大陸","北アメリカ大陸"]', 0, 2, 'アフリカ大陸は赤道がほぼ中央を通っています。南アメリカ大陸にも赤道は通っています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '乾燥帯の砂漠気候で、昼夜の気温差が大きい理由は何ですか。', '["雲が少なく日差しが強いから","海が近いから","標高が高いから","風が強いから"]', 0, 3, '砂漠は湿度が低く雲が少ないため、昼は太陽光を直接受け、夜は熱が宇宙へ逃げていくため気温差が激しいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の地中海性気候で、栽培が盛んな農作物はどれですか。', '["オリーブやブドウ","米","小麦","カカオ"]', 0, 2, '地中海性気候は夏に乾燥するため、乾燥に強いオリーブやブドウの栽培が伝統的に行われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '地球の自転の向きはどちらですか。', '["西から東","東から西","北から南","南から北"]', 0, 2, '地球は西から東へ自転しています。そのため、東にある地域ほど日の出が早くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '冷帯にある都市として有名なのはどこですか。', '["モスクワ","ロンドン","シンガポール","カイロ"]', 0, 3, 'ロシアのモスクワは冷帯に位置し、冬の寒さが非常に厳しい都市です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '寒帯のツンドラ気候で見られる、夏に現れる植物は何ですか。', '["コケや地衣類","熱帯雨林","針葉樹","広葉樹"]', 0, 2, 'ツンドラ気候では、短い夏に氷が溶けた地表にコケや地衣類、小さな草花が生育します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '経度180度付近を通る線を何といいますか。', '["日付変更線","赤道","本初子午線","北回帰線"]', 0, 2, '経度180度付近は日付変更線です。ここを越えるときに日付を1日ずらします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '温帯の温暖湿潤気候の日本で、夏に雨が多い理由は何ですか。', '["季節風（モンスーン）の影響","偏西風の影響","貿易風の影響","寒流の影響"]', 0, 1, '日本は夏に海から吹く季節風の影響で高温多雨になります。これが稲作に適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '六大陸の中で、最も面積が大きい大陸はどれですか。', '["ユーラシア大陸","アフリカ大陸","北アメリカ大陸","南アメリカ大陸"]', 0, 1, 'ユーラシア大陸は世界最大の大陸です。2位のアフリカ大陸の約1.5倍の広さがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '乾燥帯の砂漠気候で、家畜を連れて移動する生活を何といいますか。', '["遊牧","定住農業","焼畑農業","企業的農業"]', 0, 2, '砂漠やステップ気候では、水や草を求めて家畜とともに移動する遊牧が行われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '熱帯雨林気候で見られる、木の上に家を建てる理由は何ですか。', '["湿気や害虫を防ぐため","洪水に備えるため","太陽光を避けるため","風通しを良くするため"]', 0, 3, '熱帯雨林は湿度が高く害虫も多いため、高床式にして地面から離して生活する知恵があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '世界で最も面積が広い国はどこですか。', '["ロシア","カナダ","中国","アメリカ"]', 0, 2, 'ロシアは世界最大の面積を持つ国です。ユーラシア大陸の北部に位置しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'social_studies', '緯度0度の赤道付近の気候は、一年中どうなっていますか。', '["高温多雨","低温乾燥","高温乾燥","低温多雨"]', 0, 2, '赤道付近は太陽の光を強く受けるため、一年中気温が高く、上昇気流により雨が多く降ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の領海は、基線から何海里までと定められていますか。', '["12海里","24海里","200海里","350海里"]', 0, 1, '領海は基線から12海里までです。200海里は排他的経済水域（EEZ）の範囲を指すため、混同しないようにしましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '排他的経済水域（EEZ）において、日本が権利を行使できる範囲は基線から何海里までですか。', '["12海里","24海里","200海里","350海里"]', 2, 1, '排他的経済水域は、基線から200海里までの範囲です。この水域では、水産資源や海底の鉱物資源を開発する権利が認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本が領土として主張しているが、現在他国が占拠している北方領土に含まれない島はどれですか。', '["択捉島","国後島","色丹島","佐渡島"]', 3, 1, '北方領土は択捉島、国後島、色丹島、歯舞群島の4島です。佐渡島は新潟県に属する日本の領土です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本最南端の島である沖ノ鳥島は、どの都道府県に属していますか。', '["沖縄県","東京都","鹿児島県","北海道"]', 1, 1, '沖ノ鳥島は東京都小笠原村に属しています。遠く離れていますが、日本の領土として重要な役割を果たしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アジア州で最も人口が多い国はどこですか。', '["中国","インド","インドネシア","日本"]', 1, 1, '2023年以降、インドの人口が中国を追い抜き、世界第1位となりました。アジア州の人口動態は常に変化しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '西アジアで産出される資源として最も代表的なものは何ですか。', '["石炭","鉄鉱石","石油","金"]', 2, 1, '西アジアは世界の石油の主要な供給源です。ペルシャ湾周辺には巨大な油田が集中しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパ州の北部に位置し、フィヨルドが見られる国はどこですか。', '["ノルウェー","イタリア","スペイン","ギリシャ"]', 0, 1, 'ノルウェーはスカンジナビア半島に位置し、氷河によって削られた深い入り江であるフィヨルドが有名です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパ連合（EU）の共通通貨は何ですか。', '["ドル","ポンド","ユーロ","フラン"]', 2, 1, 'ユーロはEUの多くの加盟国で導入されている共通通貨です。経済的な結びつきを強める役割を果たしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アフリカ州で最大の面積を持つ国はどこですか。', '["エジプト","南アフリカ共和国","アルジェリア","ナイジェリア"]', 2, 1, 'アルジェリアはアフリカ大陸で最も面積が広い国です。以前はスーダンが最大でしたが、分離独立により順位が変わりました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の地方区分で「北陸地方」が含まれるのはどの地方ですか。', '["東北地方","関東地方","中部地方","近畿地方"]', 2, 1, '中部地方は、北陸・中央高地・東海の3つに分けられます。北陸地方は日本海側に面しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本で最も面積が広い都道府県はどこですか。', '["北海道","岩手県","長野県","新潟県"]', 0, 1, '北海道は日本全体の面積の約22％を占めており、都道府県の中で最大の面積です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパ州の気候で、大陸西岸に一年中吹く風の影響で温暖な気候になるのは何ですか。', '["季節風","偏西風","貿易風","極東風"]', 1, 1, 'ヨーロッパ西部は偏西風と北大西洋海流の影響を受け、緯度の割に温暖で雨が多い気候です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アフリカ州の気候帯で、赤道付近に広がる気候はどれですか。', '["熱帯","乾燥帯","温帯","冷帯"]', 0, 1, '赤道付近は太陽光を強く受けるため、一年中高温多雨の熱帯気候となります。熱帯雨林が広がっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の領土のうち、最も東に位置する島はどこですか。', '["南鳥島","沖ノ鳥島","対馬","与那国島"]', 0, 1, '南鳥島は日本の最東端に位置する島です。東京都小笠原村に属しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アジア州の気候で、夏に海から陸へ吹く風を何といいますか。', '["偏西風","季節風（モンスーン）","貿易風","フェーン"]', 1, 1, 'アジアのモンスーン気候では、夏に海から湿った風が吹き込み、雨が多くなります。農業に大きな影響を与えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパのアルプス山脈で、かつて氷河によって削られた谷に海水が入り込んでできた地形を何といいますか。', '["リアス海岸","フィヨルド","砂丘","三角州"]', 1, 1, 'フィヨルドはU字谷が沈水してできた地形です。ノルウェーの海岸線に多く見られます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アフリカ州で、かつてヨーロッパ諸国の植民地支配を受けていた歴史的背景に関連する言語はどれですか。', '["公用語としての英語やフランス語","日本語","中国語","ロシア語"]', 0, 1, '多くのアフリカ諸国はヨーロッパの植民地だったため、現在も旧宗主国の言語が公用語として使われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の都道府県で、政令指定都市が最も多い地方はどこですか。', '["北海道地方","近畿地方","九州地方","四国地方"]', 1, 1, '近畿地方には大阪市、京都市、神戸市、堺市など多くの政令指定都市が集中しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパ州の東部に広がる平原を何といいますか。', '["東ヨーロッパ平原","中央平原","大草原","パンパ"]', 0, 1, '東ヨーロッパ平原はヨーロッパ州の大部分を占める広大な平原です。農業が盛んに行われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アジア州で、かつて「世界の工場」と呼ばれ、現在は経済成長が著しい国はどこですか。', '["中国","日本","韓国","モンゴル"]', 0, 1, '中国は豊富な労働力を背景に工業製品を大量生産し、世界の工場と呼ばれました。現在は技術革新も進んでいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の排他的経済水域（EEZ）の広さは、世界で何番目ですか。', '["1位","3位","6位","10位"]', 2, 1, '日本は周囲を海に囲まれているため、EEZの面積は世界で6番目に広いです。海洋資源の確保が重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパ州で、地中海に面した国はどれですか。', '["イタリア","ドイツ","ポーランド","スウェーデン"]', 0, 1, 'イタリアは地中海に突き出した半島国家です。地中海性気候の影響で、オリーブやブドウの栽培が盛んです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アフリカ州で、サハラ砂漠の南側に広がる乾燥した地域を何といいますか。', '["サヘル","サバンナ","ステップ","オアシス"]', 0, 1, 'サヘルは砂漠化が問題となっている地域です。近年、気候変動の影響で乾燥化が進んでいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本の地方区分において、四国地方に含まれる県はいくつありますか。', '["2つ","3つ","4つ","5つ"]', 2, 1, '四国地方は徳島県、香川県、愛媛県、高知県の4県で構成されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アジア州の西部に位置し、乾燥した気候が特徴の地域はどこですか。', '["東南アジア","西アジア","東アジア","中央アジア"]', 1, 1, '西アジアは砂漠が多く、乾燥した気候です。石油資源が豊富であることで知られています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'ヨーロッパの気候区分で、夏に乾燥し冬に雨が降る気候を何といいますか。', '["西岸海洋性気候","地中海性気候","冷帯気候","温暖湿潤気候"]', 1, 1, '地中海性気候は、夏に高温乾燥、冬に温暖湿潤となるのが特徴です。果樹栽培に適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', 'アフリカ州で、世界最長のナイル川が流れる国はどれですか。', '["エジプト","南アフリカ","ケニア","コンゴ"]', 0, 1, 'ナイル川はアフリカ大陸を北に流れ、エジプトを通って地中海に注ぎます。古代文明の発祥地です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'social_studies', '日本で最も北に位置する都道府県はどこですか。', '["青森県","秋田県","北海道","岩手県"]', 2, 1, '北海道は日本の最北端に位置する都道府県です。冷涼な気候が特徴です。', NULL);
