INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '藤原道長が詠んだとされる、自身の栄華を月になぞらえた歌はどれか。', '["この世をばわが世とぞ思ふ望月の","ちはやぶる神代も聞かず竜田川","ひさかたの光のどけき春の日に","秋来ぬと目にはさやかに見えねども"]', 0, 1, '「この世をばわが世とぞ思ふ望月の欠けたることもなしと思へば」という歌は、道長の全盛期を象徴する有名な歌です。', NULL);
