INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代に、貴族の住居として発達した建築様式を何というか。', '["寝殿造","書院造","数寄屋造","竪穴住居"]', 0, 1, '寝殿造は、中央の寝殿と左右の対の屋を渡殿でつなぐ、平安時代の貴族の住宅様式です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '1185年、壇の浦の戦いで平氏を滅ぼし、鎌倉幕府を開いた人物は誰か。', '["源頼朝","源義経","平清盛","足利尊氏"]', 0, 1, '源頼朝は1185年に守護・地頭を設置する権利を得て、その後1192年に征夷大将軍に任命され鎌倉幕府を開きました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府において、将軍が御家人に領地を保証することを何というか。', '["本領安堵","新恩給与","御恩","奉公"]', 0, 1, '将軍が御家人の領地を保証することを「本領安堵」、新しい領地を与えることを「新恩給与」といい、これらを合わせて「御恩」と呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府において、御家人が将軍のために軍役や番役を務める義務を何というか。', '["奉公","御恩","年貢","公事"]', 0, 1, '御恩に対する見返りとして、御家人が軍役や京都大番役などの務めを果たすことを「奉公」といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府において、軍事・警察権を行使し、国ごとに置かれた役職は何か。', '["守護","地頭","国司","執権"]', 0, 1, '守護は軍事・警察権を担い、地頭は荘園や公領の管理・年貢の徴収を行いました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '1232年、北条泰時が定めた武家社会の最初の法律は何か。', '["御成敗式目","建武式目","武家諸法度","公事方御定書"]', 0, 1, '御成敗式目は、裁判の公平さを保つために北条泰時が制定した、武士のための最初の法律です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '元寇の際、幕府軍が防戦のために博多湾岸に築いたものは何か。', '["石築地","土塁","城郭","関所"]', 0, 1, '元軍の再襲来に備えて、幕府は博多湾岸に石の壁（石築地・元寇防塁）を築きました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府が滅亡するきっかけとなった、御家人の不満の原因は何か。', '["御恩が与えられなかったこと","天皇の命令が強かったこと","外国からの侵略","飢饉による人口減少"]', 0, 1, '元寇では外国との戦いであり、奪った土地がないため御恩（土地の分配）ができず、御家人の不満が高まりました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町幕府を開いた人物は誰か。', '["足利尊氏","足利義満","足利義政","北条時宗"]', 0, 1, '足利尊氏は後醍醐天皇の建武の新政を倒し、京都に室町幕府を開きました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '足利義満が明との間で行った貿易を何というか。', '["日明貿易","日宋貿易","勘合貿易","南蛮貿易"]', 0, 1, '足利義満は明との貿易を行い、倭寇と正規の貿易船を区別するために「勘合」を用いたため、勘合貿易とも呼ばれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、京都の東山に建てられた銀閣の正式名称は何か。', '["慈照寺","鹿苑寺","金閣寺","平等院"]', 0, 1, '足利義政が建てたのは慈照寺（銀閣）です。ちなみに鹿苑寺は足利義満が建てた金閣のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '1467年に始まり、室町幕府の権威が衰えるきっかけとなった争乱は何か。', '["応仁の乱","承久の乱","元弘の乱","観応の擾乱"]', 0, 1, '将軍の跡継ぎ問題や有力守護の対立から始まった応仁の乱により、京都は荒廃し、全国的な戦国時代へと突入しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代の国風文化において、貴族の女性たちが日記や物語に用いた文字は何か。', '["かな文字","漢字","カタカナ","梵字"]', 0, 1, '平安時代には、漢字を簡略化した「かな文字」が生まれ、和歌や物語など、日本独自の文化が発展しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府の最高権力者である執権の地位を世襲した家柄はどれか。', '["北条氏","源氏","平氏","足利氏"]', 0, 1, '鎌倉幕府では、源頼朝の死後、妻の北条政子の実家である北条氏が執権として実権を握りました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉時代の仏教において、念仏を唱えることを重視した宗派はどれか。', '["浄土宗","禅宗","日蓮宗","真言宗"]', 0, 1, '法然が始めた浄土宗は、「南無阿弥陀仏」と念仏を唱えるだけで救われると説きました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代に、武士や民衆の間で流行した、禅の精神を取り入れた文化を何というか。', '["東山文化","北山文化","国風文化","天平文化"]', 0, 1, '東山文化は、足利義政のもとで発展した、簡素で落ち着いた趣のある文化です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉時代の武士の生活で、土地を耕し、戦いの準備をする生活を何と呼ぶか。', '["弓馬の道","武士道","奉公","御恩"]', 0, 1, '武士は「弓馬の道」を重んじ、平時は農業に従事し、有事には戦うという生活を送っていました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代、藤原氏が権力を握るために行ったことはどれか。', '["娘を天皇の妃にする","武士を雇う","新しい法律を作る","土地をすべて没収する"]', 0, 1, '藤原氏は自分の娘を天皇の妃にし、生まれた子が天皇になると、その祖父として政治の実権を握りました。', NULL);
