INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代の貴族が好んだ、優雅な遊びはどれか。', '["蹴鞠","野球","相撲","チェス"]', 0, 1, '蹴鞠（けまり）は平安時代の貴族の間で流行した、ボールを落とさないように蹴り合う遊びです。', NULL);
