INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、幕府の権威が低下する中で、実力で支配する風潮を何というか。', '["下剋上","院政","摂関政治","武家政治"]', 0, 1, '下の者が上の者を倒して実権を握る「下剋上」の風潮が、戦国時代へとつながりました。', NULL);
