INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、水墨画を大成させた人物は誰か。', '["雪舟","狩野永徳","俵屋宗達","尾形光琳"]', 0, 1, '雪舟は明に渡って水墨画を学び、日本独自の力強い水墨画を確立しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代、藤原道長が建立した寺院は何か。', '["法成寺","平等院","金閣寺","東大寺"]', 0, 1, '藤原道長は、自身の権力を誇示するために壮大な法成寺を建立しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉時代、一遍が広めた宗派はどれか。', '["時宗","浄土宗","浄土真宗","日蓮宗"]', 0, 1, '一遍は踊り念仏を広めた時宗の開祖です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、京都で始まった、茶を飲む遊びを何というか。', '["闘茶","茶の湯","茶道","点前"]', 0, 1, '闘茶は、数種類の茶を飲み比べて産地を当てる遊びで、当時の武士や民衆に流行しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代、貴族の服装で、女性が重ね着をしたものを何というか。', '["十二単","狩衣","直衣","束帯"]', 0, 1, '十二単は、平安時代の貴族女性の正装で、多くの衣を重ねて着る豪華なものです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉幕府の滅亡後、足利尊氏が京都に開いた幕府は何か。', '["室町幕府","鎌倉幕府","江戸幕府","建武幕府"]', 0, 1, '足利尊氏は、後醍醐天皇と対立し、京都に室町幕府を開きました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、守護が領国を支配するようになった大名を何というか。', '["守護大名","戦国大名","国人","地侍"]', 0, 1, '室町時代、守護が領地を支配し、力をつけたものを守護大名と呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代、かな文字で書かれた日本最初の勅撰和歌集はどれか。', '["古今和歌集","万葉集","新古今和歌集","拾遺和歌集"]', 0, 1, '紀貫之らが編纂した『古今和歌集』は、かな文字で書かれた最初の勅撰和歌集です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉時代、北条氏が権力を握るために利用した役職は何か。', '["執権","将軍","守護","地頭"]', 0, 1, '執権は、将軍を補佐する役職でしたが、北条氏はこれを世襲して実権を握りました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、東山文化の代表的な建築物はどれか。', '["銀閣","金閣","平等院","東大寺"]', 0, 1, '銀閣（慈照寺）は、足利義政が建てた東山文化の代表的な建築物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '平安時代、地方で武士が成長した理由として正しいものはどれか。', '["国司の支配に抵抗するため","天皇の命令で戦うため","外国から守るため","農業を効率化するため"]', 0, 1, '地方の有力者が、国司の圧政から自分の土地や財産を守るために武装し、武士へと成長しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '鎌倉時代、御家人の裁判を扱う機関は何か。', '["問注所","政所","侍所","評定衆"]', 0, 1, '問注所は、鎌倉幕府において、御家人の土地争いなどの裁判を扱う役所です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'social_studies', '室町時代、日明貿易で日本が輸入した銅銭を何というか。', '["明銭","渡来銭","和同開珎","宋銭"]', 0, 1, '日明貿易によって大量の明銭が輸入され、日本国内での貨幣経済が発達しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「彼は熱心に勉強する。」の「熱心」の品詞は何か。', '["名詞","動詞","形容詞","形容動詞"]', 3, 1, '「熱心だ」と言い切ることができ、活用があるため形容動詞です。名詞と混同しやすいので注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「美しい花が咲いた。」の「美しい」の品詞は何か。', '["形容詞","形容動詞","動詞","副詞"]', 0, 1, '「美しい」は言い切りが「い」で終わるため形容詞です。状態を表す言葉で、活用があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「空が青い。」の「青い」の品詞は何か。', '["名詞","動詞","形容詞","形容動詞"]', 2, 1, '「青い」は言い切りが「い」で終わる形容詞です。「青だ」とは言わないので形容動詞ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「本を読む。」の「読む」の品詞は何か。', '["名詞","動詞","形容詞","形容動詞"]', 1, 1, '「読む」は動作を表す言葉で、言い切りが「う」段の音で終わるため動詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「机の上にある。」の「机」の品詞は何か。', '["名詞","動詞","形容詞","形容動詞"]', 0, 1, '「机」は物事を表す名前なので名詞です。活用がなく、主語や目的語になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「私は学校へ行く。」の「へ」の品詞は何か。', '["名詞","動詞","助詞","助動詞"]', 2, 1, '「へ」は付属語であり、前の名詞に付いて場所や方向を示す助詞です。単独では文節を作れません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「とても静かだ。」の「とても」の品詞は何か。', '["名詞","動詞","副詞","接続詞"]', 2, 2, '「とても」は、あとに続く言葉を修飾する副詞です。活用がなく、文の成分としては修飾語になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「しかし、雨が降った。」の「しかし」の品詞は何か。', '["副詞","接続詞","感動詞","名詞"]', 1, 1, '「しかし」は前後の文をつなぐ役割を持つ接続詞です。文の頭に置かれ、独立しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「ああ、美しい。」の「ああ」の品詞は何か。', '["副詞","接続詞","感動詞","名詞"]', 2, 1, '「ああ」は感動や呼びかけを表す独立語（感動詞）です。文の成分には含まれません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「美しい花が咲く。」の主語はどれか。', '["美しい","花が","咲く","美しい花が"]', 1, 2, '主語は「何が（誰が）」にあたる部分です。「花が」が主語で、「美しい」はそれを修飾しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「彼は本を読む。」の述語はどれか。', '["彼は","本を","読む","彼は本を"]', 2, 1, '述語は「どうする（どんなだ）」にあたる部分です。この文では動作を表す「読む」が述語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「赤いリンゴを食べる。」の修飾語はどれか。', '["赤い","リンゴを","食べる","赤いリンゴを"]', 0, 2, '「赤い」は「リンゴを」を詳しく説明している修飾語です。修飾語は被修飾語の直前に置かれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「誠実な人」', '["せいじつ","じょうじつ","せいしつ","せいじ"]', 0, 1, '「誠実」は「せいじつ」と読みます。漢字の読み書きは基本事項なので正確に覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「懸命に走る」', '["けんめい","けんめ","けんみょう","けいめい"]', 0, 1, '「懸命」は「けんめい」と読みます。一生懸命の「懸」の字は間違えやすいので注意してください。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「厳格な先生」', '["げんかく","げんこく","がんかく","げんがく"]', 0, 2, '「厳格」は「げんかく」と読みます。厳という字の書き順や構成にも注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しんけんな眼差し」', '["真剣","新剣","心剣","親剣"]', 0, 1, '「しんけん」は「真剣」と書きます。真実の真、剣道の剣です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「きぼうを持つ」', '["希望","希房","喜望","帰望"]', 0, 1, '「きぼう」は「希望」と書きます。望むという字の構成を確認しておきましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しょうらいの夢」', '["将来","性来","精来","正来"]', 0, 1, '「しょうらい」は「将来」と書きます。将という字の左側は「寸」ではないので注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「自立語」はどれか。', '["は","が","美しい","を"]', 2, 2, '自立語はそれだけで文節を作れる言葉です。「美しい」は形容詞で自立語ですが、助詞は付属語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「付属語」はどれか。', '["走る","赤い","机","だ"]', 3, 2, '「だ」は助動詞で、単独では文節を作れない付属語です。他の言葉に付いて意味を添えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「名詞」はどれか。', '["歩く","速い","学校","静かだ"]', 2, 1, '「学校」は物事の名前を表す名詞です。活用がなく、主語や目的語になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「動詞」はどれか。', '["美しい","きれいだ","食べる","本"]', 2, 1, '「食べる」は動作を表す動詞です。言い切りが「る」で終わる動詞の活用を確認しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「形容詞」はどれか。', '["高い","高いだ","高くする","高まる"]', 0, 2, '「高い」は言い切りが「い」で終わる形容詞です。形容詞は「〜い」で終わるのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「形容動詞」はどれか。', '["赤い","青い","静かだ","美しい"]', 2, 2, '「静かだ」は言い切りが「だ」で終わる形容動詞です。活用があり、状態を表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '文節の区切り方として正しいものはどれか。「赤い花が咲いた。」', '["赤い／花が／咲いた。","赤い花／が咲いた。","赤い花が／咲いた。","赤い／花／が／咲いた。"]', 0, 2, '文節は「ネ」を入れて不自然にならないところで区切ります。「赤いネ、花がネ、咲いたネ。」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「彼はとても親切だ。」の修飾語はどれか。', '["彼は","とても","親切だ","彼はとても"]', 1, 2, '「とても」は「親切だ」を詳しく説明している修飾語（副詞）です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「柔軟な対応」', '["じゅうなん","じゅうだん","じゅなん","じゅうねん"]', 0, 2, '「柔軟」は「じゅうなん」と読みます。柔らかいという字の読み方に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しんせつな人」', '["親切","心切","新切","真切"]', 0, 1, '「しんせつ」は「親切」と書きます。親という字と切という字の組み合わせです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「簡潔に述べる」', '["かんけつ","かんせつ","けんけつ","かんきつ"]', 0, 2, '「簡潔」は「かんけつ」と読みます。簡という字の読み方に気をつけましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「きびしい訓練」', '["厳しい","強しい","強びしい","厳びしい"]', 0, 2, '「きびしい」は「厳しい」と書きます。厳という字の書き方に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「彼は走る。」の主語はどれか。', '["彼は","走る","彼","は"]', 0, 1, '主語は「彼は」のように、助詞「は」や「が」を伴う文節全体を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「美しい花が咲いた。」の修飾語はどれか。', '["美しい","花が","咲いた","美しい花が"]', 0, 2, '「美しい」は「花が」を修飾する言葉です。主語を修飾している修飾語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「接続詞」はどれか。', '["しかし","とても","美しい","走る"]', 0, 1, '「しかし」は文と文をつなぐ接続詞です。文の頭に置かれ、独立しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「感動詞」はどれか。', '["はい","そして","とても","美しい"]', 0, 1, '「はい」は返事や応答を表す感動詞です。独立語として扱われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「動詞」の活用形として正しいものはどれか。「読む」の未然形は？', '["読ま","読み","読む","読め"]', 0, 3, '「読む」の未然形は「読ま（ない）」です。活用形は動詞の分類において非常に重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「形容詞」の活用形として正しいものはどれか。「高い」の連用形は？', '["高く","高い","高ければ","高かろう"]', 0, 3, '「高い」の連用形は「高く（なる）」です。あとに続く言葉によって形が変わります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「じょうたつする」', '["上達","情達","常達","成達"]', 0, 2, '「上達」は技術などが向上することです。漢字の構成を意識しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「謙虚な態度」', '["けんきょ","けんご","けんき","きょけん"]', 0, 2, '「謙虚」は「けんきょ」と読みます。謙という字は難しいですがよく出題されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「かんしゃの気持ち」', '["感謝","感写","観謝","甘謝"]', 0, 1, '「感謝」は「かんしゃ」と書きます。感謝の意を表す際に使われる漢字です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「副詞」はどれか。', '["ゆっくり","美しい","走る","机"]', 0, 2, '「ゆっくり」は状態を詳しく説明する副詞です。活用がなく、修飾語になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「助詞」はどれか。', '["を","走る","美しい","机"]', 0, 1, '「を」は名詞に付いて目的語であることを示す助詞です。付属語なので単独では使えません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「文節」の数はいくつあるか。「赤い花が咲いた。」', '["2","3","4","5"]', 1, 2, '「赤い／花が／咲いた。」の3つです。文節は「ネ」を入れて区切ると分かりやすいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しゅうちゅうする」', '["集中","集注","収中","周中"]', 0, 1, '「集中」は「しゅうちゅう」と書きます。一つのことに向かうという意味です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「正確な計算」', '["せいかく","せいこく","せいか","せいかく（正格）"]', 0, 1, '「正確」は「せいかく」と読みます。間違いがないという意味です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「主語」はどれか。「昨日、公園で遊んだ。」', '["昨日","公園で","遊んだ","省略されている"]', 3, 3, 'この文には主語が書かれていません。文脈から「私は」などが補えますが、文上は省略されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「ふくざつな問題」', '["複雑","複雑","副雑","復雑"]', 0, 2, '「複雑」は「ふくざつ」と書きます。混み合っているという意味です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「懸命な努力」', '["けんめい","けんみょう","けんめ","けいめい"]', 0, 1, '「懸命」は「けんめい」と読みます。一生懸命の「懸」です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「せいせきが上がる」', '["成績","正績","成積","正積"]', 0, 1, '「成績」は「せいせき」と書きます。成果の成と、業績の績です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「誠実な態度」', '["せいじつ","せいしつ","じょうじつ","じょうしつ"]', 0, 1, '「誠実」は「せいじつ」と読みます。誠という字は「まこと」とも読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「きぼうを抱く」', '["希望","喜望","希房","帰望"]', 0, 1, '「希望」は「きぼう」と書きます。望という字の書き方に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「文の成分」で、主語を詳しく説明するものはどれか。', '["修飾語","述語","接続語","独立語"]', 0, 2, '修飾語は、主語や述語を詳しく説明する役割を持っています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「厳粛な式典」', '["げんしゅく","げんじゅく","がんしゅく","げんしゅ"]', 0, 2, '「厳粛」は「げんしゅく」と読みます。厳という字の読み方に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しんけんな表情」', '["真剣","新剣","心剣","親剣"]', 0, 1, '「真剣」は「しんけん」と書きます。真実の真、剣道の剣です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「形容動詞」の活用形として正しいものはどれか。「静かだ」の連体形は？', '["静かな","静かに","静かなる","静かだ"]', 0, 3, '「静かだ」の連体形は「静かな（人）」のように「な」になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の読み」として正しいものはどれか。「柔軟性がある」', '["じゅうなんせい","じゅなんせい","じゅうだんせい","じゅうねんせい"]', 0, 2, '「柔軟性」は「じゅうなんせい」と読みます。柔軟という字の読み方を確認しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'japanese', '「漢字の書き」として正しいものはどれか。「しょうらいの目標」', '["将来","性来","精来","正来"]', 0, 1, '「将来」は「しょうらい」と書きます。将という字の構成に注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「まるで雪のような白い肌」という表現で使われている比喩の種類はどれか。', '["直喩","隠喩","擬人法","倒置法"]', 0, 1, '「まるで」「〜のようだ」などの言葉を使って例える表現を直喩といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「人生は旅だ」という表現で使われている比喩の種類はどれか。', '["直喩","隠喩","擬人法","反復法"]', 1, 1, '「〜だ」と言い切る形で、例えの言葉を使わずに例える表現を隠喩（メタファー）といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「太陽が笑っている」という表現で使われている技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 2, 1, '人間ではないものを、人間のように表現する技法を擬人法といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「美しい夕日だ。あの燃えるような。」という表現で使われている技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 0, 2, '本来の語順を入れ替えて強調する技法を倒置法といいます。文末が名詞で終わる体言止めとは異なります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「静かな夜。星が輝く夜。」という表現で使われている技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 1, 1, '文の終わりを名詞で止めることで、余韻を残したり強調したりする技法を体言止めといいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「ゆく河の流れは絶えずして、しかももとの水にあらず」という表現で使われている技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 3, 2, '同じ言葉や似た表現を繰り返すことで、リズムや強調を生む技法を反復法といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '説明文において、筆者の最も伝えたい中心的な内容を何というか。', '["要旨","段落構成","接続詞","比喩"]', 0, 1, '説明文全体を通して筆者が最も主張したい中心的な考えを要旨といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '説明文の構成として一般的な「序論・本論・結論」のうち、導入部分にあたるのはどれか。', '["序論","本論","結論","序文"]', 0, 1, '説明文は、話題を提示する「序論」、具体的に説明する「本論」、まとめの「結論」という構成が一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「先生、明日学校に行きます。」を尊敬語に直すとどうなるか。', '["先生、明日学校にいらっしゃいます。","先生、明日学校に参ります。","先生、明日学校においでになります。","先生、明日学校に行かれます。"]', 2, 2, '相手の動作を高める尊敬語です。「行く」の尊敬語は「いらっしゃる」「おいでになる」です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「私が先生に手紙を渡す」を謙譲語に直すとどうなるか。', '["私が先生に手紙を差し上げる。","私が先生に手紙をくださる。","私が先生に手紙を渡される。","私が先生に手紙を拝見する。"]', 0, 2, '自分の動作をへりくだる謙譲語です。「渡す」の謙譲語は「差し上げる」です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「顔から火が出る」という慣用句の意味はどれか。', '["非常に恥ずかしい思いをする。","怒りで真っ赤になる。","熱がある。","驚いて顔が赤くなる。"]', 0, 1, '恥ずかしくて顔が赤くなる様子を「顔から火が出る」といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「猫の手も借りたい」という慣用句の意味はどれか。', '["猫に手伝ってもらう。","非常に忙しい。","怠けている。","猫が可愛い。"]', 1, 1, '非常に忙しく、誰の手でも借りたいほどであるという意味です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「石の上にも三年」ということわざの意味はどれか。', '["石の上に座る。","忍耐強く努力すれば報われる。","三年待てば石が動く。","石は硬い。"]', 1, 1, '冷たい石の上でも三年座り続ければ温まることから、辛抱強く努力すれば必ず成功するという意味です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「月とすっぽん」ということわざの意味はどれか。', '["どちらも丸い。","比較にならないほど差がある。","どちらも夜に出る。","どちらも美味しい。"]', 1, 1, '形が似ているだけで、質や程度が全く違うことを表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「風が歌う」という表現に含まれる技法はどれか。', '["直喩","隠喩","擬人法","倒置法"]', 2, 1, '風が歌うという人間的な動作を当てはめているため、擬人法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「彼はまるで鬼のような形相だった」の比喩の種類はどれか。', '["直喩","隠喩","擬人法","反復法"]', 0, 1, '「まるで〜のようだ」という形式なので直喩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「時間は金なり」という表現の比喩の種類はどれか。', '["直喩","隠喩","擬人法","倒置法"]', 1, 1, '「〜だ」と言い切る形なので隠喩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「美しい花。咲き誇る花。」という表現はどの技法か。', '["体言止め","倒置法","擬人法","反復法"]', 0, 1, '名詞で文を終えているため体言止めです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「悲しい。本当に悲しい。」という表現に含まれる技法はどれか。', '["反復法","倒置法","擬人法","体言止め"]', 0, 1, '同じ言葉を繰り返すことで強調しているため反復法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「おいしいね、このケーキ。」という表現に含まれる技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 0, 2, '本来なら「このケーキはおいしいね」となる語順を入れ替えているため倒置法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '説明文における「接続詞」の役割として最も適切なものはどれか。', '["文と文の論理的な関係を示す。","筆者の感情を表す。","比喩を説明する。","段落を分ける。"]', 0, 1, '「しかし」「つまり」などの接続詞は、文の前後関係を明確にする役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「先生が本を読まれる」の敬語の種類はどれか。', '["尊敬語","謙譲語","丁寧語","美化語"]', 0, 2, '相手の動作を高める尊敬語です。「〜れる」は尊敬の助動詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「私が先生にお聞きする」の敬語の種類はどれか。', '["尊敬語","謙譲語","丁寧語","美化語"]', 1, 2, '自分の動作をへりくだる謙譲語です。「聞く」の謙譲語は「伺う」「お聞きする」です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「お茶を飲む」を丁寧語にするとどうなるか。', '["お茶を召し上がる。","お茶をいただきます。","お茶を飲みます。","お茶を飲まれる。"]', 2, 1, '「〜ます」をつけることで丁寧な表現になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「耳が痛い」という慣用句の意味はどれか。', '["耳が怪我している。","欠点を指摘されてつらい。","大きな音がする。","耳が聞こえない。"]', 1, 1, '自分の弱点や過ちを指摘されて、聞くのがつらい状態をいいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「棚からぼたもち」ということわざの意味はどれか。', '["棚を掃除する。","努力せずに幸運を得る。","ぼたもちを落とす。","棚は高い。"]', 1, 1, '思いがけない幸運が舞い込むことをいいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「雲がダンスをする」という表現に含まれる技法はどれか。', '["擬人法","直喩","隠喩","反復法"]', 0, 1, '雲がダンスするという人間的な動作をしているため擬人法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「君は太陽だ」という表現の比喩の種類はどれか。', '["直喩","隠喩","擬人法","倒置法"]', 1, 1, '「〜だ」と言い切る形なので隠喩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「まるで夢のような時間」という表現の比喩の種類はどれか。', '["直喩","隠喩","擬人法","反復法"]', 0, 1, '「まるで」「〜のような」があるため直喩です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「燃えるような夕日。赤い夕日。」という表現に含まれる技法はどれか。', '["体言止め","倒置法","擬人法","反復法"]', 0, 1, '名詞で文を終えているため体言止めです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「走れ、早く走れ。」という表現に含まれる技法はどれか。', '["反復法","倒置法","擬人法","体言止め"]', 0, 1, '同じ言葉を繰り返しているため反復法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「美しいね、あの花は。」という表現に含まれる技法はどれか。', '["倒置法","体言止め","擬人法","反復法"]', 0, 2, '語順を入れ替えて強調しているため倒置法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '説明文の「本論」の主な役割はどれか。', '["話題を提示する。","結論を述べる。","具体例や根拠を挙げて説明する。","感想を書く。"]', 2, 1, '本論では、序論で提示した話題について、具体例や根拠を挙げて詳しく説明します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「先生がおっしゃる」の敬語の種類はどれか。', '["尊敬語","謙譲語","丁寧語","美化語"]', 0, 2, '「言う」の尊敬語で、相手の動作を高めています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「私が伺います」の敬語の種類はどれか。', '["尊敬語","謙譲語","丁寧語","美化語"]', 1, 2, '「行く・聞く」の謙譲語で、自分の動作をへりくだっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「お弁当を食べる」を丁寧語にするとどうなるか。', '["お弁当を召し上がる。","お弁当をいただきます。","お弁当を食べます。","お弁当を食べられる。"]', 2, 1, '「〜ます」をつけることで丁寧な表現になります。', NULL);
