INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'japanese', '「手紙を書く」を丁寧語にするとどうなるか。', '["手紙を認める。","手紙を書きなさる。","手紙を書きます。","手紙を読まれる。"]', 2, 1, '「〜ます」をつけることで丁寧な表現になります。', NULL);
