INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「森林」という熟語の構成として正しいものはどれか。', '["同じ意味の漢字を重ねる","反対の意味の漢字を重ねる","上の字が下の字を修飾する","動作の対象を表す"]', 0, 1, '「森」も「林」も木が集まっている場所を意味し、同じ意味の漢字を重ねて強調する構成です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「上下」という熟語の構成として正しいものはどれか。', '["同じ意味の漢字を重ねる","反対の意味の漢字を重ねる","上の字が下の字を修飾する","動作の対象を表す"]', 1, 1, '「上」と「下」は反対の意味を持つ漢字を組み合わせた熟語です。', NULL);
