INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「急行」という熟語の構成として正しいものはどれか。', '["同じ意味の漢字を重ねる","上の字が下の字を修飾する","主語と述語の関係","動作の対象を表す"]', 1, 2, '「急に（速く）行く」というように、上の字が下の字を修飾（詳しく説明）している構成です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「山川」という熟語の構成として正しいものはどれか。', '["同じ意味の漢字を重ねる","反対の意味の漢字を重ねる","並列の関係","動作の対象を表す"]', 2, 2, '山と川という、対等な関係の言葉を並べている熟語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「類義語」の組み合わせとして正しいものはどれか。', '["開始ー終了","希望ー絶望","容易ー簡単","正直ー嘘"]', 2, 1, '「容易」と「簡単」は、どちらも「たやすいこと」を意味する類義語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「対義語」の組み合わせとして正しいものはどれか。', '["平和ー平穏","拡大ー縮小","正確ー精密","努力ー精進"]', 1, 1, '「拡大」と「縮小」は、意味が反対の関係にある対義語です。', NULL);
