INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「漢語」はどれか。', '["空","海","読書","パン"]', 2, 1, '「読書」は中国から伝わった漢字を組み合わせてできた漢語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「外来語」はどれか。', '["春","本","ガラス","学校"]', 2, 1, '「ガラス」はオランダ語由来の言葉で、外来語に分類されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '品詞分類において「自立語」はどれか。', '["動詞","助詞","助動詞","接続助詞"]', 0, 2, '動詞は単独で文節を作れる自立語です。助詞や助動詞は付属語です。', NULL);
