INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「とても」の品詞はどれか。', '["副詞","連体詞","接続詞","感動詞"]', 0, 2, '「とても」は用言を修飾する副詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「大きな」の品詞はどれか。', '["副詞","連体詞","接続詞","感動詞"]', 1, 2, '「大きな」は体言（名詞）を修飾する連体詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「しかし」の品詞はどれか。', '["副詞","連体詞","接続詞","感動詞"]', 2, 1, '「しかし」は文と文をつなぐ接続詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「ああ」の品詞はどれか。', '["副詞","連体詞","接続詞","感動詞"]', 3, 1, '「ああ」は感動や呼びかけを表す感動詞です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「食べる」の活用形として「未然形」はどれか。', '["食べない","食べます","食べる","食べれば"]', 0, 2, '「食べない」の「食べ」が未然形です。後ろに「ない」が続く形です。', NULL);
