INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'japanese', '「美しい」の連用形はどれか。', '["美しく","美しい","美しければ","美しかろう"]', 0, 2, '形容詞の連用形は「～く」となります。「美しくなる」のように使います。', NULL);
