INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '遠近法における「大きさによる遠近法」の基本は何か。', '["遠いものは小さく描く","遠いものは大きく描く","遠いものは明るく描く","遠いものは太い線で描く"]', 0, 1, '同じ大きさの物体であれば、遠くにあるほど小さく見えるという視覚的な法則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、物体に落ちる影の形を決定するものは何か。', '["光源の位置","物体の色","紙の大きさ","アイレベル"]', 0, 2, '影の形や長さは、光源（光の源）の位置によって変化します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '二点透視図法で、消失点がアイレベルから外れることはあるか。', '["ない","ある","頻繁にある","描く人の自由である"]', 0, 3, '二点透視図法において、消失点は必ずアイレベル上に存在しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '空気遠近法において、手前のものはどう見えるか。', '["色が鮮やかで明暗差が大きい","色がぼやけて見える","全体が青白く見える","小さく見える"]', 0, 2, '手前のものは空気の影響をあまり受けないため、色やコントラストがはっきり見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、消しゴムを「描く道具」として使うとはどういうことか。', '["ハイライトを作るために使う","間違えた線を消すために使う","紙を白くするために使う","鉛筆を削るために使う"]', 0, 2, '消しゴムで塗った部分を一部消すことで、光が当たっているハイライト部分を表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '一点透視図法で、水平な線（地平線）はどのように描くか。', '["水平に描く","消失点に向かって傾ける","垂直に描く","曲線で描く"]', 0, 2, '一点透視図法では、水平線は常に地面と平行になるよう水平に描きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、反射光を描き忘れるとどうなるか。', '["立体感が弱くなる","絵が明るくなる","影が消える","線が太くなる"]', 0, 3, '反射光を描くことで、物体の丸みや質感が表現されるため、これがないと平面的に見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '二点透視図法で、物体がアイレベル上にあるとどう見えるか。', '["上面も底面も見えない","上面だけが見える","底面だけが見える","上面も底面も見える"]', 0, 3, 'アイレベルは目の高さなので、その位置にある物体の上面や底面は見えません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '遠近法において、線が収束する原理は何に基づいているか。', '["視覚的な遠近感","数学的な計算","色の三原色","影の強さ"]', 0, 2, '透視図法は、人間の目が遠くのものを小さく、平行な線が一点に集まるように感じる視覚特性に基づいています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、影のグラデーションを滑らかにするコツは何か。', '["筆圧を少しずつ変える","線を重ねて塗る","指で強くこする","消しゴムでぼかす"]', 0, 2, '筆圧を調整しながら塗ることで、明暗の移り変わり（グラデーション）を自然に表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '一点透視図法で、消失点がアイレベルより高い位置にあることはあるか。', '["ない","ある","頻繁にある","描く人の自由である"]', 0, 3, '消失点は必ずアイレベル（目の高さ）上に配置されるため、アイレベルより高い位置にはありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '空気遠近法で、遠くの山の色はどうなるか。', '["彩度が下がり青っぽくなる","彩度が上がり赤っぽくなる","真っ黒になる","真っ白になる"]', 0, 2, '遠くの景色は空気の層を通るため、彩度が下がり、青みがかった色に見えるのが一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、最も暗い「陰」の部分を描くために適した鉛筆はどれか。', '["濃いB系","薄いH系","硬いH系","HB"]', 0, 1, '濃いB系の鉛筆は芯が柔らかく色が乗りやすいため、暗い部分を描くのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '二点透視図法で、立方体の角を向けて描く際、左右の消失点はどのように配置するか。', '["アイレベル上に離して配置","アイレベル上に重ねて配置","画面の上下に配置","画面の外に配置しない"]', 0, 3, '二点透視図法では、左右の消失点をアイレベル上に離して配置することで、奥行きを表現します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、構図を決めるときに大切なことは何か。', '["画面全体のバランス","鉛筆の削り方","紙の質","消しゴムの性能"]', 0, 1, '構図は絵の土台です。対象をどこに配置するかで、画面全体の安定感や印象が決まります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '一点透視図法で、消失点に向かう線は、画面上でどう見えるか。', '["斜めに見える","垂直に見える","水平に見える","平行に見える"]', 0, 2, '奥行きを示す線は、消失点に向かって斜めに収束していくように描かれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '重なり法で、奥にあるものはどう描くのが適切か。', '["手前のものに隠れるように描く","手前のものより大きく描く","手前のものより太い線で描く","手前のものより明るく描く"]', 0, 1, '手前の物体が奥の物体を遮るように描くことで、自然な前後関係が生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、影の形は光源のどこに影響されるか。', '["位置と高さ","物体の重さ","物体の硬さ","紙の大きさ"]', 0, 2, '光源の位置や高さによって、影の長さや伸びる方向が変わります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '二点透視図法で、垂直の線はどのように描くか。', '["垂直に描く","消失点に向かって傾ける","アイレベルに合わせる","水平に描く"]', 0, 2, '二点透視図法でも、高さ方向の線は垂直のまま描くのが正しいルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '空気遠近法で、遠くのものがぼやけて見える原因は何か。', '["空気中の微粒子","光の反射","鉛筆の芯","アイレベル"]', 0, 2, '空気中の塵や水蒸気が光を散乱させるため、遠くのものほどぼやけて見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、中間調（ミドルトーン）とはどのような部分か。', '["光と影の間の明るさ","最も明るい部分","最も暗い部分","影の輪郭"]', 0, 2, '中間調はハイライトと陰の間に位置する、物体の固有の色が最もよく見える部分です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '一点透視図法で、アイレベルより上にある立方体は、何が見えるか。', '["底面","上面","側面だけ","何も見えない"]', 0, 3, 'アイレベルより高い位置にある物体は、下から見上げる形になるため、底面が見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', 'デッサンで、鉛筆の線が目立つときはどうすればよいか。', '["軽くこすってぼかす","消しゴムで消す","筆圧を強くする","線を太くする"]', 0, 2, '線をこすって馴染ませることで、面としての質感が生まれ、よりリアルな立体感が出ます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '遠近法を使う目的は何か。', '["画面に奥行きを出すため","絵を難しくするため","色を増やすため","線を減らすため"]', 0, 1, '遠近法は、平面の紙の上に、現実のような奥行きや空間の広がりを表現するための技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'art', '二点透視図法で、消失点がアイレベルからずれることはあるか。', '["ない","ある","頻繁にある","描く人の自由である"]', 0, 3, '二点透視図法において、消失点は必ずアイレベル上に配置されるという厳格なルールがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '透明水彩絵の具の特徴として、最も適切なものはどれか。', '["水で薄めて透明感を生かして描く","乾くと耐水性になり重ね塗りができる","不透明で下の色を隠すことができる","油を混ぜて光沢を出す"]', 0, 1, '透明水彩は水の量を調整して透明感を生かすのが特徴です。不透明な性質を持つのは不透明水彩やアクリル絵の具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具の最大の特徴はどれか。', '["一度乾くと水に溶けなくなる","油絵の具のように乾燥に時間がかかる","水に溶けず、常に油で薄める必要がある","透明感しか表現できない"]', 0, 1, 'アクリル絵の具は乾燥が早く、一度乾くと耐水性になるため、重ね塗りが容易で多様な素材に描ける利点があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '絵の具を網にこすりつけ、細かい飛沫を飛ばす技法を何というか。', '["スパッタリング","デカルコマニー","ドリッピング","コラージュ"]', 0, 1, 'スパッタリングは、ブラシに絵の具をつけて網でこすり、霧状の飛沫を画面に散らす技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '紙に絵の具を塗り、二つ折りにしたり別の紙を押し当てたりして模様を作る技法はどれか。', '["デカルコマニー","スパッタリング","ドリッピング","コラージュ"]', 0, 1, 'デカルコマニーは、転写技法とも呼ばれ、偶然できる形や左右対称の模様を楽しむ技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '絵の具を垂らしたり、筆から滴らせたりして描く技法を何というか。', '["ドリッピング","スパッタリング","デカルコマニー","コラージュ"]', 0, 1, 'ドリッピングは「滴る」という意味で、絵の具をポタポタと垂らして偶然の線や形を作る技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '写真、新聞、布などを切り貼りして新しい作品を作る技法を何というか。', '["コラージュ","スパッタリング","デカルコマニー","ドリッピング"]', 0, 1, 'コラージュはフランス語の「糊付け」が語源で、異なる素材を組み合わせて新しい表現を生み出す技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムの目的として、最も適切なものはどれか。', '["言葉を使わずに情報を直感的に伝える","絵画的な美しさを追求する","詳細な説明文を補足する","特定の個人の感情を表現する"]', 0, 1, 'ピクトグラムは、言語の壁を超えて誰にでも一目で意味が伝わるようにデザインされた視覚記号です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムをデザインする際に最も重要なことは何か。', '["シンプルで分かりやすいこと","複雑で細密に描くこと","多くの色を使って華やかにすること","背景を細かく描き込むこと"]', 0, 1, 'ピクトグラムは遠くから見ても瞬時に理解される必要があるため、要素を削ぎ落としたシンプルな形が求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングを行う際、網とブラシ以外に準備すると良いものはどれか。', '["型紙（ステンシル）","油絵用溶剤","木工用ボンド","キャンバスの地塗り剤"]', 0, 2, '型紙を置いてからスパッタリングをすると、型紙の部分だけが白く残り、シルエットをきれいに表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、より面白い模様を作るためのコツはどれか。', '["絵の具を乾かないうちに素早く転写する","絵の具を完全に乾燥させてから転写する","絵の具をできるだけ薄く塗る","筆の跡をしっかり残す"]', 0, 2, 'デカルコマニーは絵の具が湿っている状態で紙を合わせることで、偶然の混ざり合いや形が生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングの技法で有名な画家は誰か。', '["ジャクソン・ポロック","レオナルド・ダ・ヴィンチ","ゴッホ","ピカソ"]', 0, 3, 'ジャクソン・ポロックは、キャンバスを床に広げて絵の具を垂らす「アクション・ペインティング」で知られています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュ作品を作る際、最も注意すべき点はどれか。', '["素材の組み合わせと構成のバランス","絵の具を厚く塗ること","必ず絵を描き足すこと","一つの素材しか使わないこと"]', 0, 2, 'コラージュは素材の質感や色、形をどう配置するかが重要で、全体のバランスを考えることが作品の質を高めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムのデザインにおいて、避けるべきことはどれか。', '["複雑で解釈が分かれる表現","単純な図形の組み合わせ","明確なコントラスト","普遍的なシンボルの使用"]', 0, 2, 'ピクトグラムは誰が見ても同じ意味に受け取れる必要があり、複雑で曖昧な表現は誤解を招くため避けるべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具の「混色」について、正しい説明はどれか。', '["色を混ぜすぎると濁りやすい","混ぜれば混ぜるほど鮮やかになる","必ず白を混ぜないと色が作れない","黒を混ぜるのが最も美しい"]', 0, 2, '水彩絵の具は多くの色を混ぜると色がくすみ、濁ってしまいます。鮮やかさを保つには混色を最小限にするのがコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具で「盛り上げ」表現をするために適した道具はどれか。', '["ペインティングナイフ","柔らかい面相筆","スポンジ","ストロー"]', 0, 2, 'ペインティングナイフを使うと、絵の具を厚く塗り重ねたり、立体的な質感を表現したりすることが容易になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、飛沫の大きさを変える方法として正しいのはどれか。', '["ブラシの硬さや網の粗さを変える","絵の具の量を減らす","紙を濡らす","ドライヤーで乾かす"]', 0, 3, 'ブラシが硬いと飛沫が大きく、柔らかいと細かくなります。網の粗さによっても飛沫の粒の大きさが変わります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーの技法で、紙を広げた時にできる模様の特徴はどれか。', '["偶然にできる左右対称に近い形","緻密に計算された幾何学模様","筆で描いたような正確な線","写真のようにリアルな描写"]', 0, 2, '二つ折りにした紙を広げることで、絵の具が押しつぶされ、偶然による左右対称の面白い形が生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングの技法で、絵の具の飛び散り方をコントロールする方法はどれか。', '["腕の振り方や高さ、絵の具の粘度を変える","筆を洗う回数を増やす","画用紙を立てて描く","絵の具を水で完全に薄める"]', 0, 3, '腕の勢いや高さ、絵の具の濃さを調整することで、線の太さや飛び散る勢いをコントロールすることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュで「マチエール（素材感）」を出すための工夫として適切なものはどれか。', '["異なる質感の素材を重ねる","絵の具を一切使わない","すべて同じ紙を使う","素材を細かく切り刻む"]', 0, 2, 'ザラザラした紙、ツルツルした写真、布などの異なる質感を組み合わせることで、作品に深みや面白さが生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムの歴史において、世界的に普及したきっかけとなった大会はどれか。', '["1964年東京オリンピック","1998年長野オリンピック","2020年東京オリンピック","1972年札幌オリンピック"]', 0, 3, '1964年の東京オリンピックで、言語の壁を越えるためにピクトグラムが本格的に採用され、世界に広まりました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具で「ぼかし」を表現する際、最も大切なことは何か。', '["紙をあらかじめ水で濡らしておく","絵の具をたっぷり塗る","ドライヤーで素早く乾かす","筆を乾燥させる"]', 0, 2, '紙を水で湿らせておくと、絵の具が紙の上で広がり、境界線が自然に溶け込む「ぼかし」が表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具で、透明感を出したい時に使うものはどれか。', '["水を多めに混ぜる","油を混ぜる","白い絵の具を混ぜる","木工用ボンドを混ぜる"]', 0, 2, 'アクリル絵の具は水で薄めることで透明水彩のような透明感のある表現が可能になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、周囲を汚さないために必要な配慮はどれか。', '["新聞紙などで周囲を広く覆う","絵の具を濃くする","網を使わない","筆を強く振る"]', 0, 1, 'スパッタリングは飛沫が広範囲に飛び散るため、周囲を汚さないよう新聞紙等で保護することが必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、絵の具が乾いてしまったらどうなるか。', '["転写がうまくいかない","より鮮明に転写できる","色が混ざりやすくなる","立体感が出る"]', 0, 2, 'デカルコマニーは絵の具の流動性を利用するため、乾いてしまうと紙に定着せず転写できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングで、偶然性を高めるための方法はどれか。', '["あえてコントロールせずに垂らす","筆を細かく動かす","定規を使って線を引く","下書きをしっかり描く"]', 0, 2, 'ドリッピングの魅力は「偶然性」にあります。描き手の意図を超えた形や線を楽しむことが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュで、作品に「奥行き」を出すための工夫はどれか。', '["素材を重ねて貼る","素材をすべて同じ大きさに切る","背景を真っ白にする","一つの素材しか使わない"]', 0, 3, '素材を重ねることで層ができ、影や重なりが生まれることで、平面的な作品に奥行きが生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムのデザインで、色の使い方の基本はどれか。', '["背景と図形のコントラストを強くする","多くの色を使ってカラフルにする","中間色を多用する","背景と図形を同系色にする"]', 0, 2, '遠くから見ても瞬時に認識できるように、背景と図形の色はコントラスト（明暗差）をはっきりさせることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具の「にじみ」技法に適している紙はどれか。', '["水を含みやすい画用紙や水彩紙","表面がツルツルのコピー用紙","油分を含んだ紙","プラスチックシート"]', 0, 2, '水彩紙は水分の吸収が良いため、絵の具がほどよく広がり、美しい「にじみ」を表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具で、筆を洗う際に注意すべきことはどれか。', '["乾く前に水でしっかり洗う","乾いてから剥がす","油で洗う","洗わずに放置する"]', 0, 1, 'アクリル絵の具は乾くと耐水性になり、筆が固まって使えなくなるため、使用後はすぐに水洗いする必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、型紙を複数回使う場合の注意点はどれか。', '["型紙の絵の具を乾かしてから重ねる","型紙を濡れたまま使う","型紙を破れるまで使う","型紙を使わずに描く"]', 0, 3, '型紙が濡れていると、次に置いた時に周囲が汚れたり、型紙自体がふやけて形が崩れたりするため注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、絵の具の色を混ぜるタイミングはどれか。', '["紙を合わせる直前や合わせている最中","絵の具を完全に乾かした後","紙を広げた後","パレットの上で完全に混ぜきってから塗る"]', 0, 2, '紙を合わせることで、紙の上で色が混ざり合い、筆では作れない複雑な色の重なりが生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングの技法で、絵の具が飛び散る勢いを強くするにはどうすればよいか。', '["高い位置から勢いよく垂らす","低い位置からゆっくり垂らす","絵の具を水で薄める","筆を動かさない"]', 0, 3, '高い位置から垂らすことで、重力により勢いが増し、飛び散る形がよりダイナミックになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュで、素材を貼る際に使う道具として適切なものはどれか。', '["スティックのりや木工用ボンド","油性マジック","水彩絵の具","セロハンテープのみ"]', 0, 1, '素材の厚みや種類に合わせて、しっかり接着できるのりやボンドを選ぶことが作品を長持ちさせるコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムにおいて、人物を表す際によく使われる形はどれか。', '["単純化された人型（ピクト）","リアルな人物画","顔のアップ","手足の長いキャラクター"]', 0, 1, 'ピクトグラムでは、誰が見ても「人」だと認識できるように、頭部を円、胴体を線などで単純化した形が用いられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具で、最も明るい色を表現するための方法はどれか。', '["紙の白さを残す","白の絵の具を混ぜる","水を多く使う","何度も重ね塗りをする"]', 0, 2, '透明水彩では白の絵の具を混ぜるよりも、紙の白さを活かす（塗らない）方が、より明るく透明感のある表現になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具の「メディウム」とは何か。', '["絵の具の性質を変える補助剤","絵の具を溶かすための油","絵の具を乾かすための道具","筆を洗うための洗剤"]', 0, 3, 'メディウムは、光沢を出したり、盛り上げたり、乾燥を遅らせたりと、絵の具の性質を調整するための補助剤です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、網をこする方向はどちらがよいか。', '["一定の方向にこする","ランダムに激しくこする","網を動かさずに筆だけを動かす","網を紙に押し付ける"]', 0, 2, '一定の方向にこすることで、飛沫が均一に飛び、画面のコントロールがしやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、紙を広げる時のコツはどれか。', '["ゆっくりと慎重に広げる","勢いよく一気に広げる","広げた後にドライヤーを当てる","広げた後に絵の具を足す"]', 0, 2, 'ゆっくり広げることで、絵の具の粘りによってできる独特の模様（糸を引くような形など）をきれいに残すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングで、複数の色を使う際の効果はどれか。', '["色が重なり合って複雑な表現になる","色が混ざって黒くなる","作品が平面的になる","色が分離して見えなくなる"]', 0, 2, '複数の色を順に垂らすことで、色が重なり、奥行きやリズム感のある豊かな画面が作れます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュで、素材の「切り方」による効果はどれか。', '["手でちぎると柔らかい輪郭になる","ハサミで切ると必ず作品が良くなる","カッターで切ると色が鮮やかになる","切り方は作品に影響しない"]', 0, 2, '手でちぎることで断面が毛羽立ち、柔らかい雰囲気や温かみのある表現が可能になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムで、非常口のマークが緑色である理由は何か。', '["安全や避難を連想させる色だから","最も目立つ色だから","他の色より安いから","法律で決まっているから"]', 0, 2, '緑色は安全や安心を象徴する色として、世界共通で避難誘導のサインに使用されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具で、色が乾いてから塗り重ねる技法を何というか。', '["ウェット・オン・ドライ","ウェット・オン・ウェット","スパッタリング","ドリッピング"]', 0, 3, '乾いた画面の上に色を重ねることで、下の色が透けながら重なり、深みのある表現が可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具は、どのような素材に描けるか。', '["紙、木、布、石、プラスチックなど多様な素材","紙にしか描けない","油分を含んだものには描けない","ガラスには絶対に描けない"]', 0, 2, 'アクリル絵の具は接着力が強く、様々な素材に定着するため、工作や立体作品にも幅広く使えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、飛沫の大きさを変えるために「網」を変える場合、どのような網がよいか。', '["目の粗い網と細かい網を使い分ける","網は使わずに手で飛ばす","網を二重にする","網を洗わずに使う"]', 0, 3, '網の目の大きさが変わると、通過する絵の具の粒の大きさが変わるため、表現の幅が広がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、絵の具を置く場所の工夫はどれか。', '["中心線付近に置く","紙の端にだけ置く","紙全体を塗りつぶす","絵の具を置かずに水だけを置く"]', 0, 2, '中心線付近に絵の具を置くことで、紙を折った時に左右対称に広がりやすく、きれいな模様が作れます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングで、筆を使わずに絵の具を垂らす方法として適切なものはどれか。', '["容器から直接垂らす","指で弾く","ストローで吹く","すべて正しい"]', 3, 2, 'ドリッピングは筆に限らず、容器から直接垂らしたり、ストローで吹いて広げたりと、多様な方法で表現できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュにおいて、作品のテーマを決めるメリットは何か。', '["素材選びや構成がしやすくなる","絵の具をたくさん使える","作品を早く完成させられる","誰にも真似されない"]', 0, 1, 'テーマを決めることで、必要な素材や色、構成の方向性が明確になり、作品に統一感が生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムで、図形を「単純化」する理由はどれか。', '["情報を瞬時に伝えるため","描く時間を短縮するため","色を節約するため","紙を小さくするため"]', 0, 1, '複雑な情報を削ぎ落とし、単純な形にすることで、脳が素早く意味を理解できるように工夫されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具で、筆を洗うバケツの水が濁ってきたらどうすべきか。', '["こまめにきれいな水に入れ替える","濁った水の方が深みが出るのでそのまま使う","筆を洗わずに別の筆を使う","バケツを大きくする"]', 0, 1, '水が濁ると、次に使う色に濁りが混ざってしまうため、常にきれいな水を使うことが鮮やかな発色の基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具で、絵の具が服についた場合どうなるか。', '["乾くと落ちなくなる","水で簡単に落ちる","熱湯で落ちる","時間が経てば自然に消える"]', 0, 2, 'アクリル絵の具は耐水性があるため、服につくと乾いた後は洗濯しても落ちません。作業時は汚れてもよい服を着ることが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、型紙を固定する理由はどれか。', '["飛沫で型紙がずれるのを防ぐため","型紙を破らないため","絵の具を節約するため","網を使いやすくするため"]', 0, 2, '型紙がずれると、輪郭がぼやけてしまい、きれいなシルエットが表現できないため、しっかり固定することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、絵の具の量を増やしすぎるとどうなるか。', '["色が混ざりすぎて濁り、形が崩れる","より鮮明な形になる","乾きが早くなる","立体感が出る"]', 0, 3, '絵の具が多すぎると、紙を広げた時に絵の具が溢れて形が崩れ、色が混ざりすぎて汚い色になってしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ドリッピングで、画面全体にリズムを生むコツはどれか。', '["強弱や長短をつけて絵の具を垂らす","同じ太さの線を並べる","一色だけで描く","絵の具を垂らさずに塗る"]', 0, 2, '垂らす勢いや量に変化をつけることで、画面に動きやリズムが生まれ、飽きのこない作品になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'コラージュで、素材を「配置」する際に大切なことはどれか。', '["全体のバランスを見ながら決める","とにかく隙間なく埋める","一番大きい素材を最後に貼る","素材を重ねないようにする"]', 0, 2, '配置は作品の印象を大きく左右します。全体のバランスや視線の流れを考えながら配置することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'ピクトグラムのデザインにおいて、最も避けるべきことはどれか。', '["特定の文化や言語に依存すること","単純な図形を使うこと","コントラストを高くすること","普遍的なシンボルを使うこと"]', 0, 3, '特定の文化圏の人にしか伝わらない表現は、ピクトグラムの目的である「誰にでも伝わる」を損なうため避けるべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', '水彩絵の具で、筆に含ませる水の量を変えるとどうなるか。', '["色の濃淡が変化する","筆が長持ちする","絵の具の乾きが早くなる","色が混ざらなくなる"]', 0, 1, '水彩絵の具は水の量で色の濃淡をコントロールします。水が多いと薄く透明感があり、少ないと濃くはっきりとした色になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'アクリル絵の具で、色を混ぜて作る「中間色」の特徴はどれか。', '["濁りが少なく鮮やかさを保ちやすい","必ず黒っぽくなる","水彩よりも濁りやすい","混ぜるほど白くなる"]', 0, 2, 'アクリル絵の具は発色が良く、水彩に比べて混色しても色が濁りにくいため、鮮やかな中間色を作りやすいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'スパッタリングで、網を洗うタイミングはいつがよいか。', '["絵の具が乾く前","完全に乾いた後","作業の翌日","洗う必要はない"]', 0, 1, '網に絵の具が固まると目詰まりして使えなくなるため、使用後はすぐに水洗いしてきれいに保つことが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'art', 'デカルコマニーで、紙を折る回数について正しいのはどれか。', '["一回折るのが基本だが、工夫次第で変えてもよい","必ず二回折らなければならない","折ってはいけない","十回以上折る必要がある"]', 0, 2, '基本は二つ折りですが、折り方や回数を工夫することで、より複雑で面白い模様を生み出すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造において、粘土の重さを支え、芯になる骨組みのことを何というか。', '["心棒","木枠","台座","支柱"]', 0, 1, '塑造では、粘土が崩れないように金属や木材で骨組みを作ります。これを心棒と呼び、作品の安定性を高めるために不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀で木を彫る際、最も安全な基本姿勢はどれか。', '["刃の進む方向に手を置く","刃の進む方向の先に手を置かない","力を込めて一気に彫る","立って彫る"]', 1, 1, '彫刻刀は滑りやすいため、刃の進む先に手を置くのは非常に危険です。必ず刃の進行方向から手を外して作業します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画において、墨の濃淡を表現するために行うことは何か。', '["筆の太さを変える","墨に水を混ぜる","紙を濡らす","墨を乾燥させる"]', 1, 1, '水墨画では、墨に混ぜる水の量を調節することで、黒から薄い灰色までの豊かなグラデーション（濃淡）を作り出します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '江戸時代に庶民の間で流行した、多色刷りの木版画のことを何というか。', '["水墨画","浮世絵","障壁画","絵巻物"]', 1, 1, '浮世絵は江戸時代の風俗を描いた木版画で、特に多色刷りの「錦絵」が庶民に広く親しまれました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '俵屋宗達の代表作であり、金箔を背景に用いた屏風絵として有名なものはどれか。', '["風神雷神図屏風","富嶽三十六景","鳥獣戯画","洛中洛外図"]', 0, 2, '俵屋宗達の「風神雷神図屏風」は、金箔の背景に大胆な構図で神を描いた、日本美術を代表する傑作です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の種類で、線彫りや細い溝を彫るのに適しているのはどれか。', '["丸刀","平刀","三角刀","切り出し刀"]', 2, 1, '三角刀は刃先がV字型になっており、細い線を彫ったり、輪郭をはっきりさせたりするのに適した彫刻刀です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造で粘土を盛る際に、粘土同士をしっかり接着させるために必要な作業はどれか。', '["粘土を乾燥させる","粘土を叩いて密着させる","水を多く含ませる","ヘラで表面を削る"]', 1, 1, '粘土を盛る際、ただ乗せるだけでは剥がれやすいため、叩いたり押し付けたりして空気を抜き、密着させることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の鑑賞において、光と影の対比を強調する技法を何というか。', '["遠近法","キアロスクーロ","点描法","コラージュ"]', 1, 3, 'キアロスクーロはイタリア語で「明暗」を意味し、ルネサンス期以降の西洋絵画で立体感を出すために多用された技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「平刀」の主な用途はどれか。', '["細かい線を彫る","広い面を平らに削る","深い溝を彫る","角を丸くする"]', 1, 1, '平刀は刃先が真っ直ぐなため、仕上げの段階で表面を平らに整えたり、広い面積を削り取るのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の制作工程において、絵師、彫師、摺師の3者の役割分担を何と呼ぶか。', '["分業制","共同制作","工房制","専属制"]', 0, 1, '浮世絵は、絵を描く「絵師」、板を彫る「彫師」、紙に刷る「摺師」が協力する分業制によって大量生産されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画で、筆に墨をつけず、水だけで描く技法を何というか。', '["たらし込み","没骨法","渇筆","水墨"]', 0, 3, 'たらし込みは、乾かないうちに別の墨や水を垂らしてにじませる技法で、宗達や光琳が多用しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「丸刀」の特徴として正しいものはどれか。', '["刃が鋭利で直線的","刃が半円形で、柔らかな線や面を彫れる","刃がV字型で深い溝を彫れる","刃が斜めで細かい作業向き"]', 1, 1, '丸刀は刃先が丸みを帯びているため、木を削る際に抵抗が少なく、滑らかな曲線や面を彫るのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造において、粘土が乾燥してひび割れるのを防ぐための対策はどれか。', '["ドライヤーで乾かす","霧吹きで水をかける","直射日光に当てる","粘土を厚く盛る"]', 1, 1, '粘土は乾燥すると収縮してひび割れます。制作中は霧吹きで適度に湿らせ、保管時はビニール袋で包むのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の「遠近法」のうち、近くを大きく、遠くを小さく描く技法を何というか。', '["線遠近法","空気遠近法","多視点法","鳥瞰図"]', 0, 1, '線遠近法は、消失点に向かって線を引くことで、平面上に奥行きを表現する西洋美術の基本的な技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「切り出し刀」の主な用途はどれか。', '["広い面を削る","輪郭を整えたり、細かい切り込みを入れる","深い穴を掘る","表面を磨く"]', 1, 1, '切り出し刀は刃先が斜めになっており、細かい部分の切り込みや、輪郭線をはっきりさせる作業に適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '日本の伝統美術である「水墨画」の主な色味はどれか。', '["赤と黒","青と白","黒と白（墨の濃淡）","金と銀"]', 2, 1, '水墨画は、墨の黒と紙の白、そしてその中間にある濃淡だけで表現する、精神性の高い芸術です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の「錦絵」とはどのようなものか。', '["白黒の版画","多色刷りの木版画","手描きの絵画","油絵"]', 1, 1, '錦絵は、複数の色版を重ねて刷ることで完成する多色刷りの木版画で、江戸時代に完成されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造で作品を作る際、心棒に粘土を盛る前に何をする必要があるか。', '["粘土を焼く","心棒に針金などを巻き付け、粘土が落ちないようにする","心棒を塗装する","粘土を冷やす"]', 1, 1, '心棒が滑らかすぎると粘土が滑り落ちてしまいます。針金や紐を巻き付けて表面を粗くし、粘土の食いつきを良くします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術における「印象派」の特徴として適切なものはどれか。', '["光の移ろいや色彩を重視する","写実的に描く","幾何学的な形を強調する","暗い色調で重厚に描く"]', 0, 1, '印象派は、光の変化やその瞬間の色彩を捉えることを重視し、筆触をあえて残す技法が特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀で木を彫る際に「逆目（さかめ）」とはどういう状態か。', '["木目に沿って彫ること","木目に逆らって彫ること","木を横に切ること","彫りすぎること"]', 1, 1, '逆目とは木目に逆らって彫ることで、木が割れたり、表面がささくれたりして綺麗に彫れません。木目を確認することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画で、筆の穂先を斜めにして描く技法を何というか。', '["側筆","直筆","渇筆","没骨"]', 0, 3, '側筆は筆の腹を使って描く技法で、面を塗ったり、独特の掠れ（かすれ）を表現したりするのに使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造において、粘土の「量感」を表現するとはどういうことか。', '["重さを測ること","立体的な厚みや塊の存在感を感じさせること","表面を滑らかにすること","色を塗ること"]', 1, 1, '量感とは、彫刻において物体が持つ重みやボリューム感のことです。凹凸を強調することで表現されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '日本の伝統的な屏風絵で、金箔を背景に用いる主な目的は何か。', '["部屋を明るく見せるため","高級感を出すため","光を反射させ、華やかな空間を作るため","絵を保護するため"]', 2, 1, '金箔は光を反射する性質があり、暗い室内に置かれた屏風が光を捉えることで、空間全体を華やかに演出します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の刃を研ぐ際に使用する道具はどれか。', '["やすり","砥石","サンドペーパー","布"]', 1, 1, '彫刻刀の切れ味を維持するためには、定期的に砥石で研ぐ必要があります。刃の角度に合わせて研ぐのがコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の鑑賞において「ルネサンス」とはどのような時代か。', '["古代ギリシャ・ローマの文化を復興しようとした時代","抽象画が生まれた時代","写真が発明された時代","宗教を否定した時代"]', 0, 1, 'ルネサンスは「再生」を意味し、古代ギリシャ・ローマの人間中心の文化や芸術を再評価した時代です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画において、筆を乾かして描く技法を何というか。', '["渇筆","没骨","たらし込み","側筆"]', 0, 1, '渇筆（かっぴつ）は、筆の水分を少なくして描くことで、独特の掠れた質感を出す技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造の制作において、粘土を盛る際に「ヘラ」を使う主な目的はどれか。', '["粘土を冷やすため","細かい部分の形を整えたり、表面をならしたりするため","粘土を早く乾かすため","粘土を削り取るためだけ"]', 1, 1, 'ヘラは指では届かない細かい凹凸の修正や、表面の仕上げに非常に役立つ塑造の必須道具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵師として有名な「葛飾北斎」の代表作はどれか。', '["富嶽三十六景","東海道五十三次","風神雷神図","見返り美人図"]', 0, 1, '葛飾北斎の「富嶽三十六景」は、富士山を様々な角度から描いた浮世絵の連作で、世界的に有名です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀で木を彫る際、木を固定するために使う道具はどれか。', '["万力（クランプ）","ハンマー","定規","ペンチ"]', 0, 1, '木を彫る際、木が動くと怪我の原因になります。万力やクランプで作業台にしっかりと固定することが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造作品が完成した後の保管方法として適切なものはどれか。', '["直射日光に当てる","乾燥させないようにビニール袋に入れる","水に浸す","すぐに解体する"]', 1, 1, '粘土は急激に乾燥するとひび割れるため、完成後もしばらくはビニール袋などで包み、ゆっくり乾燥させます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の「静物画」とは、主に何を描いた絵画か。', '["人物","風景","動かない物（果物や花など）","歴史的な事件"]', 2, 1, '静物画は、果物、花、食器などの動かない物を対象とした絵画のジャンルです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画の「没骨法（もっこつほう）」とはどのような技法か。', '["輪郭線を描かずに、色面や墨面で形を表す技法","細かい線を重ねる技法","墨を塗りつぶす技法","筆を使わない技法"]', 0, 3, '没骨法は輪郭線を描かず、墨の濃淡や筆のタッチだけで対象の形や立体感を表現する技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀で彫った後の木版画の表面に、インクを塗るために使う道具はどれか。', '["筆","ローラー","スポンジ","布"]', 1, 1, '版画では、ローラーを使ってインクを均一に伸ばし、版の凸部分にインクを乗せるのが一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造において、粘土の「内側」に空洞を作らないようにする理由は何か。', '["重くするため","乾燥時にひび割れや爆発を防ぐため","粘土を節約するため","形を崩しやすくするため"]', 1, 1, '粘土の中に空気が入ると、焼成時や乾燥時に空気が膨張して作品が割れたり、ひび割れの原因になったりします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の版画制作で、色の数だけ必要なものは何か。', '["絵師","版木","紙","インク"]', 1, 1, '多色刷りの浮世絵では、色ごとに異なる版木（色版）を彫る必要があります。色の数だけ版木が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の鑑賞において「構図」とは何を指すか。', '["絵の具の種類","画面の中での形や色の配置","絵のサイズ","描く時間"]', 1, 1, '構図とは、画面の中にモチーフをどのように配置するかという計画のことです。これにより絵の印象が大きく変わります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「丸刀」で彫った跡の特徴はどれか。', '["鋭い直線","U字型の溝","V字型の溝","平らな面"]', 1, 1, '丸刀は刃先が丸いため、彫るとU字型の溝ができます。彫り跡に柔らかい表情が出るのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画の「筆の直筆（ちょくひつ）」とはどのような状態か。', '["筆を斜めにして描く","筆を紙に対して垂直に立てて描く","筆を寝かせて描く","筆を素早く動かす"]', 1, 1, '直筆は筆を垂直に立てて描く技法で、均一で力強い線を引くのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造で粘土を盛る際、最も大切なことは何か。', '["早く完成させること","全体のバランスと量感を確認すること","表面をピカピカにすること","色を塗ること"]', 1, 1, '塑造では、特定の場所ばかり作るのではなく、全体を見ながらバランスや量感を整えていくことが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '日本の伝統的な「屏風」の主な役割はどれか。', '["窓を隠す","部屋の仕切りや装飾","椅子として使う","屋根を支える"]', 1, 1, '屏風は、部屋の仕切りとして使われるほか、美しい絵を描くことで装飾品としての役割も果たしてきました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の刃を研ぐとき、砥石に水をかける理由は何か。', '["刃を冷やすため","砥石の滑りを良くし、研ぎカスを取り除くため","砥石を柔らかくするため","刃を錆びさせるため"]', 1, 1, '水は研ぎカスを流し、砥石の表面を常に新鮮な状態に保つために必要不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の「肖像画」とは何を描いたものか。', '["風景","特定の人物の顔や姿","動物","建物"]', 1, 1, '肖像画は、特定の人物の容姿や性格、社会的地位などを表現するために描かれる絵画です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画で、墨を磨る際に使う道具はどれか。', '["硯（すずり）","筆","紙","パレット"]', 0, 1, '墨は硯の上で水と混ぜて磨ることで、墨汁を作ります。硯の質も墨の濃淡に影響します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「切り出し刀」で、最も注意すべき点はどれか。', '["刃が小さいため、力任せに彫る","刃先が鋭いため、指を切らないようにする","刃を寝かせて彫る","毎日洗う"]', 1, 1, '切り出し刀は非常に鋭利です。特に細かい作業で使うため、刃先が指に向かないよう細心の注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造において、粘土を「こねる」主な目的はどれか。', '["粘土を柔らかくし、中の空気を抜くため","粘土を温めるため","色を混ぜるため","形を整えるため"]', 0, 1, '粘土をこねることで、粘土の硬さを均一にし、中に含まれている空気を抜くことで、制作中のひび割れを防ぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の「摺り」の工程で、紙を版木に押し付けるために使う道具はどれか。', '["バレン","ローラー","筆","ハンマー"]', 0, 1, 'バレンは、紙の裏から均一に力を加えてインクを紙に写し取るために使われる、版画特有の道具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の鑑賞において「色彩」が果たす役割はどれか。', '["絵の重さを決める","感情や雰囲気を伝える","絵の価格を決める","描く時間を決める"]', 1, 1, '色彩は、温かさや冷たさ、悲しみや喜びなど、見る人の感情に直接訴えかける重要な要素です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「平刀」で、板の表面を平らにするコツはどれか。', '["刃を立てて彫る","刃を寝かせて、少しずつ削る","力を込めて一気に削る","木目に沿って彫る"]', 1, 1, '平刀を寝かせて使うことで、刃の幅を活かして広い面を均一に削り取ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画において、筆の「穂先」を整えることを何というか。', '["筆を洗う","筆を整える（穂先をまとめる）","筆を乾かす","筆を捨てる"]', 1, 1, '筆の穂先が割れていると綺麗な線が描けません。墨をつけるたびに穂先を整えるのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造作品の「土台」が重要な理由は何か。', '["作品を高く見せるため","作品を安定させ、転倒を防ぐため","粘土を節約するため","作品を軽くするため"]', 1, 1, '塑造は重量があるため、しっかりとした土台がないとバランスを崩して倒れてしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の「版木」に使われる木材として一般的なものはどれか。', '["サクラ","スギ","マツ","ヒノキ"]', 0, 3, '浮世絵の版木には、硬くて彫りやすく、耐久性のあるサクラの木が伝統的に使われてきました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の「遠近法」で、遠くのものがぼやけて見える技法を何というか。', '["空気遠近法","線遠近法","点描法","コラージュ"]', 0, 1, '空気遠近法は、大気の影響で遠くのものが青白く、輪郭がぼやけて見える現象を表現する技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「三角刀」で彫った跡の特徴はどれか。', '["丸い溝","鋭いV字の溝","平らな面","ギザギザの線"]', 1, 1, '三角刀は刃がV字型をしているため、彫ると鋭いV字の溝ができます。細かな線彫りに最適です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造で粘土を盛る際、指で押さえるだけでなく、ヘラで「ならす」効果は何か。', '["粘土の表面を滑らかにし、形を整える","粘土を硬くする","粘土を軽くする","粘土を乾燥させる"]', 0, 1, 'ヘラでならすことで、指の跡を消し、作品の表面を滑らかにして完成度を高めることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画で、墨の「濃い」部分を何と呼ぶか。', '["濃墨（のうぼく）","淡墨（たんぼく）","中墨","薄墨"]', 0, 1, '水墨画では、濃い墨を「濃墨」、薄い墨を「淡墨」と呼び、これらを使い分けることで表現の幅が広がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '浮世絵の版画で、色がずれないように合わせる目印を何というか。', '["見当（けんとう）","ガイド","マーク","ポイント"]', 0, 3, '見当は、版木に彫られたL字型の印で、紙を置く位置を正確に合わせるための重要な工夫です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '西洋美術の「点描法」とはどのような技法か。', '["細かい点を打って絵を描く","線を引いて描く","塗りつぶして描く","写真を貼る"]', 0, 1, '点描法は、小さな色の点を並べることで、見る人の目で色が混ざり合って見えるようにする技法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '彫刻刀の「丸刀」で深い溝を彫るコツはどれか。', '["一度に深く彫る","同じ場所を何度か往復して少しずつ彫る","力を込めて一気に押し込む","刃を立てて彫る"]', 1, 1, '一度に深く彫ろうとすると木が割れたり、怪我をしたりします。少しずつ彫り進めるのが安全で綺麗に仕上がるコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '塑造作品の「量感」を出すために効果的なことは何か。', '["表面を平らにする","凹凸をはっきりと作り、塊として捉える","色を塗る","細部を細かく作り込む"]', 1, 1, '量感は、塊としての存在感です。細部よりも、まずは大きな塊の凹凸を意識して形を作ることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '水墨画の「余白」の役割はどれか。', '["紙が足りないから","見る人の想像力を広げるため","墨を節約するため","絵を明るくするため"]', 1, 1, '水墨画では、描かない部分（余白）が空や水、空気などを表現し、見る人の想像力を刺激する重要な要素となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'art', '木彫の彫刻刀で、最も太い線や広い面を彫るのに適しているのはどれか。', '["丸刀（大）","三角刀","切り出し刀","平刀（小）"]', 0, 1, '丸刀はサイズが豊富で、大きな丸刀を使えば広い面を大胆に削り取ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走において、スタートの合図前に体を動かしてしまうことを何というか。', '["フライング","スタートダッシュ","クラウチング","テークオーバー"]', 0, 1, '合図より前にスタートすることをフライングと呼び、失格の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'クラウチングスタートの際、スターティングブロックに足を置く位置として適切なのはどれか。', '["前足と後ろ足で位置を分ける","両足を揃える","前足だけを置く","後ろ足だけを置く"]', 0, 2, 'クラウチングスタートでは、前足と後ろ足の位置を前後にずらしてブロックにセットします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'クラウチングスタートの「セット」の合図でとる姿勢はどれか。', '["腰を肩より少し高く上げる","腰を地面につける","立ったまま待つ","膝を完全に伸ばす"]', 0, 2, 'セットの合図では、腰を肩より少し高く上げ、前傾姿勢をとることで加速しやすくします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーにおいて、バトンを受け渡すために決められた区間を何というか。', '["テークオーバーゾーン","スタートゾーン","加速ゾーン","バトンゾーン"]', 0, 1, 'テークオーバーゾーンは、バトンを渡す側と受ける側が共に走って受け渡しを行うための区間です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'バトンパスにおいて、受け手が後ろを振り返らずにバトンを受け取る方法を何というか。', '["アンダーハンドパス","オーバーハンドパス","サイドパス","バックパス"]', 0, 2, 'アンダーハンドパスは、受け手が手のひらを後ろに向け、下からバトンを受け取る方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの助走の目的として最も適切なものはどれか。', '["踏み切りに必要な水平方向の速度を得る","高く跳ぶための準備","着地を安定させる","歩数を数える"]', 0, 1, '助走は、踏み切り時に大きな水平方向の速度を得て、遠くへ跳ぶためのエネルギーを作るために行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びで、踏み切り板を越えて踏み切った場合、記録はどうなるか。', '["無効（ファウル）","記録は半分になる","やり直しができる","そのまま計測される"]', 0, 1, '踏み切り板の線を越えて踏み切るとファウルとなり、その試技は記録なしとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動における「ストレッチ」の主な目的はどれか。', '["筋肉の柔軟性を高め、けがを予防する","筋肉を太くする","心肺機能を高める","瞬発力を鍛える"]', 0, 1, 'ストレッチは筋肉を伸ばすことで柔軟性を高め、運動中のけがを防ぐ効果があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '静的ストレッチを行う際の注意点として適切なものはどれか。', '["反動をつけず、ゆっくりと筋肉を伸ばす","できるだけ強く反動をつける","息を止めて行う","痛みを感じるまで伸ばす"]', 0, 2, '静的ストレッチは、反動をつけず、呼吸を止めずにリラックスして行うのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走でタイムを縮めるために最も重要な要素はどれか。', '["ストライドとピッチを最適化する","大きく腕を振るだけにする","スタートだけ速くする","ゴール直前で減速する"]', 0, 2, 'ストライド（歩幅）とピッチ（歩数）のバランスを最適化することが、走速度を高める鍵です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーでバトンを渡す際、受け手はどのような姿勢をとるのが良いか。', '["走り出しやすい姿勢で待つ","立ち止まって待つ","後ろを向いて待つ","座って待つ"]', 0, 2, '受け手は、加速しながらバトンを受け取れるよう、走り出しやすい姿勢で待つのが理想的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの着地で、体を前に倒すために重要なことは何か。', '["両足をそろえて前方に投げ出す","着地直前に体を後ろに倒す","片足だけで着地する","着地後に後ろを振り返る"]', 0, 2, '着地時に両足を前方に投げ出すことで、重心を前に移動させ、記録を伸ばすことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '運動前のウォーミングアップの目的として正しくないものはどれか。', '["体温を下げてリラックスさせる","筋肉の柔軟性を高める","心拍数を徐々に上げる","運動の準備をする"]', 0, 1, 'ウォーミングアップは体温を上げ、筋肉を動かしやすくするために行います。下げるのは逆効果です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの記録は、どこからどこまでを測るか。', '["踏み切り板から着地した最も近い跡まで","踏み切り板から着地した最も遠い跡まで","助走開始地点から着地地点まで","踏み切り板から体全体まで"]', 0, 2, '記録は、踏み切り板の端から、体の一部が地面に触れた最も近い地点までを計測します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'クラウチングスタートで「位置について」の合図の際、手はどこに置くか。', '["スタートラインの後ろ","スタートラインの上","スタートラインの先","膝の上"]', 0, 1, '手はスタートラインの後ろに置き、ラインを越えないようにセットします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'バトンパスで、受け手がバトンを受け取る際に意識すべきことはどれか。', '["渡す相手の合図を待つ","バトンを奪い取る","目をつぶる","立ち止まって待つ"]', 0, 2, '受け手は渡す相手の合図（声など）を確認し、タイミングを合わせて走り出す必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動で「動的ストレッチ」とはどのようなものか。', '["体を動かしながら筋肉をほぐす","静止した状態で筋肉を伸ばす","重りを持って筋トレする","寝転がって休む"]', 0, 2, '動的ストレッチは、関節を動かしながら筋肉に刺激を与え、運動に適した状態にするものです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走で、腕を振る目的として最も適切なものはどれか。', '["走るリズムを整え、推進力を高める","バランスを崩すため","疲れを隠すため","相手を威嚇するため"]', 0, 1, '腕振りは、走るリズムを作り、足の動きと連動させて推進力を生むために重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの「空中姿勢」の目的はどれか。', '["バランスを保ち、着地に備える","高く跳び上がるため","助走のスピードを上げるため","審判に見せるため"]', 0, 2, '空中でバランスを整えることで、スムーズな着地と記録の向上を目指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーにおいて、テークオーバーゾーン内でバトンが渡せなかった場合はどうなるか。', '["失格となる","5秒のペナルティ","ゾーンの外で渡せばよい","やり直しができる"]', 0, 2, 'テークオーバーゾーン外でのバトン受け渡しはルール違反となり、失格となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走において、ゴールを駆け抜ける際のアドバイスとして適切なものはどれか。', '["ゴールラインの先まで全力で走る","ゴール直前で減速する","ゴールラインで止まる","後ろを振り返る"]', 0, 1, 'ゴールラインで減速するとタイムが落ちるため、ラインの先まで全力で駆け抜けるのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'ストレッチを行う際に、最も避けるべきことはどれか。', '["無理に反動をつけて伸ばすこと","呼吸をすること","リラックスすること","毎日続けること"]', 0, 1, '無理な反動は筋肉や腱を痛める原因となるため、絶対に行ってはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの踏み切りの際、重心はどこにあるのが理想的か。', '["体の真下","体の後ろ","大きく前","頭の上"]', 0, 3, '踏み切り時に重心が体の真下にあることで、効率よく上方向へ力を伝えることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーのバトンパスで、受け手がバトンを受け取る手の形として適切なものはどれか。', '["手のひらを上または後ろに向ける","拳を握る","指を組む","腕を組む"]', 0, 2, 'アンダーハンドパスでは、受け手が手のひらを広げて差し出すことで、渡し手がバトンを置きやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動における「仲間との協力」の意義として適切なものはどれか。', '["お互いに励まし合い、運動意欲を高める","相手を負かすために行う","一人でやるより楽だから","先生に怒られないため"]', 0, 1, '仲間と協力することで、運動の楽しさが増し、お互いに高め合うことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走のスタートで、最も反応速度が求められるのはどの瞬間か。', '["号砲（ピストル）が鳴った瞬間","セットの合図が出た瞬間","位置についた瞬間","ゴールした瞬間"]', 0, 1, '号砲が鳴った瞬間に素早く反応して走り出すことが、スタートダッシュの成功に不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びで、踏み切り板を強く踏むためのコツはどれか。', '["足裏全体で力強く踏み込む","つま先だけで跳ぶ","かかとだけで跳ぶ","助走を緩める"]', 0, 2, '足裏全体で踏み込むことで、地面からの反発力を最大限に利用することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーでバトンを落としてしまった場合、どうするのが正しいか。', '["自分で拾って走り続ける","審判に拾ってもらう","そのまま走る","棄権する"]', 0, 2, 'バトンを落とした場合は、自分で拾って競技を続行することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '運動後のクールダウンの目的はどれか。', '["疲労回復を早め、筋肉の張りを取り除く","筋肉を鍛える","心拍数を急激に上げる","すぐに帰宅するため"]', 0, 1, 'クールダウンは、運動で高まった心拍数を落ち着かせ、疲労物質の除去を助けるために行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走において、前傾姿勢を保つのはどの段階か。', '["スタート直後の加速局面","ゴール直前","中盤の巡航局面","準備運動中"]', 0, 2, 'スタート直後は前傾姿勢を保つことで、地面を強く押し、加速しやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの助走で、歩数を一定にする理由は何か。', '["正確に踏み切り板を踏むため","速く走るため","疲れにくくするため","高く跳ぶため"]', 0, 2, '助走の歩数を一定にすることで、踏み切り板に対して正確な足位置で踏み切ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーのバトンパスで、渡す側が気をつけることはどれか。', '["受け手の走るスピードに合わせる","バトンを投げて渡す","受け手を追い越す","立ち止まって渡す"]', 0, 2, '渡す側は、受け手のスピードに合わせて走り、スムーズにバトンを渡す必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動で、筋力トレーニングを行う際の適切な頻度はどれか。', '["休息を挟みながら定期的に行う","毎日限界まで行う","週に一度だけ行う","全く行わない"]', 0, 2, '筋肉を回復させる時間（休息）を設けることが、効率的なトレーニングには重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走の「ピッチ」とは何か。', '["足の回転数","歩幅の広さ","腕の振りの大きさ","スタートの速さ"]', 0, 2, 'ピッチは足の回転の速さ（回転数）を指し、ストライド（歩幅）と並ぶ走速度の要素です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びで、踏み切り足はどちらにするのがよいか。', '["自分が踏み切りやすい方の足","必ず右足","必ず左足","両足同時に踏み切る"]', 0, 1, '踏み切り足は、自分が最も力強く踏み切れる利き足などを選ぶのが一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーのバトンパスにおいて、テークオーバーゾーンの長さはどれくらいか。', '["20メートル","5メートル","50メートル","100メートル"]', 0, 3, '陸上競技のルールでは、バトンパスを行うテークオーバーゾーンは20メートルと定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '運動中に水分補給を行う目的として適切なものはどれか。', '["脱水症状を防ぐため","体重を増やすため","お腹を満たすため","喉を潤すためだけ"]', 0, 1, '運動中は汗で水分が失われるため、脱水症状を防ぐためにこまめな水分補給が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走で、スタートダッシュの際に目線はどこに向けるのがよいか。', '["斜め前方の地面","真上","真横","ゴール"]', 0, 2, 'スタート直後は斜め前方の地面を見ることで、前傾姿勢を維持しやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの助走で、スピードを維持したまま踏み切るために必要なことは何か。', '["踏み切り直前に減速しない","踏み切り直前に加速する","踏み切り直前に止まる","踏み切り直前に歩幅を広げる"]', 0, 2, '助走で得たスピードを殺さずに踏み切ることが、遠くへ跳ぶための重要なポイントです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーでバトンパスの練習をする際、最も大切なことは何か。', '["受け手と渡し手のタイミングを合わせる","バトンを高く投げる","速く走ることだけを考える","バトンを持たずに走る"]', 0, 1, 'バトンパスは、二人の走るタイミングと位置が一致した時に最もスムーズに行えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動で、バランス運動を行う目的はどれか。', '["体の安定性を高める","筋肉を大きくする","心肺機能を高める","柔軟性を高める"]', 0, 2, 'バランス運動は、体の重心をコントロールする能力を高め、安定した動作を可能にします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走の「ストライド」とは何か。', '["一歩の歩幅","足の回転数","腕の振りの速さ","スタートの反応"]', 0, 2, 'ストライドは一歩の歩幅を指します。これを広げつつ回転数を維持するのが速く走るコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの着地で、砂場をならすのはなぜか。', '["正確に記録を測定するため","見た目をきれいにするため","砂を柔らかくするため","次の人のため"]', 0, 1, '砂場を平らにしておくことで、着地した跡を正確に計測できるようにするためです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーで「テークオーバーゾーン」をうまく使うコツは何か。', '["ゾーン内で最大限に加速する","ゾーンの入り口で止まる","ゾーンの外で待つ","ゾーン内でバトンを落とす"]', 0, 2, 'ゾーン内で加速し、受け手がスピードに乗った状態でバトンを受け取ることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '運動中に体調が悪くなった場合、どうするのが正しいか。', '["すぐに運動を中止し、休む","我慢して続ける","友達に隠す","先生に言わずに帰る"]', 0, 1, '体調不良時は無理をせず、すぐに運動を中止して休むことが安全管理上最も重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'クラウチングスタートで、後ろ足の膝は地面についているか。', '["ついている","ついていない","どちらでもよい","浮かせている"]', 0, 2, '「位置について」の合図では、後ろ足の膝を地面につけて待機するのが基本姿勢です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの助走距離は、どのように決めるのがよいか。', '["自分の走力に合わせて練習で決める","全員同じ距離にする","適当に決める","長いほどよい"]', 0, 2, '助走距離は、自分が最高速度に達するまでの距離を練習で確認して決めるのがベストです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーのバトンパスで、受け手がバトンを受け取る直前にすること。', '["腕を後ろに伸ばして待つ","立ち止まる","後ろを振り返る","座り込む"]', 0, 2, '受け手は、渡し手がバトンを渡しやすくするために、腕を後ろに伸ばして待つのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動で、筋力トレーニングの際、呼吸はどうすべきか。', '["力を入れる時に吐く","力を入れる時に吸う","ずっと止める","意識しなくてよい"]', 0, 2, '力を入れる瞬間に息を吐くことで、腹圧が高まり、動作が安定しやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走で、ゴールラインを通過する際、最もタイムが速くなるのはどれか。', '["胸を前に突き出して駆け抜ける","手を上げて喜ぶ","減速して通過する","横を向いて通過する"]', 0, 2, '胴体（トルソー）がラインを越えた瞬間が記録となるため、胸を突き出すのが有効です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの踏み切りで、視線はどこに向けるべきか。', '["前方遠く","足元","空","真下"]', 0, 2, '足元を見ると体が前傾しすぎるため、前方遠くを見ることで姿勢を保ちやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーにおいて、バトンはどのようなものか。', '["軽量な円筒形の棒","重い鉄の棒","柔らかい布","ボール"]', 0, 1, 'バトンは、走りやすさを考慮して軽量な円筒形の棒で作られています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '運動後のストレッチで意識することはどれか。', '["筋肉の緊張をほぐすこと","さらに筋肉を追い込むこと","心拍数を上げること","早く帰ること"]', 0, 1, '運動後のストレッチは、筋肉の緊張を解き、疲労回復を促すために非常に重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走のスタートで、スターティングブロックを使うメリットは何か。', '["地面を強く蹴り出せる","楽に走れる","距離が短くなる","転ばなくなる"]', 0, 2, 'ブロックに足を固定することで、地面を強く蹴り出し、加速力を高めることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びの着地で、足を砂場につけた後、どうするのがよいか。', '["そのまま前方に歩き出す","後ろに倒れる","その場で止まる","砂場から後ろに飛び出す"]', 0, 2, '着地後は、記録を損なわないよう、前方に歩き出して砂場から出るのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', 'リレーでバトンパスの練習をする際、何が最も重要か。', '["安全なバトンの受け渡し","速く走る技術だけ","バトンを落とさないことだけ","誰が一番速いか決めること"]', 0, 1, 'リレーはチーム競技なので、安全かつスムーズなバトンの受け渡しが最も重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '体つくり運動で、柔軟性を高めるメリットはどれか。', '["けがをしにくくなる","背が伸びる","足が速くなる","体重が減る"]', 0, 1, '柔軟性が高まると関節の可動域が広がり、運動中のけがの予防につながります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '短距離走で、走る際に腕を振る角度はどれくらいが適切か。', '["肘を約90度に曲げる","腕を真っ直ぐ伸ばす","腕を大きく回す","腕を動かさない"]', 0, 2, '肘を約90度に曲げて振ることで、最も効率よく腕を振ることができ、走るリズムが作れます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'pe', '走り幅跳びで、踏み切り板を足で踏むとき、足のどの部分で踏むのがよいか。', '["足の裏全体","かかと","つま先","足の外側"]', 0, 2, '足の裏全体で踏み込むことで、地面からの反発力を効率よく上方向へ伝えることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールの泳法で、最も推進力を生み出すのはどの動きですか。', '["腕によるストローク","足によるバタ足","頭の上下運動","体のローリング"]', 0, 1, 'クロールにおいて推進力の大部分は腕のストロークによって生み出されます。バタ足は主に体のバランスを保つ役割が大きいです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎの足の動き（キック）の正しい順序はどれですか。', '["引きつけ・蹴り・閉じ","蹴り・引きつけ・閉じ","閉じ・蹴り・引きつけ","引きつけ・閉じ・蹴り"]', 0, 2, '平泳ぎのキックは、かかとをお尻に引きつけ、足首を返して外側に蹴り出し、最後に両足を閉じる動作が基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業前、準備運動を行う主な目的として適切なものはどれですか。', '["筋肉をほぐし怪我を防ぐ","泳ぐ距離を伸ばす","水温を上げる","水着を乾きやすくする"]', 0, 1, '準備運動は筋肉や関節を温めて柔軟にし、急な運動による怪我や足のつりを防ぐために非常に重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の前転で、回転をスムーズにするために重要なことは何ですか。', '["背中を丸めて小さくなる","手をつかずに回る","足を大きく開く","頭を高く上げる"]', 0, 1, '背中を丸めて「ゆりかご」のような姿勢を作ることで、重心が移動しやすくなり、スムーズに回転することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の後転で、手のつく位置として適切なのはどこですか。', '["肩の近く（耳の横）","腰の近く","足の近く","マットの外"]', 0, 2, '後転では肩の近くに手を置き、マットを押すことで頭がマットに強く打ち付けられるのを防ぎ、回転を助けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱運動で、開脚跳びをする際に最も重要なポイントはどれですか。', '["手でしっかり跳び箱を押す","目をつぶって跳ぶ","足を閉じたまま跳ぶ","助走を一切しない"]', 0, 1, '手で跳び箱を強く押す（突き放す）ことで、体が浮き上がり、足を開くための時間とスペースを確保できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒運動の「逆上がり」で、回転を助けるために意識すべきことは何ですか。', '["鉄棒を体から離さない","足で地面を強く蹴る","腕を伸ばしきる","後ろに反る"]', 0, 2, '鉄棒を体に引き寄せ、へそを鉄棒に近づけるように意識することで、回転の半径が小さくなり回りやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳中に気分が悪くなった場合、最も適切な行動はどれですか。', '["すぐに近くの先生や仲間に伝える","我慢して泳ぎ続ける","一人で静かに休む","そのまま水中に潜る"]', 0, 1, '水泳中の体調不良は重大な事故につながる可能性があるため、迷わず周囲の大人や仲間に助けを求めるのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の倒立で、バランスを保つために必要なことは何ですか。', '["指先で細かく調整する","足首を曲げる","腰を大きく反らす","目線を足元に向ける"]', 0, 3, '倒立では、指先でマットを捉えて重心をコントロールすることで、バランスを保ちます。目線は手の間を見るのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'スポーツのマナーとして、試合後の挨拶で最も大切なことは何ですか。', '["相手への敬意を表す","勝敗の理由を説明する","審判に文句を言う","すぐに帰宅する"]', 0, 1, 'スポーツは相手がいて成り立つものです。勝敗に関わらず、互いの健闘を称え合うことがスポーツマンシップの基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールの呼吸動作で、正しいタイミングはどれですか。', '["顔を横に向けたとき","顔を正面に向けたとき","顔を真下に向けたとき","息を止めているとき"]', 0, 2, 'クロールでは、腕のストロークに合わせて頭を自然に横に向け、口で素早く息を吸います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱運動で、助走の目的として正しいものはどれですか。', '["踏み切りに必要な勢いをつける","跳び箱を移動させる","着地を安定させる","自分の順番を待つ"]', 0, 1, '助走は、踏み切り板で高く跳ぶための水平方向のエネルギーを確保するために不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒運動で、前回り下りを行う際の安全上の注意点はどれですか。', '["鉄棒をしっかり握り続ける","勢いよく手を離す","足から着地しない","目を閉じて回る"]', 0, 2, '前回り下りでは、最後まで鉄棒を握り、コントロールを失わないようにすることが安全な着地につながります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動で、前転の後に立ち上がる際、反動を利用するために必要なことは何ですか。', '["足を引き寄せる","手をマットから離す","頭を後ろに反らす","足を大きく広げる"]', 0, 2, '回転の勢いを利用して、足をお尻の近くに素早く引き寄せることで、スムーズに立ち上がることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の安全ルールで、プールサイドでやってはいけないことは何ですか。', '["走ること","歩くこと","準備運動をすること","先生の話を聞くこと"]', 0, 1, 'プールサイドは濡れていて滑りやすいため、走ると転倒して頭を打つなどの重大な事故につながる恐れがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールの泳法で、体が沈まないようにするために重要なのは何ですか。', '["姿勢を水平に保つ","頭を高く上げる","足を激しく動かす","腕を速く回す"]', 0, 2, '頭を上げすぎると腰が沈みます。目線を底に向け、体を水面と水平に保つことが抵抗を減らし、浮きやすくします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '器械運動において、補助者が行うべき最も重要なことは何ですか。', '["安全を確保し、怪我を防ぐ","技の点数をつける","大きな声で応援する","自分の練習を優先する"]', 0, 1, '補助者は、練習者が安全に技を行えるように見守り、転倒や衝突などの危険から守る役割を担います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎの泳法で、推進力を高めるための「けのび」の姿勢で大切なことは何ですか。', '["体を一直線に伸ばす","足を大きくバタつかせる","頭を水面から出す","腕を大きく広げる"]', 0, 2, 'けのびの姿勢で体を一直線に伸ばすことで、水の抵抗を最小限に抑え、効率よく進むことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の開脚前転で、回転を成功させるコツはどれですか。', '["回転の途中で足を広げる","最初から足を開いておく","手を使わずに回る","背中を反らせる"]', 0, 3, '前転の回転の勢いを利用して、重心が移動するタイミングで素早く足を開くのが開脚前転のポイントです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'スポーツにおいて「フェアプレー」とはどういう意味ですか。', '["ルールを守り、正々堂々と戦うこと","審判の判定に従わないこと","勝つためには手段を選ばないこと","相手を挑発すること"]', 0, 1, 'フェアプレーは、ルールを遵守し、相手を尊重して正々堂々と競技を行うスポーツマンシップの核心です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールのバタ足で、膝の使い方はどうあるべきですか。', '["力を抜き、自然に曲げ伸ばしする","膝をピンと伸ばし固定する","膝を大きく曲げて動かす","足首を固定して動かす"]', 0, 2, '膝を固めすぎると動きが硬くなります。足の付け根から動かし、膝の力を抜いてしなやかに動かすのがコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱運動で、着地時の正しい姿勢はどれですか。', '["膝を軽く曲げ、衝撃を吸収する","膝を伸ばしたまま着地する","かかとから強く着地する","すぐに走り出す"]', 0, 1, '着地時に膝を軽く曲げることで、足首や膝への衝撃を和らげ、怪我を防ぐことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒の「支持」の姿勢とは、どのような状態ですか。', '["腕で体を支え、鉄棒の上にいる状態","膝を曲げてぶら下がっている状態","鉄棒の下で回っている状態","鉄棒に背中を向けている状態"]', 0, 2, '支持は、腕を伸ばして鉄棒の上に体を支える姿勢を指します。多くの技の基本となる姿勢です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業で「バディ」を組む目的は何ですか。', '["互いの安全を確認し合うため","競争して泳ぐため","着替えを手伝うため","人数を数えるため"]', 0, 1, 'バディ制度は、ペアで互いの安全を監視し合うことで、溺水などの事故を未然に防ぐための重要な安全対策です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '後転で、頭がマットに当たってしまう主な原因は何ですか。', '["手の押しが弱い","勢いが強すぎる","足が閉じている","お尻が上がっている"]', 0, 2, '手でマットをしっかり押して体を浮かせないと、頭がマットに接触してしまいます。手の使い方が回転の鍵です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎの呼吸で、顔を上げるタイミングはいつですか。', '["腕で水をかき込むとき","足を蹴り出すとき","けのびをしているとき","足を閉じるとき"]', 0, 3, '腕で水をかき込み、体が浮き上がったタイミングで顔を上げ、息を吸うのが平泳ぎの正しいリズムです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の倒立で、重心はどこにあるのが理想ですか。', '["手のひらの中心（指の付け根付近）","手首の付け根","肘のあたり","足の先"]', 0, 3, '倒立では、重心を手のひらの中心付近に置くことで、安定した姿勢を保つことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'スポーツのマナーとして、練習用具の扱いで正しいのはどれですか。', '["大切に扱い、元の場所に戻す","壊れたら放置する","自分専用のものとして持ち帰る","他の人のものを勝手に使う"]', 0, 1, '用具を大切に扱うことは、スポーツに取り組む姿勢そのものです。次に使う人のために整理整頓を心がけましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールのストロークで、水をかく際の手の形はどうするのが良いですか。', '["指を揃えて軽く閉じる","指を大きく開く","拳を握る","手首を曲げる"]', 0, 2, '指を揃えて軽く閉じることで、手のひらで水をしっかり捉え、大きな推進力を得ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱で、踏み切り板を使う際の注意点はどれですか。', '["板の中央を両足で踏む","板の端を片足で踏む","板を使わずに跳ぶ","板の上で止まる"]', 0, 1, '踏み切り板の中央を両足で力強く踏むことで、反発力を最大限に活かし、高く跳ぶことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒の「懸垂逆上がり」で、最も重要な身体部位の使い方はどれですか。', '["腹筋を使って体を丸める","背筋を伸ばして反る","首を大きく回す","膝を外側に開く"]', 0, 3, '腹筋を使って体を鉄棒に引き寄せ、丸めることで、回転の勢いを維持しやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業で、飛び込みが禁止されている理由はどれですか。', '["頭部や頸部の怪我を防ぐため","水が汚れるため","泳ぐスピードが落ちるため","水着が脱げるため"]', 0, 1, 'プールでの飛び込みは、底に頭をぶつけたり、頸椎を損傷したりする重大な事故の危険があるため、厳禁です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の側転で、意識すべき目線はどこですか。', '["手をつく位置を見る","空を見る","足元を見る","目を閉じる"]', 0, 2, '側転では、手をつく位置をしっかり見ることで、体のバランスを保ち、真っ直ぐに回転することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎのキックで、足首の形はどうするのが正しいですか。', '["足首を外側に返す","足首を伸ばす","足首を内側に曲げる","足首を固定しない"]', 0, 3, '足首を外側に返す（つま先を外に向ける）ことで、足の裏で水をしっかり捉えて後ろに押すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '器械運動の練習で、最も優先すべきことは何ですか。', '["安全管理と準備運動","難しい技への挑戦","記録の更新","友達との競争"]', 0, 1, 'どんな運動でも、安全を確保し、準備運動を十分に行うことが、怪我をせず上達するための大前提です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールのローリングとは何ですか。', '["体を左右に傾ける動作","頭を上下させる動作","足を交互に動かす動作","息を止める動作"]', 0, 2, 'ローリングは、体を左右に少し傾けることで、腕を回しやすくし、呼吸をスムーズにするために必要な動作です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱で、手をつく位置として適切なのはどれですか。', '["跳び箱の奥側","跳び箱の手前側","跳び箱の横","跳び箱の上に乗る"]', 0, 2, '跳び箱の奥の方に手をつくことで、体を前方に押し出し、スムーズに跳び越すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒の「足掛け回り」で、回転を安定させるために必要なことは何ですか。', '["膝の裏をしっかり掛ける","腕を緩める","足を大きく開く","鉄棒から手を離す"]', 0, 2, '膝の裏を鉄棒に深く掛けることで、体が鉄棒から離れず、安定して回転することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業中、雷が鳴り始めたらどうすべきですか。', '["すぐにプールから上がる","あと一往復だけ泳ぐ","プールの底に潜る","そのまま泳ぎ続ける"]', 0, 1, '雷は水面を通じて感電する危険があるため、直ちにプールから上がり、安全な場所に避難しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の「ゆりかご」の目的は何ですか。', '["背中を丸める感覚を養う","足の筋力を鍛える","早く走れるようにする","柔軟性を競う"]', 0, 1, 'ゆりかごは、背中を丸めて前後へ揺れることで、前転や後転に必要な体の丸め方や重心移動の感覚を養います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎで、体が沈んでしまう原因として考えられるのはどれですか。', '["頭を上げすぎている","足を閉じている","腕を伸ばしている","息を吐いている"]', 0, 2, '頭を上げすぎると、シーソーの原理で腰や足が沈んでしまいます。目線は斜め下に向けるのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'スポーツのマナーとして、審判の判定に対する態度はどうあるべきですか。', '["判定を尊重する","納得がいかない場合は抗議する","無視する","審判を交代させる"]', 0, 1, '審判の判定は絶対です。判定に不服があっても、スポーツマンとして冷静に受け入れ、プレーを続けるのがマナーです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールのバタ足で、足の動かし方のコツはどれですか。', '["足の付け根から大きく動かす","膝から下だけを動かす","足首を固めて動かす","足を左右に開いて動かす"]', 0, 2, '足の付け根（股関節）から動かすことで、しなやかな動きになり、効率よく推進力を生み出せます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱で、開脚跳びの際に足を開くタイミングはいつですか。', '["手で跳び箱を押した直後","跳び箱に乗る前","着地した後","助走中"]', 0, 2, '手で跳び箱をしっかり押し、体が浮き上がったタイミングで足を開くことで、跳び箱に足が当たるのを防げます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒の「前回り」で、体が鉄棒から離れてしまう原因はどれですか。', '["腕が伸びきっている","鉄棒を握りしめている","お腹を鉄棒に近づけている","足が閉じている"]', 0, 3, '腕を伸ばしたままだと、体が鉄棒から離れてしまい、回転の勢いが止まってしまいます。腕を曲げて引き寄せることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業で、準備運動の際に行う「シャワー」の目的は何ですか。', '["体の汚れを落とし、水温に慣れる","水着を濡らす","友達と遊ぶ","髪を洗う"]', 0, 1, 'シャワーは衛生面だけでなく、冷たい水に体を少しずつ慣らして心臓への負担を減らす役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動で、後転の回転を助ける「手」の役割はどれですか。', '["マットを押して頭を浮かせる","バランスを取る","回転のスピードを落とす","マットの汚れを拭く"]', 0, 2, '後転では、耳の横についた手でマットを力強く押すことで、頭がマットに押し付けられるのを防ぎ、回転を助けます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎのキックで、最も水を押すのはどの部分ですか。', '["足の裏とすねの内側","つま先","かかと","足の甲"]', 0, 3, '平泳ぎのキックでは、足の裏とすねの内側で水を後ろに押し出すことで、推進力を得ています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '器械運動で、技ができない時に行うべきことは何ですか。', '["補助運動や段階的な練習をする","諦めて他の種目をする","無理をして何度も挑戦する","先生に怒られるまで待つ"]', 0, 1, 'できない技は、基礎となる動きや補助運動を反復し、段階的に練習することで上達を目指すのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールの呼吸で、息を吐くタイミングはいつですか。', '["顔が水の中にあるとき","顔を上げたとき","腕を回す前","泳ぎ終わった後"]', 0, 2, '顔が水の中にあるときに鼻や口から息を吐き出し、顔を上げた瞬間に素早く吸うのが正しい呼吸法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱で、踏み切り板の反発を活かすために必要なことは何ですか。', '["足の裏全体で力強く踏み切る","つま先だけで軽く跳ねる","板の端を避けて踏む","助走を止めてから跳ぶ"]', 0, 2, '足の裏全体で板の中央を踏むことで、反発力を効率よく全身に伝え、高く跳ぶことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '鉄棒運動で、安全のために最も大切なことは何ですか。', '["周囲の安全を確認してから行う","一番高い鉄棒を選ぶ","手袋をして行う","友達と同時に行う"]', 0, 1, '鉄棒は回転する種目が多く、周囲に人がいると衝突の危険があるため、必ず周囲の安全を確認してから行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳で、足がつった時の対処法として適切なのはどれですか。', '["落ち着いて水中で足を伸ばす","パニックになって暴れる","そのまま泳ぎ続ける","息を止めて潜る"]', 0, 1, '足がつった時はパニックにならず、落ち着いて足を伸ばし、周囲に助けを求めましょう。無理な動作は禁物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'マット運動の倒立で、肘はどうあるべきですか。', '["しっかり伸ばす","軽く曲げる","大きく外側に広げる","体に密着させる"]', 0, 2, '倒立では、肘をしっかり伸ばして体重を支えることで、安定した姿勢を維持することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '平泳ぎの泳法で、腕の動きの範囲はどこまでですか。', '["肩のラインまで","腰のあたりまで","足の先まで","頭の上まで"]', 0, 3, '平泳ぎの腕の動きは、肩のラインよりも後ろに行き過ぎないようにするのが、水の抵抗を減らすコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'スポーツにおいて、チームメイトへの声かけで大切なことは何ですか。', '["励ましや前向きな言葉","ミスを責める言葉","指示を無視する言葉","無言でプレーする"]', 0, 1, 'チームスポーツでは、互いに声を掛け合い、励まし合うことで士気が高まり、良いプレーにつながります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', 'クロールの泳法で、頭の位置として適切なのはどれですか。', '["水面が頭の真ん中あたりに来る位置","頭を完全に水面から出す","頭を完全に水中に沈める","頭を左右に大きく振る"]', 0, 2, '水面が頭の真ん中を通るようにすると、抵抗が少なく、呼吸もしやすい理想的な姿勢になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '跳び箱で、着地が不安定になる主な原因は何ですか。', '["目線が下を向いている","助走が速すぎる","手をしっかりついている","膝を曲げている"]', 0, 2, '着地時に目線を下に向けると、バランスを崩しやすくなります。遠くを見るようにすると安定します。', NULL);
