INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'pe', '水泳の授業で、最も重要な安全ルールはどれですか。', '["先生の指示を必ず守る","速く泳ぐ練習をする","ゴーグルを二重にする","友達と競争する"]', 0, 1, '水泳は危険が伴うため、先生の指示やルールを厳守することが、自分と仲間の命を守るために最も大切です。', NULL);
