INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バドミントンで、シャトルがネットに触れて相手コートに入った場合、どうなるか。', '["インプレー（続行）","レット（やり直し）","失点","フォールト"]', 0, 2, 'バドミントンでは、ネットに触れても相手コートに入ればそのままプレーを続行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', '柔道の試合開始時と終了時に行う礼の作法として正しいものはどれか。', '["立礼","座礼","黙想","握手"]', 0, 1, '柔道の試合では、畳の上で立ったまま行う「立礼」が基本です。礼に始まり礼に終わります。', NULL);
