INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バスケットボールで、シュートが外れた後にボールを確保することを何というか。', '["リバウンド","スティール","ブロック","パス"]', 0, 1, '外れたシュートボールを確保するプレーをリバウンドと言います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バレーボールで、オーバーハンドパスでボールを扱う際に注意すべきことは何か。', '["ホールディング","オーバーネット","タッチネット","ドリブル"]', 0, 3, 'ボールを長く持ちすぎるとホールディングという反則になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'サッカーで、ペナルティエリア内で守備側が反則をした場合に与えられるものはどれか。', '["ペナルティキック","コーナーキック","フリーキック","スローイン"]', 0, 1, 'ペナルティエリア内での反則は、ペナルティキック（PK）となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', '卓球で、ボールが台の角に当たった場合どうなるか。', '["インプレー","失点","やり直し","ノーカウント"]', 0, 2, '卓球では台の角（エッジ）も台の一部とみなされ、インとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バドミントンで、スマッシュの主な目的は何か。', '["得点すること","ラリーを続けること","相手を疲れさせること","時間を稼ぐこと"]', 0, 1, 'スマッシュは、相手が返せないような速い球を打ち込み、得点を狙う攻撃的なショットです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', '柔道で、相手を倒して抑え込む技を何というか。', '["抑え込み技","投げ技","絞め技","関節技"]', 0, 1, '相手を畳に押さえつける技を抑え込み技と言います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', '剣道で、面を打つ際に必要なことは何か。', '["気・剣・体の一致","力任せに打つ","スピードのみ","相手を避ける"]', 0, 3, '気合、竹刀の動き、踏み込みが同時に行われる「気・剣・体の一致」が有効打突の条件です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バスケットボールで、試合時間は何クォーター制か。', '["4クォーター","2クォーター","3クォーター","5クォーター"]', 0, 2, 'バスケットボールは通常4つのクォーターに分けて試合を行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'バレーボールで、サーブを打つ順番は何で決まるか。', '["ローテーションの順","身長順","年齢順","じゃんけん"]', 0, 2, 'ローテーションの順序に従って、決められた選手が順番にサーブを打ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', 'サッカーで、試合開始時にボールを中央に置くことを何というか。', '["キックオフ","ゴールキック","コーナーキック","スローイン"]', 0, 1, '試合の開始や得点後の再開は、センターサークルからのキックオフで行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'pe', '卓球で、ラケットの持ち方として一般的なものはどれか。', '["シェークハンド","ペンホルダー","両方ある","どちらでもない"]', 2, 1, '卓球のラケットの持ち方には、シェークハンドとペンホルダーの2種類が一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる、心身の急激な発達を何というか。', '["二次性徴","第一次性徴","成熟期","成長期"]', 0, 1, '思春期に現れる身体の性的な特徴の発達を二次性徴と呼びます。第一次性徴は出生時に備わっている性器の特徴を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '男子の二次性徴として誤っているものはどれか。', '["声変わりが始まる","精巣が発達する","初経が起こる","筋肉が発達する"]', 2, 1, '初経は女子の二次性徴の一つです。男子には起こりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '女子の二次性徴として適切なものはどれか。', '["声変わり","乳房のふくらみ","ひげが生える","喉仏が目立つ"]', 1, 1, '乳房のふくらみは女子の二次性徴の代表的な身体変化です。他の選択肢はすべて男子の特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期の心の変化として適切なものはどれか。', '["感情が常に安定する","自立心が芽生え、大人への反発を感じることもある","他者との関わりを完全に避けるようになる","身体の変化に全く気づかなくなる"]', 1, 2, '思春期は自立心が強まり、親や大人に対して反発心を持つことがありますが、これは精神的に成長している証拠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '生殖機能が成熟し、妊娠が可能になるのはどの時期か。', '["乳幼児期","思春期","成人期","老年期"]', 1, 1, '思春期は、生殖器が発達し、精子や卵子が作られるようになり、生殖機能が成熟する時期です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '呼吸によって体内に取り入れられる重要な気体は何か。', '["二酸化炭素","窒素","酸素","ヘリウム"]', 2, 1, '呼吸は、酸素を取り入れ、体内でできた二酸化炭素を排出する働きです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '血液を全身に送り出すポンプの役割をしている臓器はどれか。', '["肺","心臓","胃","肝臓"]', 1, 1, '心臓は筋肉でできており、収縮と拡張を繰り返すことで血液を全身に循環させるポンプの役割をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '運動をすると心拍数が増えるのはなぜか。', '["心臓を休ませるため","筋肉に酸素をより多く送るため","体温を下げるため","呼吸を止めるため"]', 1, 2, '運動時には筋肉が多くの酸素を必要とするため、心臓が早く動いて血液の循環を速め、酸素を供給しようとします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「R」が指すものはどれか。', '["Rest（安静）","Run（走る）","Rise（上げる）","Read（読む）"]', 0, 1, 'RICE処置のRはRest（安静）です。患部を動かさないことで損傷の拡大を防ぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「I」が指すものはどれか。', '["Injury（けが）","Ice（冷却）","Important（重要）","Increase（増加）"]', 1, 1, 'RICE処置のIはIce（冷却）です。患部を冷やすことで痛みや腫れを抑えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「C」が指すものはどれか。', '["Care（ケア）","Cold（冷たい）","Compression（圧迫）","Check（確認）"]', 2, 1, 'RICE処置のCはCompression（圧迫）です。包帯などで患部を圧迫し、腫れを防ぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「E」が指すものはどれか。', '["Elevation（挙上）","Energy（エネルギー）","Exercise（運動）","Exit（出口）"]', 0, 1, 'RICE処置のEはElevation（挙上）です。患部を心臓より高い位置に保つことで、腫れを抑えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に分泌が活発になる、性的な発達を促す物質を何というか。', '["消化酵素","性ホルモン","ビタミン","成長ホルモン"]', 1, 2, '性ホルモンは、二次性徴や生殖機能の発達をコントロールする重要な物質です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '血液が肺で受け取るものはどれか。', '["二酸化炭素","栄養分","酸素","老廃物"]', 2, 2, '肺では、血液中の二酸化炭素を排出し、代わりに酸素を取り込んで全身へ送ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '運動不足が続くと、心臓や肺の働きはどうなるか。', '["強くなる","弱くなる","変わらない","大きくなる"]', 1, 1, '運動をしないと心肺機能は低下します。適度な運動を継続することが心肺機能を高めるために重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '捻挫をした直後の応急手当として最も適切なものはどれか。', '["すぐにお風呂に入る","患部を温める","RICE処置を行う","我慢して運動を続ける"]', 2, 1, '捻挫などのけがをした際は、すぐにRICE処置を行い、炎症や腫れを最小限に抑えることが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期の身体的成長には個人差がある。このことについて正しい考え方はどれか。', '["全員同じ時期に成長する","成長の時期や速さには個人差があるのが普通である","成長が遅いのは病気である","成長が早いほど良い"]', 1, 2, '思春期の成長には個人差があり、時期や速さが人によって異なるのは自然なことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '呼吸器系に含まれる臓器はどれか。', '["心臓","胃","肺","腎臓"]', 2, 1, '肺は呼吸器系の一部で、空気中の酸素を取り込み、二酸化炭素を排出する役割を担っています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '血液を循環させるための「循環器系」に含まれるのはどれか。', '["肺と気管","心臓と血管","胃と腸","脳と神経"]', 1, 1, '循環器系は心臓と血管からなり、血液を全身に巡らせることで酸素や栄養を運びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「Ice（冷却）」を行う目的はどれか。', '["筋肉を鍛えるため","患部の痛みや腫れを抑えるため","血流を促進するため","骨を強くするため"]', 1, 2, '冷却することで血管が収縮し、炎症の拡大や腫れ、痛みを抑える効果があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる心理的な変化として、適切なものはどれか。', '["親への依存が強まる","異性に対して関心が高まる","友達との関係を無視するようになる","自分の感情がわからなくなる"]', 1, 2, '思春期には異性への関心が高まることが一般的です。これは心身が成長している証拠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '運動を継続すると、安静時の心拍数はどうなる傾向があるか。', '["増える","減る","変わらない","不規則になる"]', 1, 3, '継続的な運動で心臓のポンプ機能が強化されると、一度の拍動で送り出せる血液量が増えるため、安静時の心拍数は減る傾向にあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'けがをしたとき、患部を「挙上」する主な理由は何か。', '["患部を温めるため","血液の流れを良くするため","腫れを抑えるため","痛みを忘れるため"]', 2, 2, '患部を心臓より高くすることで、血液が患部に溜まるのを防ぎ、腫れを抑えることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期の健康管理において、最も大切なことは何か。', '["無理なダイエットをする","睡眠を削って勉強する","バランスの良い食事と適度な運動","サプリメントに頼る"]', 2, 1, '成長期には栄養が必要であり、運動と休養のバランスが健康な体を作るために不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '心臓から送り出された血液が通る管を何というか。', '["神経","血管","気管","リンパ管"]', 1, 1, '血管は血液が流れる管であり、動脈、静脈、毛細血管があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「圧迫」で注意すべき点はどれか。', '["強く締めすぎて血流を止めないこと","包帯を巻かないこと","患部を動かし続けること","氷で冷やさないこと"]', 0, 2, '圧迫は腫れを防ぐために行いますが、強く締めすぎると血流障害を起こすため注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる「初経」とは何か。', '["初めての運動","初めての月経","初めての成長痛","初めての声変わり"]', 1, 1, '初経は、思春期に初めて起こる月経のことです。生殖機能が成熟し始めたサインの一つです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '呼吸の回数が増えるのはどのような時か。', '["睡眠中","リラックスしている時","激しい運動をしている時","座っている時"]', 2, 1, '運動中は筋肉がより多くの酸素を必要とするため、呼吸の回数が増えて酸素を取り込もうとします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に自分の体に対して抱く悩みとして、一般的なものはどれか。', '["成長が早すぎることや遅すぎることへの不安","体力がつきすぎること","身長が伸びすぎること","病気にかかりやすくなること"]', 0, 2, '成長のスピードには個人差があるため、周囲と比べて不安を感じることは思春期によくある悩みです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'けがをした直後に「温める」のが良くない理由は何か。', '["痛みが強くなるから","血流が良くなりすぎて腫れがひどくなるから","患部が冷えるから","筋肉が固まるから"]', 1, 2, 'けが直後の患部は炎症を起こしています。温めると血流が促進され、かえって腫れや炎症が悪化してしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '心臓の拍動によって血管にかかる圧力を何というか。', '["体温","血圧","脈拍","呼吸数"]', 1, 2, '血圧は心臓が血液を送り出す力によって血管壁にかかる圧力のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に分泌される性ホルモンは、どこで主に作られるか。', '["心臓","肺","生殖器","胃"]', 2, 2, '性ホルモンは、男子なら精巣、女子なら卵巣などの生殖器から分泌されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「安静」の目的は何か。', '["患部を動かして早く治すため","損傷の拡大を防ぐため","筋肉をリラックスさせるため","痛みを忘れるため"]', 1, 2, '安静にすることで、患部への負担を減らし、けがの悪化を防ぐことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる心の変化として、正しいものはどれか。', '["すべての人に同じ強さで起こる","個人差があり、悩み方も様々である","全く悩むことはない","大人にすべて任せれば解決する"]', 1, 1, '思春期の心の変化は人それぞれであり、悩み方も多様です。自分一人で抱え込まず相談することも大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '血液が全身を巡ることで運ばれるものはどれか。', '["酸素と栄養分","二酸化炭素のみ","老廃物のみ","光"]', 0, 1, '血液は、細胞に酸素と栄養を届け、細胞から出た二酸化炭素や老廃物を回収する役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置は、どのようなけがに有効か。', '["骨折や捻挫などの外傷","風邪","腹痛","頭痛"]', 0, 1, 'RICE処置は、捻挫、打撲、肉離れなどのスポーツによる外傷の応急手当として非常に有効です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に男子に起こる身体的変化はどれか。', '["月経の開始","骨盤の広がり","精巣の発達と精子の形成","乳房の発達"]', 2, 1, '精巣の発達と精子の形成は男子の二次性徴であり、生殖機能が成熟する過程です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '呼吸の働きを助ける筋肉はどれか。', '["横隔膜","胃","心臓","肝臓"]', 0, 3, '横隔膜が上下することで胸腔の大きさが変わり、肺に空気が入ったり出たりします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「Ice」で、氷を直接肌に当てない方が良い理由は何か。', '["凍傷を防ぐため","氷が溶けやすいため","冷えすぎないようにするため","痛みを増やすため"]', 0, 2, '氷を直接肌に当てると凍傷になる恐れがあるため、タオルなどで包んでから当てるのが適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる心の変化をどう捉えるべきか。', '["異常なことなので隠すべき","成長の過程で起こる自然なこと","大人になれば勝手に治る","友達と比べるべきではない"]', 1, 1, '思春期の揺れ動く心は、大人になるための大切な成長過程です。自分を肯定的に捉えることが大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '運動時に心拍数が増えるのは、何が原因か。', '["酸素の需要が増えるから","心臓が疲れるから","血液が減るから","体温が下がるから"]', 0, 2, '運動で筋肉が活発に動くと、より多くの酸素が必要になるため、心臓が早く動いて酸素を供給します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「C（圧迫）」を長時間行いすぎるとどうなるか。', '["血流が悪くなる","腫れが早く引く","痛みが消える","骨が強くなる"]', 0, 2, '圧迫を長時間強く行いすぎると血流が遮断され、組織に悪影響を与える可能性があるため、適度な圧迫が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期の身体的発達において、最も影響を与えるのは何か。', '["性ホルモン","運動量","睡眠時間","勉強量"]', 0, 2, '二次性徴などの身体的変化は、主に性ホルモンの分泌によって引き起こされます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '肺で酸素と二酸化炭素の交換が行われる場所はどこか。', '["気管支","肺胞","心臓","血管"]', 1, 3, '肺の中にある小さな袋状の「肺胞」で、血液中の二酸化炭素と空気中の酸素の交換が行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「E（挙上）」は、どの程度の高さが目安か。', '["心臓より高い位置","地面と同じ高さ","心臓より低い位置","頭と同じ高さ"]', 0, 2, '患部を心臓より高くすることで、重力を利用して患部に血液が溜まるのを防ぎ、腫れを抑えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる「声変わり」はなぜ起こるか。', '["喉仏が発達し、声帯が大きくなるから","大声を出すから","風邪をひくから","筋肉が落ちるから"]', 0, 2, '性ホルモンの影響で喉仏が発達し、声帯が厚く長くなることで、声が低くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '運動をすると呼吸が深くなるのはなぜか。', '["肺を大きくするため","一度に多くの酸素を取り込むため","肺を休ませるため","体温を上げるため"]', 1, 2, '運動時は酸素を大量に消費するため、呼吸を深くして一度に取り込む空気の量を増やします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「I（冷却）」は、いつまで行うのが良いか。', '["ずっと行う","炎症が治まるまで（通常48〜72時間程度）","1時間だけ","痛みが消えるまで"]', 1, 3, '冷却は炎症が強い初期（48〜72時間）に行うのが効果的です。長期間の冷却は逆効果になることもあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に異性への関心が高まるのは、何の影響か。', '["性ホルモンの分泌","テレビの影響","友達の影響","勉強の影響"]', 0, 2, '性ホルモンの分泌が活発になることで、心身が成熟し、異性への関心が高まるのは自然なことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '心臓の働きを維持するために大切なことは何か。', '["激しい運動を毎日続ける","適度な運動とバランスの良い食事","睡眠を全く取らない","甘いものばかり食べる"]', 1, 1, '心臓も筋肉なので、適度な運動と栄養バランスの取れた食事が健康維持に不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「R（安静）」において、やってはいけないことはどれか。', '["患部を動かす","患部を固定する","無理をしない","安静にする"]', 0, 1, 'けがをした直後に患部を動かすと、損傷が悪化するため、安静にすることが最も重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に女子に起こる身体的変化はどれか。', '["声変わり","乳房のふくらみと骨盤の発達","ひげが生える","喉仏が目立つ"]', 1, 1, '女子の二次性徴には、乳房のふくらみや骨盤の発達、月経の開始などがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '血液が全身を一周するのに必要な時間はどのくらいか。', '["約1分","約1時間","約1日","約1秒"]', 0, 3, '心臓のポンプ機能により、血液は全身を約1分で一周して循環しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「C（圧迫）」で使うものはどれか。', '["包帯やテーピング","氷","枕","温かいタオル"]', 0, 2, '圧迫には包帯やテーピングを用い、患部を適度に締め付けて腫れを抑えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に起こる心の変化をどう扱うのが良いか。', '["一人で悩む","信頼できる大人や友人に相談する","無視して忘れる","誰にも言わない"]', 1, 1, '悩みがあるときは、信頼できる人に相談することで、気持ちが整理され、前向きになれることがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '呼吸によって体外に排出されるものはどれか。', '["酸素","二酸化炭素","栄養分","水"]', 1, 1, '呼吸は、体内で作られた二酸化炭素を肺から体外へ排出する働きもしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「E（挙上）」を行う際、注意すべきことは何か。', '["患部を心臓より高く保つこと","患部を地面につけること","患部を激しく動かすこと","患部を冷やさないこと"]', 0, 2, '挙上は、血液が患部に溜まらないように心臓より高く保つことが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '思春期に身長が急激に伸びることを何というか。', '["成長スパート","成長停止","成長停滞","成長加速"]', 0, 2, '思春期には身長が急激に伸びる時期があり、これを成長スパートと呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', '心臓の拍動を測ることでわかるものはどれか。', '["脈拍数","体温","身長","体重"]', 0, 1, '脈拍は、心臓の拍動が血管に伝わったもので、これを測ることで心臓の動きを知ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'pe', 'RICE処置の「I（冷却）」で、氷嚢がない場合はどうすればよいか。', '["氷をビニール袋に入れる","冷たい水で濡らしたタオルを使う","何もしない","温かいタオルを使う"]', 0, 2, '氷嚢がなくても、ビニール袋に氷と少量の水を入れて氷嚢代わりにすることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材のうち、一般的に成長が早く、建築材料として広く使われるのはどちらか。', '["針葉樹","広葉樹","竹","草本類"]', 0, 1, '針葉樹はまっすぐ伸びる性質があり、成長が早いため、柱や梁などの建築材料として多く利用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '次のうち、広葉樹に分類される木材はどれか。', '["スギ","ヒノキ","マツ","ナラ"]', 3, 1, 'スギ、ヒノキ、マツは針葉樹です。ナラは広葉樹で、硬く重いため家具やフローリングによく使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を切り出す際、木材の無駄を少なくし、効率よく材料をとることを何というか。', '["木取り","接合","研磨","墨付け"]', 0, 1, '木取りとは、木材の性質や大きさを考慮して、効率的に部材を切り出す計画を立てることです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '直角の確認や、長さの測定、直線のけがきに使用するL字型の道具はどれか。', '["さしがね","のこぎり","かんな","げんのう"]', 0, 1, 'さしがねは、直角を測るだけでなく、寸法の測定や曲線のけがきなど、木工で最も重要な道具の一つです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、体の組織（筋肉や皮膚など）を作る主な材料になるものはどれか。', '["炭水化物","脂質","タンパク質","ビタミン"]', 2, 1, 'タンパク質は、体を作る材料になる栄養素です。炭水化物や脂質は主にエネルギー源となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群において、第1群に分類される食品の主な役割は何か。', '["骨や歯を作る","エネルギーになる","体の調子を整える","筋肉を作る"]', 0, 2, '第1群は魚、肉、卵、大豆製品で、主にタンパク質を供給し、体を作る材料になります。骨や歯を作るのは第2群のカルシウム源です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'のこぎりで木材を切断する際、力を入れるべき方向はどれか。', '["押すとき","引くとき","上下に動かすとき","斜めに動かすとき"]', 1, 1, '日本ののこぎりは、引くときに切れるように刃がついています。押すときは力を抜くのがコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の表面を平らに削り、なめらかにする道具はどれか。', '["かんな","のみ","やすり","きり"]', 0, 1, 'かんなは、木材の表面を薄く削り取って平滑に仕上げるための伝統的な道具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材同士を接合する方法のうち、釘を使わずに木材の凹凸を組み合わせてつなぐ技法を何というか。', '["接着","継手・仕口","ねじ止め","溶接"]', 1, 2, '継手（つぎて）や仕口（しぐち）は、木材を加工して凹凸を作り、釘を使わずに接合する伝統的な木工技術です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、エネルギー源として最も効率よく使われるものはどれか。', '["炭水化物","タンパク質","ビタミン","ミネラル"]', 0, 1, '炭水化物は体内でブドウ糖に分解され、脳や体を動かす主要なエネルギー源として利用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、緑黄色野菜が分類されるのは何群か。', '["第1群","第3群","第5群","第6群"]', 1, 2, '第3群は緑黄色野菜です。ビタミンやミネラルを豊富に含み、体の調子を整える役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の「年輪」ができる主な理由は何か。', '["季節による成長速度の違い","日光の当たり方の違い","木の種類の違い","水分量の違い"]', 0, 2, '春から夏にかけては成長が早く細胞が大きくなり、秋から冬は成長が遅いため、その差が年輪となって現れます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を加工する際、最初に寸法を書き込む作業を何というか。', '["けがき","切断","組み立て","仕上げ"]', 0, 1, 'けがきは、材料に寸法や加工線を書き込む作業で、正確な製作のための最も重要な工程です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '広葉樹の特徴として正しいものはどれか。', '["組織が緻密で硬い","成長が非常に早い","真っ直ぐな木が多い","加工が容易である"]', 0, 2, '広葉樹は組織が緻密で硬く、重いものが多いです。針葉樹に比べて成長に時間がかかるものが多いです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素に含まれないものはどれか。', '["炭水化物","食物繊維","脂質","ビタミン"]', 1, 2, '五大栄養素は、炭水化物、脂質、タンパク質、ビタミン、ミネラルです。食物繊維は重要ですが栄養素には含まれません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群において、第6群の食品は何か。', '["穀類","油脂","果物","乳製品"]', 2, 2, '第6群は果物です。ビタミンCやカリウムなどの供給源として重要な役割を果たします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'のこぎりの刃の目が細かいもの（横挽き用など）は、どのような切断に適しているか。', '["木目に沿って切る","木目を横切って切る","丸太を割る","厚い板を切り出す"]', 1, 2, '横挽き用ののこぎりは、木目を断ち切るために刃が細かく作られています。縦挽き用は木目に沿って切るのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'かんなの刃の調整において、刃先を出す量はどの程度が適切か。', '["できるだけ多く出す","紙一枚分程度","刃が見えないようにする","1cm程度"]', 1, 2, 'かんなは薄く削るための道具なので、刃はほんの少し（紙一枚分程度）だけ出すのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'タンパク質を多く含む食品群はどれか。', '["第1群","第2群","第3群","第4群"]', 0, 1, '第1群は肉、魚、卵、大豆製品で、体を作るタンパク質の主な供給源です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を接合する際、釘を打つ前にあらかじめ開けておく小さな穴を何というか。', '["下穴","貫通穴","ダボ穴","埋め木穴"]', 0, 1, '下穴をあけることで、木材が割れるのを防ぎ、釘を正確に打ち込むことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、エネルギー源となる食品は第何群か。', '["第1群と第2群","第3群と第4群","第4群と第5群","第5群と第6群"]', 2, 2, '第4群は穀類・いも類（炭水化物）、第5群は油脂（脂質）で、どちらもエネルギー源となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の「木目」に沿って切断する際に使うのこぎりはどれか。', '["縦挽き用","横挽き用","胴付きのこ","糸のこ"]', 0, 2, '縦挽き用ののこぎりは、木目に沿って繊維を切り裂くように刃が設計されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、体の機能を調節する役割を持つものはどれか。', '["ビタミンとミネラル","炭水化物と脂質","タンパク質と脂質","炭水化物とタンパク質"]', 0, 1, 'ビタミンとミネラルは、体の調子を整え、代謝をスムーズにする働きがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の乾燥が不十分な場合、どのような問題が起こるか。', '["腐りやすくなる","強度が上がる","加工しやすくなる","香りが良くなる"]', 0, 2, '木材中の水分が多いと、カビや腐朽菌が発生しやすくなり、木材が腐る原因になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'さしがねの裏側にある目盛りを使って計算できるものはどれか。', '["円の面積","角材の対角線","三角形の面積","重さ"]', 1, 3, 'さしがねの裏面には「角目」という目盛りがあり、これを使うと丸太から切り出せる最大の角材の寸法が分かります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を接合する際、接着剤を塗った後に必要な作業はどれか。', '["すぐに動かす","クランプ等で固定する","水で濡らす","火で炙る"]', 1, 1, '接着剤が乾くまで圧力をかけて固定することで、隙間なく強力に接合することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、第2群の主な役割は何か。', '["骨や歯を作る","エネルギーになる","体を作る","調子を整える"]', 0, 2, '第2群は牛乳、乳製品、海藻、小魚で、カルシウムを多く含み、骨や歯を作る材料になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の加工において、のこぎりで切った後のざらざらした面を平らにする道具はどれか。', '["やすり","のみ","きり","げんのう"]', 0, 1, 'やすりは、木材の表面を削ってなめらかにしたり、角を丸めたりするのに適しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のひとつ「ミネラル」の働きとして適切なものはどれか。', '["エネルギーになる","骨や歯の構成成分になる","筋肉の主な材料になる","皮膚の保護をする"]', 1, 2, 'ミネラル（カルシウムや鉄など）は、骨や歯を作ったり、体の機能を維持したりする重要な役割があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の「木表（きおもて）」とは、どの面を指すか。', '["樹皮に近い外側の面","中心に近い内側の面","切り口の面","節がある面"]', 0, 3, '木表は樹皮に近い側、木裏は中心に近い側を指します。木表の方が乾燥による反りが少ないとされています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群において、ビタミン類を多く含むのは第何群か。', '["第1群と第2群","第3群と第6群","第4群と第5群","第1群と第4群"]', 1, 2, '第3群（緑黄色野菜）と第6群（果物）は、ビタミンやミネラルを豊富に含み、体の調子を整えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を接合する際、釘の打ち方として正しいものはどれか。', '["まっすぐ垂直に打つ","斜めに打つと強くなる","一度抜いてから打ち直す","端ギリギリに打つ"]', 1, 2, '釘を少し斜めに打ち込む（斜め打ち）ことで、抜けにくくなり、接合の強度が上がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'かんながけをする際、木材のどの方向に削るのが良いか。', '["木目に逆らわない方向","木目に逆らう方向","斜め方向","どこでも良い"]', 0, 2, '木目に逆らって削ると、木材がささくれたり、きれいに仕上がらなかったりします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、脂質の主な役割はどれか。', '["体の構成成分とエネルギー源","骨を強くする","免疫力を高める","消化を助ける"]', 0, 2, '脂質はエネルギー源になるほか、細胞膜やホルモンの構成成分としても重要な役割を果たします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の加工で、穴をあける道具はどれか。', '["きり","かんな","のこぎり","さしがね"]', 0, 1, 'きりは、木材に小さな穴をあけるための道具です。大きな穴はドリルなどを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、エネルギー源となる食品をすべて選ぶとどれか。', '["第1群・第2群","第3群・第6群","第4群・第5群","第1群・第3群"]', 2, 2, '第4群（穀類・いも類）と第5群（油脂）は、主にエネルギー源として利用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の性質として、誤っているものはどれか。', '["熱を伝えにくい","湿気を調節する","金属より軽い","水に完全に溶ける"]', 3, 1, '木材は水に浮く性質があり、水に溶けることはありません。断熱性や調湿性に優れています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'のこぎりの刃の「あさり」とは何か。', '["刃を左右に交互に広げたもの","刃の鋭さ","刃の長さ","持ち手の形"]', 0, 3, 'あさりは、切り幅を刃の厚みより広くすることで、のこぎりが木材に挟まるのを防ぐ工夫です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'タンパク質が不足するとどのような影響があるか。', '["筋肉が減る","太りやすくなる","視力が落ちる","眠れなくなる"]', 0, 2, 'タンパク質は筋肉や臓器を作る材料なので、不足すると筋肉量が減り、体力が低下します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の「節（ふし）」とは何か。', '["枝が幹に取り込まれた跡","年輪の模様","木材の割れ目","樹皮の模様"]', 0, 1, '節は、木の枝が幹の成長とともに内部に取り込まれた部分です。硬く、加工しにくいことがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'さしがねを使って直角をけがく際、最も重要なことは何か。', '["正確に合わせる","強く押し付ける","何度もなぞる","定規を使わない"]', 0, 1, '正確な木工には、けがきの段階で正確に線を引くことが不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、体温を保つ役割があるものはどれか。', '["脂質","ビタミン","ミネラル","タンパク質"]', 0, 2, '脂質はエネルギー源として体温を保つ役割があります。また、内臓を守るクッションの役割もします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、第1群に含まれないものはどれか。', '["肉","魚","卵","米"]', 3, 1, '米は第4群（穀類）です。第1群は肉、魚、卵、大豆製品などのタンパク質源です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を接合する際に使われる「ダボ」とは何か。', '["木製の小さな棒","金属の釘","接着剤の別名","固定用金具"]', 0, 2, 'ダボは、木材にあけた穴に差し込んで接合を補助する小さな木製の棒です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'のこぎりを使用する際の安全対策として正しいものはどれか。', '["切断中は手袋をしない","刃を自分に向ける","無理な力を入れる","足元に物を置く"]', 0, 1, '手袋は刃に巻き込まれる危険があるため、のこぎり作業では素手が基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '広葉樹の例として正しいものはどれか。', '["ケヤキ","スギ","ヒノキ","マツ"]', 0, 1, 'ケヤキは広葉樹で、木目が美しく硬いため家具や建具によく使われます。他はすべて針葉樹です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のバランスを整える食事を何というか。', '["栄養バランスの良い食事","高カロリー食","ファストフード","単品料理"]', 0, 1, '五大栄養素を過不足なく摂取することが、健康を維持するために最も重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群において、第5群の食品は何か。', '["油脂","穀類","野菜","果物"]', 0, 2, '第5群は油脂で、エネルギー源として重要な役割を果たします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材を加工する際、かんながけのコツは何か。', '["一定の力で引く","力を入れて押し付ける","斜めに削る","一度に深く削る"]', 0, 2, 'かんなは、一定の力でスムーズに引くことで、表面をきれいに仕上げることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の「木裏」の特徴はどれか。', '["反りやすい","硬い","節がない","色が白い"]', 0, 3, '木裏は中心に近い側で、乾燥すると外側に反る性質があるため、木表を外側にして使うのが一般的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素のうち、体の調子を整える栄養素はどれか。', '["ビタミン・ミネラル","炭水化物・脂質","タンパク質・炭水化物","脂質・タンパク質"]', 0, 1, 'ビタミンとミネラルは、体の機能を調節し、健康を維持するために不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'のこぎりで切断する際、切り始めをスムーズにする方法はどれか。', '["親指の爪をガイドにする","最初から強く引く","斜めに強く押す","何もせず切る"]', 0, 2, '親指の爪を刃の横に添えてガイドにすると、切り始めが安定し、正確に切ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、第4群に含まれるものはどれか。', '["米・パン","肉","牛乳","みかん"]', 0, 1, '第4群は穀類・いも類で、エネルギー源となる炭水化物を多く含みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の接合で、釘を使わず木材同士をはめ込む技法を何というか。', '["継手・仕口","ねじ止め","ボルト止め","接着剤のみ"]', 0, 2, '継手・仕口は、木材を加工して凹凸を作り、互いにはめ込むことで接合する伝統的な方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の乾燥方法として、自然乾燥以外にあるものはどれか。', '["人工乾燥","冷凍乾燥","化学乾燥","油乾燥"]', 0, 2, '人工乾燥は、乾燥室で温度や湿度を管理して短期間で効率よく木材を乾燥させる方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '五大栄養素の「ミネラル」が不足するとどうなるか。', '["骨が弱くなる","太りやすくなる","視力が落ちる","眠れなくなる"]', 0, 2, 'カルシウムなどのミネラルが不足すると、骨が弱くなる（骨粗鬆症など）原因になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '木材の加工において、のこぎりの刃を長持ちさせる方法はどれか。', '["無理な力をかけない","水で冷やす","油を塗る","火で炙る"]', 0, 1, '無理な力をかけると刃が歪んだり欠けたりします。引く力を利用して軽く切るのがコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', '六つの基礎食品群で、第3群の食品はどれか。', '["緑黄色野菜","魚","米","バター"]', 0, 1, '第3群は緑黄色野菜で、ビタミンやミネラルを多く含みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_mid', 'tech_home', 'かんなの刃が木に食い込みすぎるときはどうすべきか。', '["刃を少し引っ込める","刃をさらに出す","力を強くする","角度を変える"]', 0, 2, '食い込みすぎる場合は、刃の出しすぎが原因です。少し引っ込めることで、薄く削れるようになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の性質として、叩くと薄く広がる性質を何というか。', '["展性","延性","導電性","光沢"]', 0, 1, '金属を叩いて薄く広がる性質を展性、引っ張って細く伸びる性質を延性と呼びます。混同しやすいので注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属を引っ張ると細く伸びる性質を何というか。', '["展性","延性","導電性","熱伝導性"]', 1, 1, '金属を引っ張って線状に伸ばすことができる性質を延性といいます。展性とセットで覚えましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックのうち、加熱すると柔らかくなり、冷やすと固まる性質を持つものを何というか。', '["熱可塑性プラスチック","熱硬化性プラスチック","合成ゴム","繊維"]', 0, 1, '熱可塑性プラスチックは何度でも加熱して成形可能です。一方、熱硬化性は一度固まると再加熱しても溶けません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '熱硬化性プラスチックの説明として正しいものはどれか。', '["加熱すると何度でも溶ける","加熱すると硬くなる","一度固まると再加熱しても溶けない","リサイクルが非常に容易である"]', 2, 2, '熱硬化性プラスチックは、加熱して成形する際に化学変化を起こし、一度固まると再び加熱しても溶けません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '等角図において、3つの軸は何度で交わるか。', '["90度","120度","45度","60度"]', 1, 2, '等角図は、3つの軸を120度ずつに配置して立体を描く投影法です。立体の形がわかりやすいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'キャビネット図で、奥行き方向の線は実際の長さの何倍で描くか。', '["1倍","2分の1倍","3分の1倍","4分の1倍"]', 1, 2, 'キャビネット図は、奥行きを斜め45度に描き、実際の長さの半分（2分の1）に縮小して描くのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法において、正面図の真下に配置する図はどれか。', '["平面図","右側面図","底面図","背面図"]', 2, 2, '第三角法では、正面図の真下に底面図、真上に平面図、右側に右側面図を配置します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁で野菜を切る際、安定させるために行うべきことはどれか。', '["食材を丸いまま切る","食材の転がりやすい面を平らにして安定させる","包丁を左右に動かして切る","まな板を濡らさない"]', 1, 1, '食材が転がると危険です。安定した面を下にするか、平らな面を作ってから切るのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '計量スプーン大さじ1杯は何mlか。', '["5ml","10ml","15ml","20ml"]', 2, 1, '大さじ1は15ml、小さじ1は5mlです。調理の基本数値なので必ず覚えておきましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '食中毒予防の3原則に含まれないものはどれか。', '["つけない","ふやさない","やっつける","保存する"]', 3, 1, '食中毒予防の3原則は「細菌をつけない」「ふやさない」「やっつける」です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の加工方法で、ヤスリがけの際に行うべきことはどれか。', '["押し付ける時に力を入れる","引く時に力を入れる","往復で強くこする","ヤスリを浮かせて使う"]', 0, 2, 'ヤスリは押す時に削れるように刃がついています。引く時は力を抜くのが正しい使い方です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックの加工で、熱を加えて曲げ加工をする際に適した材料はどれか。', '["熱可塑性プラスチック","熱硬化性プラスチック","金属","木材"]', 0, 2, '熱可塑性プラスチックは熱で柔らかくなるため、加熱して曲げ加工を行うことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法で、正面図の右側に配置する図はどれか。', '["平面図","左側面図","右側面図","底面図"]', 2, 2, '第三角法では、正面から見た図の右側に右側面図を配置する決まりになっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '計量カップで液体を測る際、正しい見方はどれか。', '["上から見下ろす","目盛りと視線を水平にする","下から見上げる","斜めから見る"]', 1, 1, '液体を測る際は、目盛りと視線を水平にしないと誤差が生じます。必ず平らな場所に置いて測りましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '加熱調理の目的として誤っているものはどれか。', '["殺菌する","消化しやすくする","風味を良くする","栄養素をすべて破壊する"]', 3, 1, '加熱調理は殺菌や消化吸収を助けるために行います。栄養素を破壊することは目的ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '鉄の性質として誤っているものはどれか。', '["磁石につく","錆びにくい","熱を伝えやすい","加工しやすい"]', 1, 2, '鉄は空気中の酸素や水分と反応して錆びやすい性質があります。錆びを防ぐ処理が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'アルミニウムの性質として正しいものはどれか。', '["鉄より重い","磁石につく","軽くて錆びにくい","非常に硬い"]', 2, 2, 'アルミニウムは鉄に比べて軽く、表面に酸化被膜を作るため錆びにくいという特徴があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '製図で「中心線」を表す線の種類はどれか。', '["太い実線","細い実線","一点鎖線","破線"]', 2, 2, '製図において中心線は一点鎖線で描きます。外形線は太い実線、隠れ線は破線で描きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁の持ち方として最も適切なものはどれか。', '["柄だけを握る","刃の背に指を乗せる","柄を握り、人差し指を背に添える","刃先を強く握る"]', 2, 1, '柄をしっかり握り、人差し指を背に添えることで安定して切ることができます。刃先を握るのは危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '食中毒予防で「やっつける」に該当する行為はどれか。', '["手を洗う","加熱する","冷蔵庫に入れる","調理器具を消毒する"]', 1, 1, '中心部まで十分に加熱することで、細菌を死滅させることができます。これが「やっつける」にあたります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックの記号で「PE」は何を指すか。', '["ポリエチレン","ポリプロピレン","ポリスチレン","ポリ塩化ビニル"]', 0, 3, 'PEはポリエチレンの略称です。身近なプラスチック製品の素材としてよく使われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '等角図を描く際、水平線に対して何度傾けて軸を描くか。', '["30度","45度","60度","90度"]', 0, 2, '等角図では、水平線に対して左右30度ずつ傾けて軸を描きます。これにより120度の角度が作られます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法で、正面図の真上に配置する図はどれか。', '["平面図","底面図","右側面図","左側面図"]', 0, 2, '第三角法では、正面から見た図の真上に、上から見た図である平面図を配置します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '計量スプーン小さじ1杯は何mlか。', '["2ml","5ml","10ml","15ml"]', 1, 1, '小さじ1は5mlです。大さじ1（15ml）の3分の1の量になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の加工において、金属の板を切り出すのに適した道具はどれか。', '["金切りばさみ","のこぎり","カッター","ヤスリ"]', 0, 2, '薄い金属板を切るには金切りばさみを使用します。厚い場合は金属用のこぎりを使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックの性質として誤っているものはどれか。', '["電気を通しやすい","加工しやすい","軽い","腐食しにくい"]', 0, 2, 'プラスチックは電気を通しにくい絶縁体です。そのため電気製品の部品によく使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '製図で「隠れ線」を表す線の種類はどれか。', '["太い実線","細い実線","一点鎖線","破線"]', 3, 2, '見えない部分を表す隠れ線は破線（点線）で描くのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁で「かつらむき」をする際に最も適した包丁はどれか。', '["三徳包丁","菜切り包丁","ペティナイフ","パン切り包丁"]', 1, 3, '菜切り包丁は刃がまっすぐで、かつらむきや野菜の千切りに適した形をしています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '食中毒予防で「つけない」に該当する行為はどれか。', '["加熱する","冷蔵庫に入れる","手洗いをする","調理器具を煮沸する"]', 2, 1, '手洗いは細菌を食材や調理器具につけないための最も基本的な予防策です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の加工で、穴あけに使う道具はどれか。', '["ドリル","金槌","やすり","ペンチ"]', 0, 1, '金属に穴を開けるにはドリルやボール盤を使用します。金槌は叩く道具です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックを再利用することを何というか。', '["リサイクル","廃棄","埋め立て","焼却"]', 0, 1, 'プラスチックは環境負荷を下げるため、リサイクル（再資源化）が推奨されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '等角図のメリットはどれか。', '["奥行きが正確にわかる","立体の形が把握しやすい","正面図が一番大きく見える","製図が最も簡単である"]', 1, 2, '等角図は立体を斜めから見た形で描くため、全体像が把握しやすいというメリットがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法で、正面図の左側に配置する図はどれか。', '["平面図","底面図","左側面図","右側面図"]', 2, 2, '第三角法では、左から見た図は正面図の左側に配置します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '計量カップ1カップは何mlか。', '["100ml","200ml","250ml","500ml"]', 1, 1, '日本の調理における1カップは200mlです。計量カップの基本単位です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '加熱調理で「焼く」方法の説明として正しいものはどれか。', '["油の中で加熱する","水の中で加熱する","直接または間接的に熱を加えて加熱する","蒸気で加熱する"]', 2, 1, '焼くことは、熱源からの熱で食材を加熱する方法です。油を使うのは炒める、水を使うのは煮るです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の「導電性」とはどのような性質か。', '["熱を伝えやすい","電気を通しやすい","磁石につく","叩くと広がる"]', 1, 2, '導電性とは電気を通す性質のことです。銅やアルミニウムは導電性が高いため配線に使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '熱硬化性プラスチックの例はどれか。', '["ポリエチレン","ポリプロピレン","フェノール樹脂","ポリスチレン"]', 2, 3, 'フェノール樹脂は熱硬化性プラスチックの代表例です。電気のスイッチや鍋の取っ手に使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'キャビネット図の欠点はどれか。', '["奥行きが短く見える","立体の形がわからない","描くのが非常に難しい","正面が歪む"]', 0, 2, '奥行きを半分に縮小するため、実際の立体よりも奥行きが短く見えるという欠点があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁の刃の根元を何と呼ぶか。', '["切っ先","刃先","あご","背"]', 2, 2, '包丁の刃の根元部分は「あご」と呼ばれます。ここを使って野菜のヘタを取ったりします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '食中毒予防で「ふやさない」に該当する行為はどれか。', '["加熱する","冷蔵庫に入れる","手を洗う","まな板を洗う"]', 1, 1, '細菌は低温では増殖スピードが遅くなります。冷蔵庫に入れることは「ふやさない」ための対策です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の加工で、表面を滑らかにする道具はどれか。', '["やすり","ドリル","金槌","ペンチ"]', 0, 1, '金属のバリ取りや表面の仕上げにはやすりを使用します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックを加熱して型に流し込む成形方法を何というか。', '["射出成形","切削加工","鍛造","鋳造"]', 0, 3, '射出成形は溶かしたプラスチックを金型に流し込んで大量生産する代表的な方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '製図で「外形線」を表す線の種類はどれか。', '["太い実線","細い実線","一点鎖線","破線"]', 0, 2, '物の形をはっきりと示す外形線は、太い実線で描くのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁の刃先を何と呼ぶか。', '["あご","切っ先","背","柄"]', 1, 2, '包丁の先端部分は「切っ先」と呼ばれます。細かい作業をする時に使います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '加熱調理で「煮る」とはどのような状態か。', '["油で揚げる","水や出汁の中で加熱する","蒸気で加熱する","網の上で焼く"]', 1, 1, '煮ることは、水や調味液の中で食材を加熱する方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の性質として「光沢」があるが、この光沢を何というか。', '["金属光沢","ガラス光沢","真珠光沢","樹脂光沢"]', 0, 1, '金属特有の輝きを金属光沢といいます。磨くとより強く輝きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '熱可塑性プラスチックの例はどれか。', '["フェノール樹脂","ポリエチレン","エポキシ樹脂","メラミン樹脂"]', 1, 3, 'ポリエチレンは熱可塑性プラスチックです。レジ袋や容器などに広く使われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '等角図における奥行きの長さはどう描くか。', '["実際の長さのまま描く","半分にして描く","2倍にして描く","描かない"]', 0, 2, '等角図は3つの軸方向に実際の長さをそのまま描くため、形がわかりやすいのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法で、正面図の右上に配置する図はどれか。', '["平面図","右側面図","配置しない","底面図"]', 2, 2, '第三角法では、正面図の右上に図を配置することはありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '計量スプーンで粉末を計る際の正しい方法はどれか。', '["山盛りにして計る","すりきり一杯にする","軽く押さえて計る","適当にすくう"]', 1, 1, '粉末はすりきり一杯で計るのが基本です。山盛りだと正確な分量になりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '加熱調理で「蒸す」とはどのような状態か。', '["油で加熱する","水の中で加熱する","蒸気で加熱する","直火で加熱する"]', 2, 1, '蒸すことは、水蒸気の熱を利用して食材を加熱する方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属を接合する方法として一般的なものはどれか。', '["溶接","接着剤","粘着テープ","紐で縛る"]', 0, 2, '金属同士を強固に接合するには、熱で溶かしてくっつける溶接が用いられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックの加工で、板を切り出すのに適した道具はどれか。', '["プラスチック用カッター","金切りばさみ","やすり","金槌"]', 0, 2, 'プラスチック板は専用のカッターで溝を深くして折るか、プラスチック用のこぎりで切ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '製図で「寸法線」を表す線の種類はどれか。', '["太い実線","細い実線","一点鎖線","破線"]', 1, 2, '寸法線や寸法補助線は、図面を読みやすくするために細い実線で描きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '包丁の背を何と呼ぶか。', '["刃","峰（みね）","あご","切っ先"]', 1, 2, '包丁の刃の反対側の厚い部分を峰（みね）と呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '食中毒予防で、まな板を使い分ける目的は何か。', '["洗いやすくするため","交差汚染を防ぐため","見た目を良くするため","早く調理するため"]', 1, 2, '肉や魚の細菌が野菜に移ることを防ぐため、まな板を使い分けることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '金属の性質として「熱伝導性」があるが、これはどういう意味か。', '["熱を伝えやすい","熱を遮断する","熱で溶けやすい","熱で硬くなる"]', 0, 1, '熱伝導性とは熱をよく伝える性質のことです。鍋などに金属が使われる理由です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', 'プラスチックの成形方法で、型に流し込むことを何というか。', '["鋳造","射出成形","鍛造","圧延"]', 1, 3, 'プラスチックを加熱して溶かし、型に射出する成形方法を射出成形といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '等角図とキャビネット図の大きな違いは何か。', '["奥行きの描き方","正面図の描き方","線の太さ","使用する定規"]', 0, 2, '等角図は奥行きをそのまま描くのに対し、キャビネット図は奥行きを半分に縮小して描く点が異なります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '第三角法において、正面図・平面図・右側面図の3つを描く図法を何というか。', '["三面図","二面図","等角図","キャビネット図"]', 0, 2, '正面、上、横の3方向から見た図を配置するものを三面図と呼びます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_early_final', 'tech_home', '加熱調理で「揚げる」とはどのような状態か。', '["油の中で加熱する","水の中で加熱する","蒸気で加熱する","直火で加熱する"]', 0, 1, '揚げることは、高温の油の中で食材を加熱する方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培において、光合成に必要な「三大要素」に含まれないものはどれか。', '["窒素","リン酸","カリウム","カルシウム"]', 3, 1, '肥料の三大要素は窒素（葉や茎）、リン酸（花や実）、カリウム（根）です。カルシウムは微量要素であり、三大要素には含まれません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の生育において、葉や茎を大きくするために最も重要な肥料成分はどれか。', '["窒素","リン酸","カリウム","マグネシウム"]', 0, 1, '窒素は「葉肥」と呼ばれ、葉や茎の成長を促進する働きがあります。リン酸は花や実、カリウムは根を丈夫にする働きがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の病害虫対策として、最も適切でないものはどれか。', '["風通しを良くする","発生した害虫を早めに取り除く","同じ場所に同じ植物を毎年植え続ける","適切な水やりを行う"]', 2, 1, '同じ場所に同じ植物を植え続けると「連作障害」が起き、病害虫が発生しやすくなります。場所を変える輪作が推奨されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '天然繊維のうち、植物由来のものはどれか。', '["綿（コットン）","ウール","シルク","ポリエステル"]', 0, 1, '綿は植物の種子から採れる繊維です。ウールは動物の毛、シルクは蚕の繭、ポリエステルは化学繊維です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示記号で、アイロンの底面温度を「中」に設定することを表す点はいくつあるか。', '["1つ","2つ","3つ","なし"]', 1, 2, 'アイロンの点は温度を示します。1つは低温、2つは中温、3つは高温を表します。点は多いほど高温になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いの基本である、針目を一定にして縫う縫い方はどれか。', '["なみ縫い","本返し縫い","半返し縫い","まつり縫い"]', 0, 1, 'なみ縫いは最も基本的な縫い方で、針目を一定にして縫い進めます。本返し縫いは丈夫に縫うために用いられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維の特徴として、誤っているものはどれか。', '["シワになりにくい","吸湿性が非常に高い","乾きが早い","熱に弱いものがある"]', 1, 2, '化学繊維は一般的に吸湿性が低く、蒸れやすいという性質があります。綿などの天然繊維の方が吸湿性は高いです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、土壌の酸度を調整するために使われるものはどれか。', '["苦土石灰","堆肥","化成肥料","腐葉土"]', 0, 2, '日本の土壌は酸性に傾きやすいため、苦土石灰を混ぜてアルカリ性に調整し、植物が育ちやすい環境を作ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', 'エネルギー変換の観点で、太陽光発電は何から何への変換か。', '["光エネルギーから電気エネルギー","熱エネルギーから電気エネルギー","運動エネルギーから電気エネルギー","化学エネルギーから電気エネルギー"]', 0, 1, '太陽光発電は、光エネルギーを直接電気エネルギーに変換する仕組みです。火力発電は熱エネルギーを利用します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '裁縫で、布の端がほつれないようにする処理を何というか。', '["裁ち目かがり","しつけ縫い","玉止め","玉結び"]', 0, 1, '裁ち目かがりは、布の切り口がほつれないように、端をかがり縫いする技法です。ミシンでも手縫いでも行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '肥料の三大要素のうち、実や花を育てるために必要なものはどれか。', '["リン酸","窒素","カリウム","カルシウム"]', 0, 1, 'リン酸は「実肥」と呼ばれ、花や実の成長を助けます。植物のエネルギー代謝にも深く関わっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '次のうち、動物繊維に分類されるものはどれか。', '["ウール","綿","麻","ポリエステル"]', 0, 1, 'ウール（羊毛）やシルク（絹）は動物の体から採れるタンパク質系の繊維です。綿や麻は植物繊維です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、桶にバツ印がついている記号は何を表しているか。', '["家庭での洗濯禁止","手洗い可能","漂白剤使用不可","乾燥機使用不可"]', 0, 2, '桶のマークは洗濯を表し、そこにバツ印がある場合は家庭での洗濯ができないことを意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で「間引き」を行う主な目的はどれか。', '["日光や養分を十分に確保するため","害虫を増やすため","肥料を節約するため","土を柔らかくするため"]', 0, 1, '間引きは、密集した苗を減らすことで、残った苗に日光や養分が行き渡るようにし、丈夫に育てるために行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いの「本返し縫い」の特徴はどれか。', '["非常に丈夫で、ミシンの縫い目に近い","縫い目が重ならず、速く縫える","飾り縫いとして使われる","布をまつる時に使う"]', 0, 2, '本返し縫いは、一針戻って縫うため縫い目が重なり、非常に強度が高い縫い方です。手縫いの中で最も丈夫です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維であるナイロンの主な特徴はどれか。', '["非常に強度が強く、摩擦に強い","吸湿性が非常に高い","熱に非常に強い","天然繊維より重い"]', 0, 2, 'ナイロンは非常に丈夫で摩擦に強いため、ストッキングやスポーツウェア、バッグなどに広く使われています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物が光合成を行うために必要なものはどれか。', '["水、二酸化炭素、光","酸素、窒素、光","水、酸素、肥料","二酸化炭素、肥料、酸素"]', 0, 1, '光合成は、水と二酸化炭素を原料とし、光エネルギーを使って酸素とデンプン（養分）を作り出す働きです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、三角形の中に斜線が入っている記号は何を表しているか。', '["酸素系漂白剤のみ使用可能","塩素系漂白剤のみ使用可能","漂白剤は一切使用不可","アイロン可能"]', 0, 2, '三角形は漂白を表します。中に斜線がある場合は酸素系漂白剤のみ使用可能、塗りつぶしは漂白不可を意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の根が養分を吸収する際、最も重要な役割を果たすのはどれか。', '["根毛","主根","側根","茎"]', 0, 2, '根の先端付近にある細かい「根毛」が、土壌中の水と養分を効率よく吸収する役割を担っています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、布の端を折って縫い留める際に使われる縫い方はどれか。', '["まつり縫い","なみ縫い","本返し縫い","半返し縫い"]', 0, 2, 'まつり縫いは、ズボンの裾上げや布の端を縫い留める際に、表から縫い目が見えにくいように縫う方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', 'エネルギー変換において、電熱器は何から何への変換か。', '["電気エネルギーから熱エネルギー","熱エネルギーから電気エネルギー","光エネルギーから熱エネルギー","運動エネルギーから電気エネルギー"]', 0, 1, '電熱器は電気を流すことで抵抗により熱を発生させるため、電気エネルギーを熱エネルギーに変換しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、土の中に空気を送り込み、根の成長を助ける作業を何というか。', '["中耕","間引き","追肥","摘心"]', 0, 2, '中耕は、土の表面を耕して空気を入れ、根の呼吸を助けたり、雑草を抑えたりする作業です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '次のうち、再生繊維に分類されるものはどれか。', '["レーヨン","ポリエステル","ナイロン","アクリル"]', 0, 2, 'レーヨンは木材パルプなどを薬品で溶かして繊維状に再生したもので、再生繊維と呼ばれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '肥料の三大要素のうち、根を丈夫にするために必要なものはどれか。', '["カリウム","窒素","リン酸","カルシウム"]', 0, 1, 'カリウムは「根肥」と呼ばれ、根の発育を助け、病害虫への抵抗力を高める働きがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、玉結びを作る際に指に糸を巻きつける回数は一般的に何回か。', '["1〜2回","5回以上","10回","巻く必要はない"]', 0, 1, '玉結びは、糸を指に1〜2回巻きつけてねじり、それを引き抜くことで作ります。多すぎると結び目が大きすぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の病害虫対策として「コンパニオンプランツ」を植える目的は何か。', '["病害虫を寄せ付けないため","肥料を増やすため","光合成を促進するため","土をアルカリ性にするため"]', 0, 2, 'コンパニオンプランツは、相性の良い植物を一緒に植えることで、病害虫を防いだり成長を助けたりする手法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、四角の中に丸がある記号は何を表しているか。', '["タンブル乾燥","自然乾燥","アイロン仕上げ","ドライクリーニング"]', 0, 2, '四角の中に丸がある記号は、回転式乾燥機（タンブル乾燥）を表します。中に点がある場合は温度指定を意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維のポリエステルの特徴として、正しいものはどれか。', '["シワになりにくく、丈夫である","非常に燃えやすい","水に溶けやすい","アイロンがけが必須である"]', 0, 2, 'ポリエステルは合成繊維の中で最も生産量が多く、シワになりにくく、丈夫で洗濯後の乾きも早いのが特徴です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、成長の途中で肥料を追加することを何というか。', '["追肥","元肥","中耕","間引き"]', 0, 1, '元肥は植え付け前に土に混ぜる肥料、追肥は成長に合わせて途中で与える肥料のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、針に糸を通した後に糸の端をまとめて結ぶのは何のためか。', '["布から糸が抜けないようにするため","糸を丈夫にするため","縫い目を綺麗にするため","糸の節約のため"]', 0, 1, '玉結びをすることで、縫い始めに糸が布から抜けてしまうことを防ぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', 'エネルギー変換において、モーターは何から何への変換か。', '["電気エネルギーから運動エネルギー","運動エネルギーから電気エネルギー","熱エネルギーから電気エネルギー","光エネルギーから運動エネルギー"]', 0, 1, 'モーターは電気を流すと回転する装置であり、電気エネルギーを運動（回転）エネルギーに変換しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、日当たりを調整するために行うことはどれか。', '["遮光ネットの使用","肥料の量を増やす","水やりを控える","土を深く耕す"]', 0, 2, '直射日光が強すぎる場合や、日陰を好む植物の場合、遮光ネットを使用して光の量を調整します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、干し方の記号で「日陰でつり干し」を表すのはどれか。', '["四角の中に斜線と縦線","四角の中に横線","四角の中に丸","四角の中にバツ"]', 0, 2, '四角の中に縦線はつり干し、左上の斜線は日陰を意味します。これらを組み合わせて干し方を指定します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、病害虫の発生を抑えるために最も重要なことはどれか。', '["観察して早期発見・対処する","毎日大量の肥料を与える","常に水をかけ続ける","日光を完全に遮断する"]', 0, 1, '病害虫は放置すると急速に広がるため、日々の観察で異常を早く見つけ、手で取り除くなどの対処が不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いの「半返し縫い」の特徴はどれか。', '["なみ縫いより丈夫で、表の縫い目が半分重なる","なみ縫いと同じ強度である","非常に縫い目が荒い","布を重ねる必要がない"]', 0, 2, '半返し縫いは、半分戻って縫うため、なみ縫いよりも丈夫で、表から見ると縫い目が少し重なって見えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維の「アクリル」の主な特徴はどれか。', '["ウールに似た風合いで保温性が高い","シルクのように光沢がある","非常に硬くて重い","水に溶ける"]', 0, 2, 'アクリルは合成繊維の中でも柔らかく、ウールに似た風合いを持つため、セーターや毛布などに使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培において、土の表面が乾いたときに水やりを行う理由は何か。', '["根の呼吸を助け、根腐れを防ぐため","肥料を溶かすため","日光を反射させるため","雑草を育てるため"]', 0, 1, '常に土が湿っていると根が窒息して腐る「根腐れ」の原因になります。土の乾燥と湿潤のメリハリが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、漂白剤が「使用不可」の記号はどれか。', '["三角形にバツ印","三角形のみ","三角形に斜線","三角形に点"]', 0, 2, '三角形は漂白を表し、そこにバツ印がついている場合は、塩素系・酸素系問わず漂白剤の使用が禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', 'エネルギー変換において、発電機は何から何への変換か。', '["運動エネルギーから電気エネルギー","電気エネルギーから運動エネルギー","熱エネルギーから電気エネルギー","光エネルギーから熱エネルギー"]', 0, 2, '発電機はコイルと磁石を動かす（運動させる）ことで電気を生み出すため、運動エネルギーを電気エネルギーに変換します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、布の端を始末する「裁ち目かがり」の縫い目の形はどれか。', '["斜めの縫い目が並ぶ形","直線が並ぶ形","円を描く形","縫い目が見えない形"]', 0, 2, '裁ち目かがりは、布の端を包み込むように斜めに糸を渡して縫うため、斜めの縫い目が並んだ形になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で「摘心」を行う目的はどれか。', '["脇芽を伸ばして収穫量を増やすため","根を深くするため","害虫を誘引するため","肥料を減らすため"]', 0, 2, '摘心は茎の先端を切ることで、成長の勢いを脇芽に向け、枝分かれを増やして花や実の数を増やす作業です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '天然繊維である「麻」の特徴として、正しいものはどれか。', '["吸湿・速乾性に優れ、夏物衣料に向く","非常に保温性が高い","シワが全くつかない","動物の毛から作られる"]', 0, 2, '麻は植物繊維で、吸湿性と通気性が非常に高く、乾きも早いため、夏の衣類や寝具によく使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、アイロンの温度設定で「高温」を表す点はいくつあるか。', '["3つ","1つ","2つ","なし"]', 0, 2, 'アイロンの記号内の点は温度を示し、1つは低温（110℃）、2つは中温（150℃）、3つは高温（200℃）です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培において、肥料の「三大要素」をすべて答えよ。', '["窒素・リン酸・カリウム","窒素・酸素・カリウム","リン酸・カルシウム・マグネシウム","窒素・リン酸・鉄"]', 0, 1, '肥料の三大要素は窒素（N）、リン酸（P）、カリウム（K）です。これらは植物の成長に最も多く必要とされます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、針に糸を通すとき、糸の長さはどのくらいが適切か。', '["腕の長さ程度（50〜60cm）","2メートル以上","10cm程度","どれだけ長くても良い"]', 0, 1, '糸が長すぎると絡まりやすく、縫いにくくなります。腕の長さ程度が最も扱いやすく、作業効率が良いです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維の「ポリエステル」の原料は主に何か。', '["石油","羊毛","綿花","蚕の繭"]', 0, 2, 'ポリエステルなどの合成繊維は、主に石油を原料として化学的に合成された繊維です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物が病気にかかったとき、最初に行うべき適切な対応はどれか。', '["病気の部分を取り除く","すぐに大量の殺虫剤をまく","植物を全て引き抜く","何もせず放置する"]', 0, 2, '病気の部分を早く取り除くことで、感染の拡大を防ぐことができます。放置すると全体に広がってしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、手洗いが可能であることを示す記号はどれか。', '["桶の中に手を入れているマーク","桶にバツ印","四角に丸","三角形のみ"]', 0, 2, '桶の中に手を入れているマークは、家庭での手洗いが可能であることを示しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、土壌が酸性になりすぎると起こる問題はどれか。', '["養分の吸収が悪くなる","植物が早く育つ","害虫が減る","水やりが不要になる"]', 0, 2, '多くの植物は弱酸性から中性の土壌を好みます。酸性が強すぎると、必要な養分を根から吸収しにくくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで、玉止めをする際、針に糸を何回巻きつけるか。', '["2〜3回","10回","巻く必要はない","1回のみ"]', 0, 1, '玉止めは、針に糸を2〜3回巻きつけてねじり、それを引き抜くことで作ります。多すぎると結び目が大きくなりすぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', 'エネルギー変換において、白熱電球は何から何への変換か。', '["電気エネルギーから光と熱エネルギー","光エネルギーから電気エネルギー","運動エネルギーから光エネルギー","熱エネルギーから運動エネルギー"]', 0, 1, '白熱電球は電気を流してフィラメントを高温にし、光らせるため、電気エネルギーを光と熱に変換します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で「支柱立て」を行う主な目的はどれか。', '["倒伏を防ぎ、成長を助けるため","害虫を捕まえるため","日光を遮るため","肥料を吸収しやすくするため"]', 0, 1, '背が高くなる植物や実が重い植物は、風や自身の重さで倒れやすいため、支柱を立てて支えます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '天然繊維の「シルク」の最大の特徴はどれか。', '["美しい光沢と滑らかな肌触り","非常に安価で丈夫","シワが全くつかない","水に非常に強い"]', 0, 2, 'シルクは蚕の繭から採れる動物繊維で、上品な光沢と滑らかな肌触りが特徴の高級素材です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、乾燥機（タンブル乾燥）が「禁止」の記号はどれか。', '["四角の中に丸があり、バツ印がついている","四角の中に丸がある","四角のみ","三角形にバツ印"]', 0, 2, '四角の中に丸があるのがタンブル乾燥の記号で、そこにバツ印がついている場合は使用禁止を意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培で、土壌の通気性を良くするために混ぜるものはどれか。', '["腐葉土や堆肥","砂利","塩","プラスチック"]', 0, 2, '腐葉土や堆肥を混ぜると、土がふかふかになり、空気や水が通りやすくなるため、根の成長が良くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '手縫いで「しつけ縫い」を行う目的は何か。', '["縫い合わせる布を仮止めするため","本縫いの強度を上げるため","飾りとして使うため","布のほつれを防ぐため"]', 0, 1, 'しつけ縫いは、本縫いをする前に布がずれないように大きく縫い留めておく仮縫いのことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '化学繊維の「ポリウレタン」の主な特徴はどれか。', '["伸縮性が非常に高い","熱に非常に強い","吸湿性が非常に高い","非常に硬い"]', 0, 2, 'ポリウレタンはゴムのように伸縮性に優れており、ストレッチ素材の衣類やスポーツウェアによく使われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '植物の栽培において、肥料の与えすぎ（肥料焼け）が起きるとどうなるか。', '["根が傷み、枯れることがある","植物が急激に巨大化する","花が咲かなくなる","害虫が一切つかなくなる"]', 0, 2, '肥料を過剰に与えると、土壌の濃度が高まりすぎて根から水分が奪われ、植物が枯れてしまう「肥料焼け」が起きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'tech_home', '洗濯表示で、アイロンの記号にバツ印がついているのは何を表しているか。', '["アイロン仕上げ禁止","低温アイロンのみ可能","高温アイロンのみ可能","スチームアイロンのみ可能"]', 0, 2, 'アイロンの記号にバツ印がついている場合は、アイロンがけ自体が禁止されていることを意味します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '2進数の「101」を10進数に変換するといくつになるか。', '["5","6","7","4"]', 0, 1, '2進数の101は、(1×2の2乗)＋(0×2の1乗)＋(1×2の0乗)＝4＋0＋1＝5となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '10進数の「6」を2進数で表すとどうなるか。', '["101","110","111","100"]', 1, 1, '6を2で割っていくと、6÷2=3余り0、3÷2=1余り1、1÷2=0余り1となり、余りを逆から並べると110になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'コンピュータ内部で情報を扱う最小単位は何か。', '["バイト","ビット","キロバイト","メガバイト"]', 1, 1, 'ビット(bit)は2進数の1桁分で、コンピュータが情報を処理する最小の単位です。8ビットで1バイトになります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '他人の著作物を無断でインターネットに公開する行為が違反している法律はどれか。', '["著作権法","個人情報保護法","不正アクセス禁止法","消費者契約法"]', 0, 1, '著作権法は、著作物を作った人の権利を守る法律です。無断公開は複製権や公衆送信権の侵害にあたります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'インターネット上の情報の信頼性を判断する方法として不適切なものはどれか。', '["発信元を確認する","複数の情報源を比較する","更新日を確認する","一番上に表示されたサイトを信じる"]', 3, 1, '検索結果の上位は広告やSEO対策によるものであり、必ずしも正確とは限りません。情報の裏付けをとることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'フローチャートにおいて、処理の開始や終了を表す記号はどれか。', '["長方形","ひし形","端子（楕円形）","平行四辺形"]', 2, 1, 'フローチャートの開始と終了は、角が丸い長方形（端子）で表します。ひし形は条件判断、長方形は処理を表します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'フローチャートで「もし〜ならば」という条件判断を表す記号はどれか。', '["長方形","ひし形","楕円形","矢印"]', 1, 1, 'ひし形は分岐（条件判断）を表します。ここから「はい」と「いいえ」の方向に処理が分かれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '住居の換気において、シックハウス症候群を防ぐために義務付けられている設備はどれか。', '["24時間換気システム","エアコン","床暖房","照明器具"]', 0, 2, '建築基準法により、ホルムアルデヒド等の化学物質による健康被害を防ぐため、24時間換気設備の設置が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '訪問販売で契約してしまったが、後で解約したい場合に利用できる制度はどれか。', '["クーリング・オフ","リコール","PL法","消費者契約法"]', 0, 1, 'クーリング・オフは、訪問販売などの特定の取引において、一定期間内であれば無条件で契約を解除できる制度です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'クーリング・オフができる期間として、訪問販売の場合の原則は何日間か。', '["7日間","8日間","14日間","30日間"]', 1, 2, '訪問販売の場合、法定の書面を受け取った日から起算して8日間以内であればクーリング・オフが可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '採光を良くするために、窓の配置として最も効果的なのはどれか。', '["北側に大きな窓を作る","南側に大きな窓を作る","窓を小さくする","窓を一切作らない"]', 1, 1, '北半球では太陽は南側を通るため、南側に窓を配置すると長時間安定した自然光を取り入れることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '2進数の「111」を10進数に変換するといくつになるか。', '["3","6","7","8"]', 2, 2, '(1×4)＋(1×2)＋(1×1)＝4＋2＋1＝7となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '10進数の「10」を2進数で表すとどうなるか。', '["1001","1010","1100","1110"]', 1, 2, '10÷2=5余り0、5÷2=2余り1、2÷2=1余り0、1÷2=0余り1。下から並べて1010となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '著作権が発生するタイミングとして正しいものはどれか。', '["作品を登録した時","作品を公表した時","作品を創作した時","著作権マークを付けた時"]', 2, 2, '著作権は「無方式主義」を採用しており、作品を作った瞬間に自動的に発生します。登録や申請は不要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'SNSで他人の悪口を書き込む行為が該当する可能性が高いものはどれか。', '["著作権侵害","誹謗中傷","不正アクセス","ライセンス違反"]', 1, 1, 'SNSでの悪口は誹謗中傷にあたり、名誉毀損や侮辱罪に問われる可能性がある重大な問題です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'フローチャートで、データの入力や出力を表す記号はどれか。', '["長方形","ひし形","平行四辺形","楕円形"]', 2, 2, '平行四辺形は、データの入力や出力（表示など）を表す際に使用される標準的な記号です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '住居の「通風」を良くするために有効な窓の配置はどれか。', '["窓を1つだけにする","対面する壁に窓を設ける","窓を全て閉め切る","窓を小さくする"]', 1, 2, '風の入り口と出口を作ることが重要です。対面する壁に窓を設けることで、空気の通り道ができ換気効率が上がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '通信販売（ネットショッピング）でクーリング・オフが適用されない理由として正しいものはどれか。', '["自分で選んで申し込んだから","安すぎるから","返品不可と書いてあるから","法律で決まっているから"]', 0, 2, '通信販売は自分の意思でじっくり選んで購入できるため、法律上のクーリング・オフ制度は適用されません（返品特約を確認しましょう）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '2進数の「1000」を10進数に変換するといくつになるか。', '["4","8","10","16"]', 1, 2, '1×2の3乗＝8となります。2進数の1000は10進数の8です。', NULL);
