INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', 'フローチャートの矢印（フロー線）が示すものは何か。', '["処理の順序","データの量","条件の数","エラーの発生"]', 0, 1, '矢印は処理の流れ（順序）を示します。プログラムがどの順番で実行されるかを視覚的に表すものです。', NULL);
