INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '2進数の「11」を10進数に変換するといくつになるか。', '["2","3","4","11"]', 1, 1, '(1×2)＋(1×1)＝2＋1＝3となります。', NULL);
