INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_final', 'tech_home', '著作権者の許可なく利用できる例外的なケースはどれか。', '["学校の授業で使う場合","友達に配る場合","SNSにアップする場合","ブログに載せる場合"]', 0, 2, '著作権法では、学校教育の場など一定の条件下では、著作権者の許可なく著作物を利用できる規定があります。', NULL);
