INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「けふ」を現代仮名遣いに直すとどうなるか。', '["けう","きょう","けふ","けお"]', 1, 1, '「けふ」の「ふ」は語尾にあるため「う」と読みますが、歴史的仮名遣いでは「きょう」と発音します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』のジャンルは何か。', '["物語","随筆","日記","説話"]', 0, 1, '『竹取物語』は日本最古の物語文学であり、かぐや姫を主人公とした空想的な物語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』の冒頭「今は昔、竹取の翁といふものありけり」の「今は昔」の意味は何か。', '["今となっては昔のことだが","現代の昔","昔のことだが","今から見れば昔のことである"]', 3, 2, '「今は昔」は物語の定型句で、「今となっては昔のことであるが」という回想のニュアンスを含みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「レ点」の読み方のルールはどれか。', '["下の字を先に読む","上の字を先に読む","飛ばして読む","一字飛ばして読む"]', 0, 1, 'レ点は「返り点」の一種で、すぐ下の字と上の字を入れ替えて読む（下の字を先に読む）指示です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「一二点」の読み方のルールはどれか。', '["一から二へ戻る","二から一へ戻る","一と二を同時に読む","一を飛ばして二を読む"]', 0, 1, '一二点は、一のついた字を先に読み、二のついた字へ戻って読むという順序を示す記号です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '故事成語「矛盾」の由来となった武器は何か。', '["剣と盾","矛と盾","弓と矢","槍と鎧"]', 1, 1, '楚の商人が「どんな盾も突き通す矛」と「どんな矛も防ぐ盾」を売った話から、つじつまが合わないことを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「歴史的仮名遣い」において、語頭以外の「は・ひ・ふ・へ・ほ」はどう読むか。', '["そのまま読む","わ・い・う・え・お","は・ひ・ふ・へ・ほ","あ・い・う・え・お"]', 1, 1, '語中・語尾の「は・ひ・ふ・へ・ほ」は、現代仮名遣いでは「わ・い・う・え・お」と読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』の主人公、かぐや姫を見つけたのは誰か。', '["竹取の翁","帝","石作皇子","車持皇子"]', 0, 1, '竹の中から光る竹を見つけ、その中にいた小さな女の子を翁が連れ帰って育てました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文で、返り点がない場合はどう読むか。', '["上から下へ読む","下から上へ読む","飛ばして読む","右から左へ読む"]', 0, 1, '返り点がない場合は、日本語の語順に従わず、上から下へそのまま読み下していきます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「故事成語」の説明として正しいものはどれか。', '["現代のニュースから生まれた言葉","中国の古い出来事から生まれた言葉","日本の物語から生まれた言葉","外国の詩から生まれた言葉"]', 1, 1, '故事成語は、中国の歴史書や古典に記された出来事（故事）を由来とする、教訓やたとえを含む言葉です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「ゐ」や「ゑ」の現代仮名遣いでの読み方はどれか。', '["い・え","うぃ・うぇ","い・い","え・え"]', 0, 2, '歴史的仮名遣いの「ゐ」は「い」、「ゑ」は「え」と読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』において、かぐや姫が求婚者に出した条件は何に関連するものか。', '["宝物","歌","踊り","料理"]', 0, 2, 'かぐや姫は、5人の貴公子に対して「仏の御石の鉢」などの宝物を持ってくるよう難題を出しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「再読文字」とは何か。', '["二回繰り返して読む文字","二回に分けて読む文字","二通りに読める文字","二回読む必要がある文字"]', 3, 3, '再読文字は、一度目は返り点に従って読み、二度目は送り仮名として読む文字のことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「蛇足」の故事成語が意味することは何か。', '["余計なもの","必要なもの","美しいもの","速いもの"]', 0, 2, '蛇の絵に足を描き足したことで失敗した話から、余計なことをしてかえって台無しにすることを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「いふ」を現代仮名遣いに直すとどうなるか。', '["いう","いふ","いお","いゆ"]', 0, 1, '語中の「ふ」は「う」と読むため、「いふ」は「いう」となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』の作者は誰か。', '["紫式部","清少納言","不明","在原業平"]', 2, 2, '『竹取物語』は作者不詳の物語です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「レ点」が二つ重なっている場合（＝二レ点）、どう読むか。', '["二つ飛ばして戻る","二つ下の字から順に遡って読む","無視して読む","一番下の字を先に読む"]', 1, 3, '二レ点は、二つ下の字から一つ下の字、そして元の字へと遡って読む指示です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「五十歩百歩」の故事成語が意味することは何か。', '["大きな差があること","ほとんど変わらないこと","進歩していること","距離を測ること"]', 1, 2, '戦場で50歩逃げた者が100歩逃げた者を笑った話から、程度の差はあっても本質的には同じであることを指します。', NULL);
