INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「ひ」を現代仮名遣いで読むとどうなるか。', '["ひ","い","し","ち"]', 1, 1, '語中・語尾の「ひ」は「い」と読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』で、かぐや姫が昇天する場所はどこか。', '["月","太陽","星","海"]', 0, 1, 'かぐや姫は月の住人であり、最後には月に帰っていきます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「レ点」の読み順として正しいのはどれか。', '["A Bレ → B A","Aレ B → B A","A Bレ → A B","Aレ B → A B"]', 0, 2, 'レ点は下の字を先に読むため、Bにレ点があればBを先に読み、Aを後に読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「登竜門」の故事成語が意味することは何か。', '["難しい試験","成功への入り口","高い門","竜の住処"]', 1, 2, '竜門という急流を登りきった魚が竜になるという伝説から、成功のための関門を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「む」を現代仮名遣いで読むとどうなるか。', '["む","う","ん","む"]', 0, 1, '歴史的仮名遣いの「む」は、現代仮名遣いでもそのまま「む」と読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「かぐや姫」という名前の由来は何か。', '["竹が光っていたから","美しいから","月の人だから","翁が名付けたから"]', 0, 2, '光り輝く竹の中にいたため、「光る竹」から「かぐや姫」と呼ばれるようになりました。', NULL);
