INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「一二点」の「一」の字を読んだ後、次はどこを読むか。', '["二の字","一の字の次の字","文の終わり","レ点があればレ点"]', 1, 2, '一二点は、一の字を読んだ後、その間の字を順に読み、最後に二の字へ戻ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「塞翁が馬」の故事成語が意味することは何か。', '["馬が逃げること","人生の幸不幸は予測できないこと","馬を飼うこと","塞翁という人"]', 1, 2, '馬が逃げたことが幸運につながった話から、人生の幸不幸は予測できないことを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「くわし」を現代仮名遣いに直すとどうなるか。', '["くわし","かし","くあし","くわし"]', 0, 3, '「くわし」は歴史的仮名遣いでも現代仮名遣いでも「くわし」と書きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』の貴公子たちが求めた宝物として、正しいものはどれか。', '["燕の子安貝","竜の首の玉","火鼠の皮衣","すべて正しい"]', 3, 2, 'かぐや姫は、燕の子安貝、竜の首の玉、火鼠の皮衣など、入手困難な宝物を要求しました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文で「レ点」の次に「一二点」がある場合、どちらを先に処理するか。', '["レ点","一二点","同時","文脈による"]', 0, 3, 'レ点はその場での入れ替えを優先し、その後、一二点に従って大きな順序で戻ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「画竜点睛」の故事成語が意味することは何か。', '["竜の絵を描くこと","最後の仕上げをして完成させること","目を入れること","竜を呼ぶこと"]', 1, 2, '竜の絵に最後に瞳を描き入れたら竜が飛び去った話から、最後の仕上げを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「わう」を現代仮名遣いに直すとどうなるか。', '["おう","わう","わお","おう"]', 0, 2, '歴史的仮名遣いの「わう」は、現代仮名遣いでは「おう」と読みます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '『竹取物語』の帝は、かぐや姫に対してどのような態度をとったか。', '["求婚した","追い出した","無視した","殺そうとした"]', 0, 2, '帝はかぐや姫の美しさを聞きつけ、求婚しましたが、かぐや姫は断りました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '漢文の「レ点」の読み順で、AレBとある場合、どう読むか。', '["B A","A B","飛ばす","A B A"]', 0, 1, 'レ点は下の字（B）を先に読み、上の字（A）を後に読む指示です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('junior_1_late_mid', 'japanese', '「傍若無人」の故事成語が意味することは何か。', '["人がいないように振る舞うこと","自分勝手に振る舞うこと","傍らに人がいること","無人島に行くこと"]', 1, 2, '傍らに人がいないかのように振る舞うことから、自分勝手で無遠慮な態度を指します。', NULL);
